import { Book } from "@/lib/types";

export const acts: Book = {
  id: "acts",
  name: "Apostelgeschichte",
  shortName: "Apg",
  testament: "new",
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "Den ersten Bericht* habe ich verfasst, Theophilus, von allem, was Jesus angefangen hat, zu tun und auch zu lehren*,", heading: "Vorwort1", footnotes: ["das Evangelium nach Lukas", "℘ Lk 1,3"] },
      { number: 2, text: "bis zu dem Tag, an dem er in den Himmel aufgenommen wurde*, nachdem er den Aposteln, die er sich auserwählt*, durch den Heiligen Geist Befehl gegeben hatte.", footnotes: ["℘ V. 9", "℘ Lk 6,13"] },
      { number: 3, text: "Diesen hat er sich auch nach seinem Leiden in vielen sicheren Kennzeichen lebendig dargestellt, indem er sich vierzig Tage hindurch von ihnen sehen ließ* und über die Dinge redete, die das Reich* Gottes betreffen*.", footnotes: ["℘ Kap. 10,40.41; 13,31; 1Kor 15,5", "o. die Königsherrschaft", "℘ Kap. 19,8; 28,23"] },
      { number: 4, text: "Und als er mit ihnen versammelt war, befahl er ihnen, sich nicht von Jerusalem zu entfernen*, sondern auf die Verheißung des Vaters zu warten — die ihr, sagte er, von mir gehört habt*;", heading: "Jesu Himmelfahrt", footnotes: ["℘ Lk 24,49", "℘ Kap. 2,33; Joh 14,16"] },
      { number: 5, text: "denn Johannes taufte mit Wasser*, ihr aber werdet mit* Heiligem Geist getauft werden* nach diesen wenigen* Tagen*.", footnotes: ["℘ Mt 3,11", "w. in", "℘ Kap. 11,16; Joh 1,33; 1Kor 12,13", "w. nicht vielen", "℘ Kap. 2,1-4"] },
      { number: 6, text: "Sie nun, als sie zusammengekommen waren, fragten ihn und sagten: Herr, stellst du in dieser Zeit für Israel das Reich* wieder her*?", footnotes: ["o. die Königsherrschaft", "℘ Jer 23,5.6; Hes 37,21-27; Dan 7,27; Lk 17,20"] },
      { number: 7, text: "Er sprach zu ihnen: Es ist nicht eure Sache, Zeiten oder Zeitpunkte* zu wissen, die der Vater in seiner eigenen Vollmacht festgesetzt hat*.", footnotes: ["℘ 1Thes 5,1", "℘ Mt 24,36"] },
      { number: 8, text: "Aber ihr werdet Kraft empfangen, wenn der Heilige Geist auf euch gekommen ist; und ihr werdet meine Zeugen sein*, sowohl in Jerusalem* als auch in ganz Judäa und Samaria* und bis an das Ende der Erde*.", footnotes: ["℘ Kap. 2,32; 4,33; 5,32; 13,31; Joh 15,27", "℘ Lk 24,47", "℘ Kap. 8,14", "℘ Kap. 10,39; Röm 10,18"] },
      { number: 9, text: "Und als er dies gesagt hatte, wurde er vor ihren Blicken* emporgehoben, und eine Wolke nahm ihn auf vor ihren Augen weg*.", footnotes: ["w. indem sie es sahen", "℘ Mk 16,19; Offb 11,12"] },
      { number: 10, text: "Und als sie gespannt zum Himmel schauten, wie er auffuhr, siehe, da standen zwei Männer in weißen Kleidern bei ihnen*,", footnotes: ["℘ Kap. 10,30; Lk 24,4"] },
      { number: 11, text: "die auch sprachen: Männer von Galiläa, was steht ihr und seht hinauf zum Himmel? Dieser Jesus, der von euch weg in den Himmel aufgenommen worden ist, wird so kommen*, wie ihr ihn habt hingehen sehen in den Himmel*.", footnotes: ["℘ Kap. 3,20; Joh 14,3", "℘ Mt 24,30"] },
      { number: 12, text: "Da kehrten sie nach Jerusalem zurück* von dem Berg, welcher Ölberg heißt, der nahe bei Jerusalem ist*, einen Sabbatweg* entfernt.", footnotes: ["℘ Lk 24,52", "℘ Sach 14,4", "d. i. die Strecke, die ein Israelit am Sabbat zurücklegen durfte, etwa 1 km (vgl. 2Mo 16,29)"] },
      { number: 13, text: "Und als sie hineingekommen waren, stiegen sie hinauf in den Obersaal, wo sie sich aufzuhalten pflegten: sowohl Petrus als Johannes und Jakobus und Andreas, Philippus und Thomas, Bartholomäus und Matthäus, Jakobus, der Sohn des Alphäus, und Simon, der Eiferer*, und Judas, der Sohn des Jakobus*.", footnotes: ["griech. Zelotes, d. h. ein (ehemaliger) Anhänger der Zelotenpartei; die Zeloten wollten die röm. Herrschaft mit Gewalt beseitigen; vgl. auch Anm. zu Mt 10,4", "℘ Mt 10,2-4"] },
      { number: 14, text: "Diese alle verharrten einmütig im Gebet* mit einigen Frauen* und Maria, der Mutter Jesu, und mit seinen Brüdern*.", footnotes: ["℘ Kap. 2,42; 6,4; Lk 18,1", "℘ Lk 23,49.55", "℘ Mt 12,46"] },
      { number: 15, text: "Und in diesen Tagen stand Petrus in der Mitte der Brüder auf und sprach — und es war eine Menge von etwa hundertzwanzig Personen* beisammen —:", heading: "Wahl des Matthias zum Apostel", footnotes: ["w. Namen"] },
      { number: 16, text: "Ihr Brüder*, es musste die Schrift erfüllt werden*, die der Heilige Geist durch den Mund Davids vorhergesagt hat über Judas, der denen, die Jesus festnahmen, Wegweiser geworden ist*.", footnotes: ["w. Männer, Brüder (ein Hebraismus, gew. bei der Anrede verwendet)", "℘ Lk 24,44", "℘ Lk 22,4.47"] },
      { number: 17, text: "Denn er war uns zugezählt und hatte das Los dieses Dienstes empfangen*.", footnotes: ["℘ Joh 6,70.71"] },
      { number: 18, text: "Dieser nun hat zwar von dem Lohn der Ungerechtigkeit einen Acker erworben, ist aber kopfüber gestürzt, mitten entzweigeborsten, und alle seine Eingeweide sind ausgeschüttet worden." },
      { number: 19, text: "Und es ist allen Bewohnern von Jerusalem bekannt geworden, so dass jener Acker in ihrer eigenen Mundart Hakeldamach, das ist Blutacker, genannt worden ist*.", footnotes: ["℘ Mt 27,7.8"] },
      { number: 20, text: "Denn es steht im Buch der Psalmen geschrieben: »Seine Wohnung werde öde, und es sei niemand, der darin wohne«*!, und: »Sein Aufseheramt empfange ein anderer!«*", footnotes: ["℘ Ps 69,26", "℘ Ps 109,8"] },
      { number: 21, text: "Es muss nun von den Männern, die mit uns gegangen sind in all der Zeit, in welcher der Herr Jesus bei uns ein- und ausging*,", footnotes: ["℘ Lk 1,2"] },
      { number: 22, text: "angefangen von der Taufe des Johannes bis zu dem Tag, an dem er von uns hinweg aufgenommen wurde — von diesen muss einer Zeuge seiner Auferstehung mit uns werden*.", footnotes: ["℘ Kap. 2,32; 3,15; 10,39"] },
      { number: 23, text: "Und sie stellten zwei auf: Josef, genannt Barsabbas*, mit dem Beinamen Justus, und Matthias.", footnotes: ["℘ Kap. 15,22"] },
      { number: 24, text: "Und sie beteten und sprachen: Du, Herr, Herzenskenner aller*, zeige von diesen beiden den einen an, den du auserwählt hast,", footnotes: ["℘ Kap. 15,8; Lk 5,22"] },
      { number: 25, text: "damit er die Stelle dieses Dienstes und Apostelamtes empfängt, von dem Judas abgewichen ist, um an seinen eigenen Ort zu gehen." },
      { number: 26, text: "Und sie gaben ihnen Lose*; und das Los fiel auf Matthias, und er wurde den elf Aposteln zugezählt.", footnotes: ["o. warfen Lose für sie\n℘ 1Sam 14,42; Spr 16,33"] },
    ]},
    { number: 2, verses: [
      { number: 1, text: "Und als der Tag des Pfingstfestes* erfüllt war*, waren sie alle an einem Ort beisammen.", heading: "Das Kommen des Heiligen Geistes", footnotes: ["w. Tag des 50. (Tag nach Darbringung der Erstlingsgarbe), auch »Fest der Wochen« genannt", "℘ 3Mo 23,15.16; 5Mo 16,9.10"] },
      { number: 2, text: "Und plötzlich geschah aus dem Himmel ein Brausen, als führe ein gewaltiger Wind daher, und erfüllte das ganze Haus, wo sie saßen." },
      { number: 3, text: "Und es erschienen ihnen zerteilte Zungen wie von Feuer, und sie setzten sich* auf jeden Einzelnen von ihnen.", footnotes: ["w. es setzte sich"] },
      { number: 4, text: "Und sie wurden alle mit Heiligem Geist erfüllt* und fingen an in anderen Sprachen* zu reden, wie der Geist ihnen gab auszusprechen*.", footnotes: ["℘ Kap. 4,31; 11,15", "o. Zungen", "℘ Kap. 10,44-46; 19,6; Mk 16,17; 1Kor 12,10"] },
      { number: 5, text: "Es wohnten aber in Jerusalem Juden, gottesfürchtige Männer, von jeder Nation unter dem Himmel." },
      { number: 6, text: "Als aber dieses Geräusch* entstand, kam die Menge zusammen und wurde bestürzt, weil jeder Einzelne sie in seiner eigenen Mundart* reden hörte.", footnotes: ["o. diese Stimme", "℘ 1Mo 11,9"] },
      { number: 7, text: "Sie entsetzten sich aber alle und wunderten sich und sagten: Siehe, sind nicht alle diese, die da reden, Galiläer?" },
      { number: 8, text: "Und wie hören wir sie, ein jeder in unserer eigenen Mundart, in der wir geboren sind:" },
      { number: 9, text: "Parther und Meder und Elamiter und die Bewohner von Mesopotamien und von Judäa und Kappadozien, Pontus und Asien*", footnotes: ["d. i. die röm. Provinz »Asia«, der westl. Teil Kleinasiens"] },
      { number: 10, text: "und Phrygien und Pamphylien, Ägypten und den Gegenden von Libyen gegen Kyrene hin und die hier weilenden Römer, sowohl Juden als auch Proselyten*,", footnotes: ["durch Anerkennung des Gesetzes, Beschneidung und Proselytentaufe in die Gemeinde Israels aufgenommene Heiden"] },
      { number: 11, text: "Kreter und Araber — wie hören wir sie von den großen Taten Gottes* in unseren Sprachen reden?", footnotes: ["℘ Ps 9,2"] },
      { number: 12, text: "Sie entsetzten sich aber alle und waren in Verlegenheit und sagten einer zum anderen: Was mag dies wohl sein?" },
      { number: 13, text: "Andere aber sagten spottend: Sie sind voll süßen Weines*.", footnotes: ["℘ 1Kor 14,23"] },
      { number: 14, text: "Petrus aber stand auf mit den Elfen, erhob seine Stimme und redete zu ihnen: Männer von Judäa und ihr alle, die ihr zu Jerusalem wohnt, dies sei euch kund, und hört auf meine Worte!", heading: "Pfingstpredigt des Petrus" },
      { number: 15, text: "Denn diese sind nicht betrunken, wie ihr meint, denn es ist die dritte Stunde des Tages*;", footnotes: ["d. i. etwa zwei bis drei Stunden nach Sonnenaufgang; vgl. auch Anm. zu Mt 20,3"] },
      { number: 16, text: "sondern dies ist es, was durch den Propheten Joel gesagt ist:" },
      { number: 17, text: "»Und es wird geschehen in den letzten Tagen, spricht Gott, dass ich von meinem Geist ausgießen werde* auf alles Fleisch, und eure Söhne und eure Töchter werden weissagen, und eure jungen Männer werden Gesichte sehen, und eure Ältesten werden in Träumen Visionen haben;", footnotes: ["℘ Jes 44,3"] },
      { number: 18, text: "und sogar auf meine Knechte* und auf meine Mägde* werde ich in jenen Tagen von meinem Geist ausgießen, und sie werden weissagen.", footnotes: ["w. Sklaven bzw. Sklavinnen", "w. Sklaven bzw. Sklavinnen"] },
      { number: 19, text: "Und ich werde Wunder tun oben am Himmel und Zeichen unten auf der Erde: Blut und Feuer und qualmender Rauch;" },
      { number: 20, text: "die Sonne wird verwandelt werden in Finsternis und der Mond in Blut*, ehe der große und herrliche Tag des Herrn kommt*.", footnotes: ["℘ Offb 6,12", "℘ Joe 2,11"] },
      { number: 21, text: "Und es wird geschehen: Jeder, der den Namen des Herrn anrufen wird, wird gerettet werden.«*", footnotes: ["℘ Joe 3,1-5; Röm 10,13"] },
      { number: 22, text: "Männer von Israel, hört diese Worte: Jesus, den Nazoräer*, einen Mann, der von Gott euch gegenüber erwiesen worden ist durch Machttaten und Wunder und Zeichen, die Gott durch ihn in eurer Mitte tat*, wie ihr selbst wisst —", footnotes: ["Eine andere Form für das bei Mk (und teilweise Lk) überlieferte »Nazarener«; vgl. auch Anm. zu Mt 2,23", "℘ Kap. 10,38; Lk 24,19; Joh 3,2"] },
      { number: 23, text: "diesen Mann, der nach dem bestimmten Ratschluss und nach Vorkenntnis Gottes* hingegeben worden ist, habt ihr durch die Hand von Gesetzlosen an das Kreuz geschlagen und umgebracht*.", footnotes: ["℘ Kap. 3,18; 4,28; Lk 22,22; 1Petr 1,20", "℘ V. 36"] },
      { number: 24, text: "Den hat Gott auferweckt*, nachdem er die Wehen des Todes aufgelöst hatte, wie es denn nicht möglich war, dass er von ihm behalten würde.", footnotes: ["℘ Kap. 3,15; 4,10; 5,30; 10,40; 13,30; 17,31; Mt 28,6; Röm 4,24; 1Kor 6,14; Gal 1,1; Eph 1,20; 1Thes 1,10; 1Petr 1,21"] },
      { number: 25, text: "Denn David sagt über ihn: »Ich sah den Herrn allezeit vor mir; denn er ist zu meiner Rechten, damit ich nicht wanke." },
      { number: 26, text: "Darum freute sich mein Herz, und meine Zunge jubelte; ja, auch mein Fleisch wird in Hoffnung ruhen;" },
      { number: 27, text: "denn du wirst meine Seele nicht im Hades* zurücklassen noch zugeben, dass dein Frommer Verwesung sehe.", footnotes: ["d. i. das Totenreich; so auch V. 31"] },
      { number: 28, text: "Du hast mir kundgetan Wege des Lebens; du wirst mich mit Freude erfüllen vor deinem Angesicht.«*", footnotes: ["℘ Ps 16,8-11"] },
      { number: 29, text: "Ihr Brüder*, es sei erlaubt, mit Freimütigkeit zu euch zu reden über den Patriarchen David, dass er gestorben und begraben und sein Grab bis auf diesen Tag unter uns ist*.", footnotes: ["w. Männer, Brüder (ein Hebraismus, gew. bei der Anrede verwendet)", "℘ 1Kö 2,10; Neh 3,16"] },
      { number: 30, text: "Da er nun ein Prophet war* und wusste, dass Gott ihm mit einem Eid geschworen hatte, einen seiner Nachkommen* auf seinen Thron zu setzen*,", footnotes: ["℘ 2Sam 23,2", "w. einen aus der Frucht seiner Lende", "℘ 2Sam 7,12.13; Ps 89,4.5"] },
      { number: 31, text: "hat er voraussehend von der Auferstehung des Christus geredet, dass er weder im Hades zurückgelassen worden ist noch sein Fleisch die Verwesung gesehen hat*.", footnotes: ["℘ Kap. 13,35-37; Joh 20,9"] },
      { number: 32, text: "Diesen Jesus hat Gott auferweckt, wovon wir alle Zeugen sind*.", footnotes: ["℘ Kap. 1,8.22"] },
      { number: 33, text: "Nachdem er nun durch die Rechte Gottes erhöht worden ist* und die Verheißung des Heiligen Geistes vom Vater empfangen hat*, hat er dieses ausgegossen*, was ihr seht und hört.", footnotes: ["℘ Kap. 5,31; Phil 2,9", "℘ Kap. 1,4", "℘ Joh 7,39; Tit 3,6"] },
      { number: 34, text: "Denn nicht David ist in die Himmel aufgefahren; er sagt aber selbst: »Der Herr sprach zu meinem Herrn: Setze dich zu meiner Rechten," },
      { number: 35, text: "bis ich deine Feinde lege zum Schemel deiner Füße!«*", footnotes: ["℘ Ps 110,1; Mt 22,44"] },
      { number: 36, text: "Das ganze Haus Israel wisse nun zuverlässig, dass Gott ihn sowohl zum Herrn* als auch zum Christus gemacht hat*, diesen Jesus, den ihr gekreuzigt habt*.", footnotes: ["℘ Kap. 10,36; Eph 1,21; Phil 2,11", "℘ Lk 2,11", "℘ V. 23; Kap. 3,15; 4,10; 5,30.31; 7,52; 10,39; Mk 15,25; Lk 24,20"] },
      { number: 37, text: "Als sie aber das hörten, drang es ihnen durchs Herz, und sie sprachen zu Petrus und den anderen Aposteln: Was sollen wir tun, ihr Brüder*?", heading: "Entstehung der Gemeinde", footnotes: ["w. Männer, Brüder (ein Hebraismus, gew. bei der Anrede verwendet)\n℘ Kap. 16,30; Lk 3,10; Joh 6,28"] },
      { number: 38, text: "Petrus aber sprach zu ihnen: Tut Buße*, und jeder von euch lasse sich taufen* auf den Namen Jesu Christi zur Vergebung eurer Sünden*! Und ihr werdet die Gabe des Heiligen Geistes empfangen*.", footnotes: ["℘ Kap. 3,19; 20,21; 26,20; Mt 3,2", "o. soll getauft werden", "℘ Kap. 22,16; Mk 16,16", "℘ Eph 1,13"] },
      { number: 39, text: "Denn euch gilt die Verheißung und euren Kindern und allen, die in der Ferne sind*, so viele der Herr, unser Gott, hinzurufen wird*.", footnotes: ["℘ Jes 57,19", "℘ Ps 115,14"] },
      { number: 40, text: "Und mit vielen anderen Worten legte er Zeugnis ab und ermahnte sie* und sagte: Lasst euch retten aus diesem verkehrten Geschlecht*!", footnotes: ["o. beschwor und ermahnte er sie", "℘ Mt 17,17"] },
      { number: 41, text: "Die nun sein Wort aufnahmen, ließen sich taufen*; und es wurden an jenem Tag etwa dreitausend Seelen hinzugetan.", footnotes: ["w. wurden getauft\n℘ Kap. 8,12; 18,8"] },
      { number: 42, text: "Sie verharrten aber in der Lehre der Apostel* und in der Gemeinschaft, im Brechen des Brotes* und in den Gebeten*.", footnotes: ["℘ 2Tim 3,14", "℘ Kap. 20,7; Lk 22,19; 1Kor 10,16", "℘ Kap. 1,14"] },
      { number: 43, text: "Es kam aber über jede Seele Furcht, und es geschahen viele Wunder und Zeichen durch die Apostel*.", footnotes: ["℘ Kap. 4,30; 5,12; 6,8; 8,6; 14,3; 19,11"] },
      { number: 44, text: "Alle Gläubiggewordenen* aber waren beisammen und hatten alles gemeinsam*;", footnotes: ["mit anderen Handschr.: Alle Glaubenden", "℘ Kap. 4,32"] },
      { number: 45, text: "und sie verkauften die Güter und die Habe und verteilten sie an alle, je nachdem einer bedürftig war*.", footnotes: ["℘ Kap. 4,35; Lk 12,33; Röm 12,13"] },
      { number: 46, text: "Täglich verharrten sie einmütig im Tempel* und brachen zu Hause das Brot, nahmen Speise mit Jubel und Schlichtheit des Herzens,", footnotes: ["℘ Kap. 3,1; Lk 24,53"] },
      { number: 47, text: "lobten Gott und hatten Gunst beim ganzen Volk. Der Herr aber tat täglich hinzu, die gerettet werden sollten*.", footnotes: ["℘ Kap. 4,4; 5,14; 6,7; 9,31; 11,21.24; 16,5"] },
    ]},
    { number: 3, verses: [
      { number: 1, text: "Petrus aber und Johannes gingen um die Stunde des Gebets*, die neunte*, zusammen hinauf in den Tempel*.", heading: "Heilung eines Lahmgeborenen", footnotes: ["℘ Kap. 10,3", "d. i. etwa drei Stunden vor Sonnenuntergang; vgl. auch Anm. zu Mt 20,3", "℘ Kap. 2,46"] },
      { number: 2, text: "Und ein Mann, der von seiner Mutter Leibe an lahm war, wurde herbeigetragen*; man setzte ihn täglich an die Pforte des Tempels, die man die schöne nennt, damit er Almosen erbat von denen, die in den Tempel gingen.", footnotes: ["℘ Kap. 14,8"] },
      { number: 3, text: "Als dieser Petrus und Johannes sah, wie sie in den Tempel eintreten wollten, bat er, dass er ein Almosen empfinge." },
      { number: 4, text: "Petrus aber mit Johannes blickte fest auf ihn hin und sprach: Sieh uns an!" },
      { number: 5, text: "Er aber gab acht auf sie, in der Erwartung, etwas von ihnen zu empfangen." },
      { number: 6, text: "Petrus aber sprach: Silber und Gold besitze ich nicht; was ich aber habe, das gebe ich dir: Im Namen Jesu Christi, des Nazoräers*: Geh umher*!*", footnotes: ["Eine andere Form für das bei Mk (und teilweise Lk) überlieferte »Nazarener«; vgl. auch Anm. zu Mt 2,23\n℘ Kap. 4,10", "℘ Kap. 9,34", "mit anderen alten Handschr.: Steh auf und geh umher!"] },
      { number: 7, text: "Und er ergriff ihn bei der rechten Hand und richtete ihn auf. Sofort aber wurden seine Füße und seine Knöchel stark," },
      { number: 8, text: "er sprang auf, konnte stehen und ging umher. Und er trat mit ihnen in den Tempel, ging umher und sprang und lobte Gott*.", footnotes: ["℘ Jes 35,6"] },
      { number: 9, text: "Und das ganze Volk sah ihn umhergehen und Gott loben;" },
      { number: 10, text: "und sie erkannten ihn, dass er der war, der um das Almosen an der schönen Pforte des Tempels gesessen; und sie wurden mit Verwunderung und Erstaunen erfüllt über das, was sich mit ihm ereignet hatte." },
      { number: 11, text: "Während er aber den Petrus und Johannes festhielt, lief das ganze Volk voller Erstaunen zu ihnen zusammen in der Säulenhalle, die Salomonshalle genannt wird*.", footnotes: ["℘ Kap. 5,12; Joh 10,23"] },
      { number: 12, text: "Als aber Petrus es sah, sprach er zum Volk: Männer von Israel, was verwundert ihr euch hierüber, oder was seht ihr so gespannt auf uns, als hätten wir aus eigener Kraft oder Frömmigkeit* bewirkt, dass er gehen kann?", heading: "Zweite Predigt des Petrus", footnotes: ["o. Gottesfurcht"] },
      { number: 13, text: "Der Gott Abrahams und Isaaks und Jakobs, der Gott unserer Väter*, hat seinen Knecht* Jesus verherrlicht*, den ihr überliefert und vor Pilatus verleugnet habt*, als dieser entschieden hatte, ihn loszugeben.", footnotes: ["℘ Kap. 5,30; 22,14; 2Mo 3,6", "℘ Kap. 4,27; Jes 42,1; 53,11", "℘ Joh 12,23", "℘ Joh 19,15"] },
      { number: 14, text: "Ihr aber habt den Heiligen* und Gerechten* verleugnet und gebeten, dass euch ein Mörder geschenkt würde*;", footnotes: ["℘ Lk 1,35", "℘ Kap. 7,52; 22,14; 1Petr 3,18; 1Jo 2,1", "℘ Lk 23,18.19"] },
      { number: 15, text: "den Fürsten* des Lebens aber habt ihr getötet, den Gott aus den Toten auferweckt hat*, wovon wir Zeugen sind*.", footnotes: ["o. Anfänger, Urheber, Begründer", "℘ Kap. 2,24.36", "℘ Kap. 1,8.22"] },
      { number: 16, text: "Und durch den Glauben an seinen Namen hat sein Name diesen, den ihr seht und kennt, stark gemacht; und der durch ihn bewirkte Glaube hat ihm diese vollkommene Gesundheit gegeben vor euch allen." },
      { number: 17, text: "Und jetzt, Brüder, ich weiß, dass ihr in Unwissenheit gehandelt habt, wie auch eure Obersten*.", footnotes: ["℘ Lk 23,34"] },
      { number: 18, text: "Gott aber hat so erfüllt, was er durch den Mund aller Propheten vorher verkündigt hat*, dass sein Christus leiden sollte*.", footnotes: ["℘ Kap. 2,23", "℘ Kap. 17,3; 26,23; Lk 24,26.27"] },
      { number: 19, text: "So tut nun Buße und bekehrt euch*, dass eure Sünden ausgetilgt werden,", footnotes: ["℘ Kap. 2,38"] },
      { number: 20, text: "damit Zeiten der Erquickung kommen vom Angesicht des Herrn und er den euch vorausbestimmten Jesus Christus sende*!", footnotes: ["℘ Kap. 1,11"] },
      { number: 21, text: "Den muss freilich der Himmel aufnehmen bis zu den Zeiten* der Wiederherstellung aller Dinge*, von denen Gott durch den Mund seiner heiligen Propheten von jeher* geredet hat*.", footnotes: ["℘ 1Tim 6,15", "℘ Mt 17,11", "o. von Ewigkeit (griech. Äon) her", "℘ Jes 65,17-25; Offb 10,7"] },
      { number: 22, text: "Mose hat schon gesagt: »Einen Propheten wird euch der Herr, euer Gott, aus euren Brüdern erwecken, gleich mir. Auf ihn sollt ihr hören* in allem, was er zu euch reden wird!", footnotes: ["℘ Kap. 7,37"] },
      { number: 23, text: "Es wird aber geschehen: Jede Seele, die auf jenen Propheten nicht hören wird, soll aus dem Volk ausgerottet werden.«*", footnotes: ["℘ 5Mo 18,15.18.19; Joh 5,46"] },
      { number: 24, text: "Aber auch alle Propheten, von Samuel an und der Reihe nach, so viele geredet haben, haben auch diese Tage verkündigt*.", footnotes: ["℘ 1Petr 1,10"] },
      { number: 25, text: "Ihr seid die Söhne der Propheten und des Bundes, den Gott euren Vätern verordnet hat*, als er zu Abraham sprach: »Und in deinem Samen* werden gesegnet werden alle Geschlechter der Erde.«*", footnotes: ["℘ Röm 9,4", "o. in deiner Nachkommenschaft\n℘ Gal 3,16.29", "℘ 1Mo 22,18"] },
      { number: 26, text: "Euch zuerst hat Gott seinen Knecht erweckt und ihn gesandt, euch zu segnen*, indem er einen jeden von euch von seinen* Bosheiten abwendet.", footnotes: ["℘ Kap. 13,46; Mt 15,24; Röm 1,16; 15,8", "w. euren"] },
    ]},
    { number: 4, verses: [
      { number: 1, text: "Während sie aber zu dem Volk redeten, kamen die Priester und der Hauptmann des Tempels und die Sadduzäer* auf sie zu*,", heading: "Petrus und Johannes vor dem Hohen Rat", footnotes: ["religiöse Partei, der u. a. die vornehmen Priesterfamilien angehörten; s. auch Anm. zu Mt 3,7", "℘ Kap. 5,17"] },
      { number: 2, text: "empört darüber, dass sie das Volk lehrten und in Jesus die Auferstehung aus den Toten verkündigten*.", footnotes: ["℘ Kap. 23,8"] },
      { number: 3, text: "Und sie legten Hand an sie* und setzten sie in Gewahrsam bis an den Morgen, denn es war schon Abend*.", footnotes: ["℘ Kap. 12,1", "℘ Kap. 5,18; 16,23; Lk 21,12"] },
      { number: 4, text: "Viele aber von denen, die das Wort gehört hatten, wurden gläubig; und die Zahl der Männer kam auf etwa fünftausend*.", footnotes: ["℘ Kap. 2,41.47"] },
      { number: 5, text: "Es geschah aber am folgenden Tag, dass ihre Obersten und Ältesten und Schriftgelehrten sich in Jerusalem versammelten," },
      { number: 6, text: "und Hannas, der Hohepriester, und Kaiphas* und Johannes und Alexander und so viele vom hohenpriesterlichen Geschlecht waren.", footnotes: ["℘ Lk 3,2"] },
      { number: 7, text: "Und nachdem sie sie in die Mitte gestellt hatten, fragten sie: In welcher Kraft oder in welchem Namen habt ihr dies getan*?", footnotes: ["℘ Mt 21,23"] },
      { number: 8, text: "Da sprach Petrus, erfüllt mit Heiligem Geist, zu ihnen: Oberste des Volkes und Älteste!" },
      { number: 9, text: "Wenn wir heute über die Wohltat an einem kranken Menschen verhört werden, wodurch dieser geheilt worden ist," },
      { number: 10, text: "so sei euch allen und dem ganzen Volk Israel kund: Im Namen Jesu Christi, des Nazoräers*, den ihr gekreuzigt habt, den Gott auferweckt hat aus den Toten* — in diesem Namen steht dieser gesund vor euch*.", footnotes: ["s. Anm. zu Kap. 2,22", "℘ Kap. 2,24.36", "℘ Kap. 3,6.16"] },
      { number: 11, text: "Das ist der Stein, der von euch, den Bauleuten, verachtet, der zum Eckstein* geworden ist*.", footnotes: ["w. zum Haupt der Ecke", "℘ Ps 118,22; Mt 21,42"] },
      { number: 12, text: "Und es ist in keinem anderen das Heil*; denn auch kein anderer Name unter dem Himmel ist den Menschen gegeben, in dem wir gerettet werden müssen*.", footnotes: ["o. die Rettung", "℘ Kap. 5,31; 13,23; Mt 1,21"] },
      { number: 13, text: "Als sie aber die Freimütigkeit des Petrus und Johannes sahen und bemerkten, dass es ungelehrte und ungebildete Leute seien*, verwunderten sie sich; und sie erkannten sie, dass sie mit Jesus gewesen waren.", footnotes: ["℘ 1Kor 1,27"] },
      { number: 14, text: "Und da sie den Menschen, der geheilt worden war, bei ihnen stehen sahen*, konnten sie nichts dagegen sagen.", footnotes: ["℘ Kap. 3,8.9"] },
      { number: 15, text: "Nachdem sie ihnen aber befohlen hatten, aus dem Hohen Rat* zu gehen, überlegten sie miteinander", footnotes: ["w. Synedrium; s. Anm. zu Mt 26,59"] },
      { number: 16, text: "und sagten: Was sollen wir diesen Menschen tun? Denn dass wirklich ein deutliches Zeichen durch sie geschehen ist, ist allen offenbar, die zu Jerusalem wohnen, und wir können es nicht leugnen*.", footnotes: ["℘ Lk 6,11"] },
      { number: 17, text: "Aber damit es nicht weiter unter dem Volk ausgebreitet werde, wollen wir sie bedrohen, dass sie nicht mehr in diesem Namen zu irgendeinem Menschen reden." },
      { number: 18, text: "Und als sie sie gerufen hatten, geboten sie ihnen, sich überhaupt nicht in dem Namen Jesu zu äußern noch zu lehren*.", footnotes: ["℘ Kap. 5,28.40"] },
      { number: 19, text: "Petrus aber und Johannes antworteten und sprachen zu ihnen: Ob es vor Gott recht ist, auf euch mehr zu hören als auf Gott, urteilt ihr*!", footnotes: ["℘ Kap. 5,29; Dan 3,18"] },
      { number: 20, text: "Denn es ist uns unmöglich, von dem, was wir gesehen und gehört haben, nicht zu reden*.", footnotes: ["℘ Jer 20,9; 1Kor 9,16"] },
      { number: 21, text: "Sie aber bedrohten sie noch mehr und entließen sie, da sie nicht fanden, auf welche Weise sie sie bestrafen sollten, um des Volkes willen*; denn alle verherrlichten Gott* um dessentwillen, was geschehen war.", footnotes: ["℘ Kap. 5,26; Mt 21,46", "℘ Lk 5,26"] },
      { number: 22, text: "Denn der Mensch war mehr als vierzig Jahre alt, an dem dieses Zeichen der Heilung geschehen war." },
      { number: 23, text: "Als sie aber entlassen waren, kamen sie zu den Ihren und verkündeten alles, was die Hohenpriester* und die Ältesten zu ihnen gesagt hatten.", heading: "Gebet der Gemeinde", footnotes: ["Nicht nur der amtierende Hohepriester, sondern alle männlichen Mitglieder der hohenpriesterlichen Familien wurden zu den »Hohenpriestern« gerechnet."] },
      { number: 24, text: "Sie aber, als sie es hörten, erhoben einmütig ihre Stimme zu Gott und sprachen: Herrscher, du, der du den Himmel und die Erde und das Meer gemacht hast* und alles, was in ihnen ist*;", footnotes: ["℘ Ps 95,5", "℘ Kap. 14,15; 17,24; 2Mo 20,11; Neh 9,6; Ps 146,6; Offb 10,6"] },
      { number: 25, text: "der du durch den Heiligen Geist durch den Mund unseres Vaters, deines Knechtes David, gesagt hast: »Warum tobten die Nationen und sannen Eitles die Völker?" },
      { number: 26, text: "Die Könige der Erde standen auf und die Fürsten versammelten sich gegen den Herrn und seinen Gesalbten*.«*", footnotes: ["d. h. Christus", "℘ Ps 2,1.2; Lk 22,66"] },
      { number: 27, text: "Denn in dieser Stadt versammelten sich in Wahrheit gegen deinen heiligen Knecht Jesus*, den du gesalbt hast*, sowohl Herodes als auch Pontius Pilatus mit den Nationen und den Völkern Israels*,", footnotes: ["℘ Kap. 3,13", "℘ Kap. 10,38; Mt 3,16; Lk 4,18", "℘ Lk 23,7"] },
      { number: 28, text: "alles zu tun, was deine Hand und dein Ratschluss vorherbestimmt hat, dass es geschehen sollte*.", footnotes: ["℘ Kap. 2,23"] },
      { number: 29, text: "Und nun, Herr, sieh an ihre Drohungen und gib deinen Knechten*, dein Wort mit aller Freimütigkeit zu reden*;", footnotes: ["w. Sklaven", "℘ Eph 6,19"] },
      { number: 30, text: "indem du deine Hand ausstreckst zur Heilung*, dass Zeichen und Wunder geschehen* durch den Namen deines heiligen Knechtes Jesus*.", footnotes: ["℘ Kap. 5,16", "℘ Kap. 2,43; Hebr 2,4", "℘ Kap. 3,13"] },
      { number: 31, text: "Und als sie gebetet hatten, bewegte sich die Stätte, wo sie versammelt waren; und sie wurden alle mit dem Heiligen Geist erfüllt* und redeten das Wort Gottes mit Freimütigkeit.", footnotes: ["℘ Kap. 2,4"] },
      { number: 32, text: "Die Menge derer aber, die gläubig wurden, war ein Herz und eine Seele*; und auch nicht einer sagte, dass etwas von seiner Habe sein eigen sei, sondern es war ihnen alles gemeinsam*.", heading: "Gemeindeleben", footnotes: ["℘ Joh 17,21", "℘ Kap. 2,44"] },
      { number: 33, text: "Und mit großer Kraft legten die Apostel das Zeugnis von der Auferstehung des Herrn Jesus ab*; und große Gnade war auf ihnen allen*.", footnotes: ["℘ Kap. 1,8.22", "℘ Kap. 6,8; Joh 1,16"] },
      { number: 34, text: "Denn es war auch keiner bedürftig unter ihnen, denn so viele Besitzer von Äckern oder Häusern waren, verkauften sie und brachten den Preis des Verkauften*", footnotes: ["℘ Kap. 2,45"] },
      { number: 35, text: "und legten ihn nieder zu den Füßen der Apostel; es wurde aber jedem zugeteilt, so wie einer Bedürfnis hatte*.", footnotes: ["℘ Kap. 2,45"] },
      { number: 36, text: "Josef aber, der von den Aposteln Barnabas* genannt wurde — was übersetzt heißt: Sohn des Trostes —, ein Levit, ein Zyprer von Geburt,", footnotes: ["℘ Kap. 9,27; 11,22; 13,1.2; 1Kor 9,6; Gal 2,9"] },
      { number: 37, text: "der einen Acker besaß, verkaufte ihn, brachte das Geld und legte es zu den Füßen der Apostel nieder*.", footnotes: ["℘ Kap. 5,2"] },
    ]},
    { number: 5, verses: [
      { number: 1, text: "Ein Mann aber mit Namen Hananias, mit Saphira, seiner Frau, verkaufte ein Gut", heading: "Hananias und Saphira" },
      { number: 2, text: "und schaffte von dem Kaufpreis beiseite, wovon auch die Frau wusste; und er brachte einen Teil und legte ihn nieder zu den Füßen der Apostel*.", footnotes: ["℘ Kap. 4,35.37"] },
      { number: 3, text: "Petrus aber sprach: Hananias, warum hat der Satan dein Herz erfüllt*, dass du den Heiligen Geist belogen* und von dem Kaufpreis des Feldes beiseite geschafft hast?", footnotes: ["℘ Joh 13,2", "℘ Eph 4,30"] },
      { number: 4, text: "Blieb es nicht dein, wenn es unverkauft blieb, und war es nicht, nachdem es verkauft war, in deiner Verfügung*? Warum hast du dir diese Tat in deinem Herzen vorgenommen? Nicht Menschen hast du belogen, sondern Gott.", footnotes: ["o. Macht, Vollmacht"] },
      { number: 5, text: "Als aber Hananias diese Worte hörte, fiel er hin und verschied. Und es kam große Furcht über alle, die es hörten." },
      { number: 6, text: "Die jungen Männer aber standen auf, hüllten ihn ein, trugen ihn hinaus und begruben ihn." },
      { number: 7, text: "Es geschah aber nach Verlauf von etwa drei Stunden, dass seine Frau hereinkam, ohne zu wissen, was geschehen war." },
      { number: 8, text: "Petrus aber antwortete ihr: Sag mir, ob ihr für so viel das Feld verkauft habt? Sie aber sprach: Ja, für so viel." },
      { number: 9, text: "Petrus aber sprach zu ihr: Warum seid ihr übereingekommen, den Geist des Herrn zu versuchen*? Siehe, die Füße derer, die deinen Mann begraben haben, sind an der Tür, und sie werden dich hinaustragen.", footnotes: ["℘ Mt 4,7"] },
      { number: 10, text: "Sie fiel aber sofort zu seinen Füßen nieder und verschied. Und als die jungen Männer hereinkamen, fanden sie sie tot; und sie trugen sie hinaus und begruben sie bei ihrem Mann." },
      { number: 11, text: "Und es kam große Furcht über die ganze Gemeinde* und über alle, welche dies hörten*.", footnotes: ["o. Versammlung", "℘ Kap. 19,17; Ps 52,8"] },
      { number: 12, text: "Aber durch die Hände der Apostel geschahen viele Zeichen und Wunder unter dem Volk*; und sie waren alle einmütig in der Säulenhalle Salomos*.", heading: "Krankenheilungen durch die Apostel", footnotes: ["℘ Kap. 2,43; Mk 16,20", "℘ Kap. 3,11"] },
      { number: 13, text: "Von den Übrigen aber wagte keiner, sich ihnen anzuschließen, doch das Volk rühmte sie." },
      { number: 14, text: "Aber umso mehr wurden solche, die an den Herrn glaubten, hinzugetan, Scharen von Männern und auch Frauen*,", footnotes: ["℘ Kap. 2,47"] },
      { number: 15, text: "so dass sie die Kranken auf die Straßen hinaustrugen und auf Betten und Lager legten, damit, wenn Petrus käme, auch nur sein Schatten einen von ihnen überschatten möchte*.", footnotes: ["℘ Kap. 19,11.12"] },
      { number: 16, text: "Es kam aber auch die Menge aus den Städten um Jerusalem zusammen, und sie brachten Kranke und von unreinen Geistern Geplagte, die alle geheilt wurden*.", footnotes: ["℘ Kap. 4,30; 8,7; 16,18; 19,12; 28,9; Mk 16,17.18; Lk 4,40"] },
      { number: 17, text: "Der Hohepriester aber trat auf und alle, die mit ihm waren, nämlich die Sekte der Sadduzäer*, und wurden von Eifersucht* erfüllt*;", heading: "Gefangennahme und Befreiung der Apostel", footnotes: ["religiöse Partei, der u. a. die vornehmen Priesterfamilien angehörten; s. auch Anm. zu Mt 3,7", "o. Neid", "℘ Kap. 4,1.2.6"] },
      { number: 18, text: "und sie legten Hand an die Apostel und setzten sie in öffentlichen Gewahrsam*.", footnotes: ["℘ Kap. 4,3"] },
      { number: 19, text: "Ein Engel des Herrn* aber öffnete während der Nacht die Türen des Gefängnisses* und führte sie hinaus und sprach:", footnotes: ["℘ Kap. 8,26; 10,3; 12,7", "℘ Kap. 12,10; Hebr 1,14"] },
      { number: 20, text: "Geht und stellt euch hin und redet im Tempel zu dem Volk alle Worte dieses Lebens*!", footnotes: ["℘ Joh 6,68"] },
      { number: 21, text: "Als sie es aber gehört hatten, gingen sie frühmorgens in den Tempel und lehrten. Der Hohepriester aber kam und die, die mit ihm waren, und sie beriefen den Hohen Rat* und die ganze Ältestenschaft der Söhne Israel zusammen und sandten ins Gefängnis, dass sie vorgeführt würden.", footnotes: ["w. Synedrium; so auch V. 27—41; s. Anm. zu Mt 26,59"] },
      { number: 22, text: "Als aber die Diener hinkamen, fanden sie sie nicht im Gefängnis*; und sie kehrten zurück, berichteten", footnotes: ["℘ Kap. 12,19"] },
      { number: 23, text: "und sagten: Wir fanden das Gefängnis mit aller Sorgfalt verschlossen und die Wachen an den Türen stehen; als wir aber geöffnet hatten, fanden wir niemand darin." },
      { number: 24, text: "Als aber der Hauptmann des Tempels wie auch die Hohenpriester diese Worte hörten, waren sie ihretwegen in Verlegenheit, was dies doch werden möchte." },
      { number: 25, text: "Es kam aber einer und berichtete ihnen: Siehe, die Männer, die ihr ins Gefängnis gesetzt habt, stehen im Tempel und lehren das Volk." },
      { number: 26, text: "Da ging der Hauptmann mit den Dienern hin und führte sie herbei, nicht mit Gewalt, denn sie fürchteten das Volk, sie könnten gesteinigt werden*.", footnotes: ["℘ Kap. 4,21; Lk 20,6"] },
      { number: 27, text: "Sie führten sie aber herbei und stellten sie vor den Hohen Rat; und der Hohepriester befragte sie", heading: "Zeugnis der Apostel vor dem Hohen Rat" },
      { number: 28, text: "und sprach: Wir haben euch streng geboten, in diesem Namen nicht zu lehren*, und siehe, ihr habt Jerusalem mit eurer Lehre erfüllt und wollt das Blut dieses Menschen auf uns bringen*.", footnotes: ["℘ Kap. 4,18", "℘ Mt 27,25"] },
      { number: 29, text: "Petrus und die Apostel aber antworteten und sprachen: Man muss Gott mehr gehorchen als Menschen*.", footnotes: ["℘ Kap. 4,19"] },
      { number: 30, text: "Der Gott unserer Väter* hat Jesus auferweckt, den ihr ermordet habt*, indem ihr ihn ans Holz hängtet*.", footnotes: ["℘ Kap. 3,13", "℘ Kap. 2,24.36", "℘ 5Mo 21,22"] },
      { number: 31, text: "Diesen hat Gott durch seine Rechte* zum Führer* und Retter erhöht, um Israel Buße und Vergebung der Sünden zu geben*.", footnotes: ["℘ Kap. 2,33", "o. Fürsten, Urheber; im Griech. dasselbe Wort wie in Kap. 3,15", "℘ Kap. 4,12; 10,43; 13,38; 26,18; Lk 24,47"] },
      { number: 32, text: "Und wir sind Zeugen von diesen Dingen* und der Heilige Geist*, den Gott denen gegeben hat, die ihm gehorchen*.", footnotes: ["o. Worten\n℘ Kap. 1,8.22", "℘ Joh 15,26", "℘ Kap. 11,17; 15,8"] },
      { number: 33, text: "Sie aber ergrimmten*, als sie es hörten, und ratschlagten, sie umzubringen.", footnotes: ["℘ Kap. 7,54"] },
      { number: 34, text: "Es stand aber im Hohen Rat ein Pharisäer* mit Namen Gamaliel* auf, ein Gesetzesgelehrter, angesehen bei dem ganzen Volk, und befahl, die Leute für kurze Zeit hinauszutun.", heading: "Rat des Gamaliel", footnotes: ["religiöse Partei im Judentum, die auf genaue Einhaltung des Gesetzes Wert legte; s. auch Anm. zu Mt 3,7", "℘ Kap. 22,3"] },
      { number: 35, text: "Und er sprach zu ihnen: Männer von Israel, seht euch bei diesen Menschen vor, was ihr tun wollt!" },
      { number: 36, text: "Denn vor diesen Tagen stand Theudas auf und sagte, dass er selbst etwas sei, dem eine Anzahl von etwa vierhundert Männern anhing; der ist getötet worden, und alle, die ihm Gehör gaben, sind zerstreut und zunichte geworden." },
      { number: 37, text: "Nach diesem stand Judas der Galiläer auf, in den Tagen der Einschreibung*, und machte eine Menge Volk abtrünnig und brachte sie hinter sich; auch der kam um, und alle, die ihm Gehör gaben, wurden zerstreut*.", footnotes: ["s. Anm. zu Lk 2,1\n℘ Lk 2,2", "℘ Mt 24,11"] },
      { number: 38, text: "Und jetzt sage ich euch: Lasst ab von diesen Menschen und lasst sie laufen! Denn wenn dieser Rat oder dieses Werk aus Menschen ist, so wird es zugrunde gehen*;", footnotes: ["℘ Mt 15,13"] },
      { number: 39, text: "wenn es aber aus Gott ist, so werdet ihr sie nicht zugrunde richten können; damit ihr nicht gar als solche befunden werdet, die gegen Gott streiten. Und sie gaben ihm Gehör." },
      { number: 40, text: "Und als sie die Apostel herbeigerufen hatten, schlugen sie sie* und geboten ihnen, nicht im Namen Jesu zu reden*, und entließen sie.", heading: "Freilassung der Apostel", footnotes: ["Gemeint ist die Strafe der Geißelung; vgl. Anm. zu Mt 10,17.\n℘ Mk 13,9", "℘ Kap. 4,18"] },
      { number: 41, text: "Sie nun gingen aus dem Hohen Rat fort, voller Freude, dass sie gewürdigt worden waren, für den Namen Schmach zu leiden*;", footnotes: ["℘ Mt 5,11; Röm 5,3; 2Kor 12,10; Phil 1,29; 1Petr 4,13.14"] },
      { number: 42, text: "und sie hörten nicht auf, jeden Tag im Tempel und in den Häusern zu lehren* und Jesus als den Christus zu verkündigen*.", footnotes: ["℘ Kap. 20,20", "o. Christus als Evangelium zu verkündigen\n℘ Kap. 9,22; 17,3; 18,5.28"] },
    ]},
    { number: 6, verses: [
      { number: 1, text: "In diesen Tagen aber, als die Jünger sich mehrten, entstand ein Murren der Hellenisten* gegen die Hebräer, weil ihre Witwen bei der täglichen Bedienung übersehen wurden.", heading: "Diakonenwahl", footnotes: ["Juden, die aus der Zerstreuung (Diaspora) der griech. sprechenden (hellenistischen) östl. Mittelmeerwelt stammten."] },
      { number: 2, text: "Die Zwölf aber riefen die Menge der Jünger herbei und sprachen: Es ist nicht gut, dass wir das Wort Gottes vernachlässigen und die Tische bedienen." },
      { number: 3, text: "So seht euch nun um, Brüder, nach sieben Männern unter euch, von gutem Zeugnis*, voll Geist* und Weisheit, die wir über diese Aufgabe setzen wollen!", footnotes: ["℘ Kap. 16,2; 1Tim 3,8", "℘ Kap. 7,55; 11,24"] },
      { number: 4, text: "Wir aber werden im Gebet und im Dienst des Wortes verharren." },
      { number: 5, text: "Und die Rede gefiel der ganzen Menge; und sie erwählten Stephanus, einen Mann voll Glaubens und Heiligen Geistes*, und Philippus* und Prochorus und Nikanor und Timon und Parmenas und Nikolaus, einen Proselyten* aus Antiochia.", footnotes: ["℘ Kap. 7,55; 11,24", "℘ Kap. 8,5.26; 21,8", "durch Anerkennung des Gesetzes, Beschneidung und Proselytentaufe in die Gemeinde Israels aufgenommener Heide"] },
      { number: 6, text: "Diese stellten sie vor die Apostel; und als sie gebetet hatten, legten sie ihnen die Hände auf*.", footnotes: ["℘ Kap. 8,17; 9,17; 13,3; 14,23"] },
      { number: 7, text: "Und das Wort Gottes wuchs*, und die Zahl der Jünger in Jerusalem mehrte sich sehr*; und eine große Menge der Priester wurde dem Glauben gehorsam.", footnotes: ["℘ Kap. 12,24; 13,49; 19,20; Kol 1,6", "℘ Kap. 2,47"] },
      { number: 8, text: "Stephanus aber, voller Gnade* und Kraft*, tat Wunder und große Zeichen unter dem Volk*.", heading: "Anklage gegen Stephanus", footnotes: ["℘ Kap. 4,33", "℘ 1Kor 2,4.5", "℘ Kap. 2,43"] },
      { number: 9, text: "Es standen aber einige aus der sogenannten Synagoge der Libertiner* und der Kyrenäer und der Alexandriner auf und derer von Zilizien und Asien* und stritten mit Stephanus.", footnotes: ["o. der Freigelassenen; Nachkommen ehemaliger jüdischer Sklaven", "Synagogen von Juden, die aus griech. sprechenden (hellenistischen) Provinzen Afrikas und Kleinasiens stammten"] },
      { number: 10, text: "Und sie konnten der Weisheit und dem Geist nicht widerstehen, womit er redete*.", footnotes: ["℘ Lk 21,15"] },
      { number: 11, text: "Da schoben sie heimlich Männer vor, die sagten: Wir haben ihn Lästerworte reden hören gegen Mose und Gott*.", footnotes: ["℘ 1Kö 21,10; Mt 26,59"] },
      { number: 12, text: "Und sie erregten das Volk und die Ältesten und die Schriftgelehrten; und sie fielen über ihn her und rissen ihn mit sich fort und führten ihn vor den Hohen Rat*.", footnotes: ["w. Synedrium; so auch V. 15; s. Anm. zu Mt 26,59\n℘ Mt 10,17"] },
      { number: 13, text: "Und sie stellten falsche Zeugen auf*, die sagten: Dieser Mensch hört nicht auf, Worte zu reden gegen die heilige Stätte* und das Gesetz;", footnotes: ["℘ Kap. 7,58; Mk 14,57", "℘ Kap. 21,28; Jer 26,11"] },
      { number: 14, text: "denn wir haben ihn sagen hören: Dieser Jesus, der Nazoräer*, wird diese Stätte zerstören und die Gebräuche verändern, die uns Mose überliefert hat*.", footnotes: ["eine andere Form für das bei Mk (und teilweise Lk) überlieferte »Nazarener«; vgl. auch Anm. zu Mt 2,23", "℘ Kap. 21,21"] },
      { number: 15, text: "Und alle, die im Hohen Rat saßen, schauten gespannt auf ihn und sahen sein Angesicht wie eines Engels Angesicht." },
    ]},
    { number: 7, verses: [
      { number: 1, text: "Der Hohepriester aber sprach: Ist das so?", heading: "Verteidigungsrede des Stephanus vor dem Hohen Rat" },
      { number: 2, text: "Er aber sprach: Ihr Brüder* und Väter, hört*! Der Gott der Herrlichkeit* erschien unserem Vater Abraham, als er in Mesopotamien war, ehe er in Haran wohnte*,", footnotes: ["w. Männer, Brüder (ein Hebraismus, gew. bei der Anrede verwendet)", "℘ Kap. 22,1", "℘ Ps 29,3; Eph 1,17", "℘ 1Mo 11,31"] },
      { number: 3, text: "und sprach zu ihm: »Geh aus deinem Land und aus deiner Verwandtschaft, und komm in das Land, das ich dir zeigen werde!«*", footnotes: ["℘ 1Mo 12,1"] },
      { number: 4, text: "Da ging er aus dem Land der Chaldäer und wohnte in Haran; und von da siedelte er ihn, nachdem sein Vater gestorben war*, in dieses Land um, in dem ihr jetzt wohnt*.", footnotes: ["℘ 1Mo 11,32", "℘ 1Mo 12,5; Hebr 11,8"] },
      { number: 5, text: "Und er gab ihm kein Erbteil darin, auch nicht einen Fußbreit*, und er verhieß, es ihm zum Besitztum zu geben und seinen Nachkommen nach ihm*, obwohl er kein Kind hatte*.", footnotes: ["℘ 1Mo 23,4", "℘ 1Mo 17,8", "℘ 1Mo 12,7; 13,15"] },
      { number: 6, text: "Gott aber sprach so: »Seine Nachkommen werden Fremdlinge* sein in fremdem Land*, und man wird sie knechten* und misshandeln vierhundert Jahre.", footnotes: ["w. Bei-Wohner, o. Nicht-Bürger; so auch V. 29", "℘ 2Mo 2,22", "o. versklaven"] },
      { number: 7, text: "Und die Nation, der sie dienen* werden, werde ich richten«, sprach Gott, »und danach werden sie ausziehen und mir an diesem Ort dienen*.«*", footnotes: ["o. Sklave sein", "o. Gottesdienst tun; im Griech. ein anderes Wort als in V. 7a", "℘ 1Mo 15,13.14; 2Mo 3,12; 12,40.41"] },
      { number: 8, text: "Und er gab ihm den Bund der Beschneidung*; und so zeugte er den Isaak und beschnitt ihn am achten Tag*, und Isaak den Jakob* und Jakob die zwölf Patriarchen*.", footnotes: ["℘ 1Mo 17,10", "℘ 1Mo 21,4", "℘ 1Mo 25,26", "℘ 1Mo 35,22-26"] },
      { number: 9, text: "Und die Patriarchen, neidisch auf Josef*, verkauften ihn nach Ägypten*. Gott aber war mit ihm*", footnotes: ["℘ 1Mo 37,4.8.11", "℘ 1Mo 37,28", "℘ 1Mo 39,2.21.23"] },
      { number: 10, text: "und rettete ihn aus allen seinen Bedrängnissen* und gab ihm Gunst und Weisheit vor Pharao, dem König von Ägypten; und er setzte ihn als Regenten* über Ägypten und sein ganzes Haus ein.", footnotes: ["℘ 1Mo 40,14; Ps 105,20.21", "w. als Führenden"] },
      { number: 11, text: "Es kam nun eine Hungersnot über ganz Ägypten und Kanaan und eine große Bedrängnis*, und unsere Väter fanden keine Speise.", footnotes: ["℘ 1Mo 41,57; 42,5"] },
      { number: 12, text: "Als aber Jakob hörte, dass in Ägypten Getreide sei, sandte er unsere Väter zum ersten Mal aus*.", footnotes: ["℘ 1Mo 42,2"] },
      { number: 13, text: "Beim zweiten Mal wurde Josef von seinen Brüdern wiedererkannt*, und dem Pharao wurde die Herkunft Josefs bekannt*.", footnotes: ["℘ 1Mo 45,3", "℘ 1Mo 45,16"] },
      { number: 14, text: "Josef aber sandte hin und ließ seinen Vater Jakob holen und die ganze Verwandtschaft mit fünfundsiebzig Seelen*.", footnotes: ["℘ 1Mo 45,18; 46,27; 5Mo 10,22"] },
      { number: 15, text: "Jakob zog nun nach Ägypten hinab* und starb, er und unsere Väter*;", footnotes: ["℘ 1Mo 46,6", "℘ 1Mo 49,33; 2Mo 1,6"] },
      { number: 16, text: "und sie wurden nach Sichem hinübergebracht und in die Grabstätte gelegt*, die Abraham für eine Summe Geld von den Söhnen Hamors in Sichem gekauft hatte*.", footnotes: ["℘ 1Mo 50,13; Jos 24,32", "℘ 1Mo 23,16"] },
      { number: 17, text: "Als aber die Zeit der Verheißung nahte, die Gott dem Abraham zugesagt hatte*, wuchs das Volk und vermehrte sich in Ägypten*,", footnotes: ["℘ V. 5", "℘ 2Mo 1,7"] },
      { number: 18, text: "bis ein anderer König über Ägypten aufstand, der Josef nicht kannte*.", footnotes: ["℘ 2Mo 1,8"] },
      { number: 19, text: "Dieser handelte mit List gegen unser Geschlecht und misshandelte die Väter*, so dass sie ihre Säuglinge aussetzen mussten, damit sie nicht am Leben blieben*.", footnotes: ["℘ 2Mo 1,14", "℘ 2Mo 1,22; Ps 105,25"] },
      { number: 20, text: "In dieser Zeit wurde Mose* geboren, und er war Gott angenehm*; und er wurde drei Monate aufgezogen im Haus des Vaters*.", footnotes: ["℘ 2Mo 2,2", "o. schön für Gott", "℘ Hebr 11,23"] },
      { number: 21, text: "Als er aber ausgesetzt worden war*, nahm ihn die Tochter Pharaos zu sich und zog ihn auf, sich zum Sohn*.", footnotes: ["℘ 2Mo 2,3", "℘ 2Mo 2,10"] },
      { number: 22, text: "Und Mose wurde unterwiesen in aller Weisheit der Ägypter; er war aber mächtig in seinen Worten und Werken*.", footnotes: ["℘ Lk 24,19"] },
      { number: 23, text: "Als er aber ein Alter von vierzig Jahren erreicht hatte*, kam es in seinem Herzen auf, nach seinen Brüdern, den Söhnen Israel, zu sehen.", footnotes: ["w. Als ihm aber eine Zeit von . . . erfüllt wurde"] },
      { number: 24, text: "Und als er einen Unrecht leiden sah, verteidigte er ihn und rächte den Unterdrückten, indem er den Ägypter erschlug*.", footnotes: ["℘ 2Mo 2,11.12"] },
      { number: 25, text: "Er meinte aber, seine Brüder würden verstehen, dass Gott ihnen durch seine Hand Rettung gebe; sie aber verstanden es nicht." },
      { number: 26, text: "Am folgenden Tag erschien er bei ihnen, als sie sich stritten, und trieb* sie zum Frieden, indem er sagte: Ihr Männer, ihr seid Brüder, warum tut ihr einander Unrecht*?", footnotes: ["w. versöhnte", "℘ 2Mo 2,13"] },
      { number: 27, text: "Der aber dem Nächsten Unrecht tat, stieß ihn weg und sprach: Wer hat dich als Obersten und Richter über uns eingesetzt*?", footnotes: ["℘ V. 35"] },
      { number: 28, text: "Willst du mich etwa umbringen, wie du gestern den Ägypter umgebracht hast?" },
      { number: 29, text: "Mose aber entfloh bei diesem Wort und wurde ein Fremdling im Land Midian*, wo er zwei Söhne zeugte*.", footnotes: ["℘ 2Mo 2,14.15", "℘ 2Mo 2,22; 18,3"] },
      { number: 30, text: "Als vierzig Jahre verflossen* waren, erschien ihm in der Wüste des Berges Sinai ein Engel in der Feuerflamme eines Dornbusches*.", footnotes: ["w. erfüllt", "℘ 2Mo 3,2"] },
      { number: 31, text: "Als aber Mose es sah, wunderte er sich über die Erscheinung; während er aber hinzutrat, sie zu betrachten*, erging die Stimme des Herrn:", footnotes: ["℘ 2Mo 3,3"] },
      { number: 32, text: "»Ich bin der Gott deiner Väter, der Gott Abrahams und Isaaks und Jakobs.«* Mose aber erzitterte und wagte nicht, es zu betrachten.", footnotes: ["℘ 2Mo 3,6; Mt 22,32"] },
      { number: 33, text: "Der Herr aber sprach zu ihm: »Löse die Sandale von deinen Füßen, denn der Ort, auf dem du stehst, ist heiliges Land*.", footnotes: ["℘ 2Mo 3,5; Jos 5,15"] },
      { number: 34, text: "Gesehen* habe ich die Misshandlung meines Volkes, das in Ägypten ist, und ihr Seufzen habe ich gehört*, und ich bin herabgekommen, sie herauszureißen. Und nun komm, ich will dich nach Ägypten senden.«*", footnotes: ["im Griech. verstärkt; w. Sehend gesehen", "℘ 2Mo 2,24", "℘ 2Mo 3,7.8.10"] },
      { number: 35, text: "Diesen Mose, den sie verleugneten, indem sie sagten: »Wer hat dich als Obersten und Richter eingesetzt?«*, den hat Gott zum Obersten und Retter* gesandt durch die Hand des Engels, der ihm in dem Dornbusch erschien*.", footnotes: ["℘ V. 27", "o. Erlöser, Befreier", "℘ 4Mo 20,16"] },
      { number: 36, text: "Dieser führte sie heraus, indem er Wunder und Zeichen tat im Land Ägypten* und im Roten Meer* und in der Wüste, vierzig Jahre*.", footnotes: ["℘ Neh 9,10; Ps 105,27-36", "℘ 2Mo 14,21.22; Neh 9,11; Ps 106,22", "℘ Neh 9,12-21; Ps 105,40.41"] },
      { number: 37, text: "Das ist der Mose, der zu den Söhnen Israels sprach: »Einen Propheten wie mich wird euch Gott aus euren Brüdern erwecken.«*", footnotes: ["℘ Kap. 3,22.23; Mk 9,7"] },
      { number: 38, text: "Dieser ist es, der in der Gemeinde* in der Wüste gewesen ist mit dem Engel, der auf dem Berg Sinai zu ihm redete* und mit unseren Vätern. Er empfing lebendige Aussprüche*, um sie uns zu geben.", footnotes: ["o. Versammlung", "℘ 2Mo 19,3; 24,18; Joh 1,17; Röm 3,2; Gal 3,19", "℘ Hebr 4,12"] },
      { number: 39, text: "Unsere Väter aber wollten nicht gehorsam sein, sondern stießen ihn von sich, wandten sich in ihren Herzen nach Ägypten zurück*", footnotes: ["℘ 4Mo 14,3"] },
      { number: 40, text: "und sagten zu Aaron: »Mach uns Götter, die vor uns herziehen sollen! Denn dieser Mose, der uns aus dem Land Ägypten geführt hat — wir wissen nicht, was ihm geschehen ist.«*", footnotes: ["℘ 2Mo 32,1"] },
      { number: 41, text: "Sie machten in jenen Tagen ein Kalb und brachten dem Götzenbild ein Schlachtopfer und ergötzten sich an den Werken ihrer Hände*.", footnotes: ["℘ 2Mo 32,2-6; Ps 106,19"] },
      { number: 42, text: "Gott aber wandte sich ab und gab sie dahin*, dem Heer des Himmels zu dienen*, wie geschrieben steht im Buch der Propheten: »Habt ihr mir etwa vierzig Jahre in der Wüste Opfertiere und Schlachtopfer dargebracht, Haus Israel?", footnotes: ["℘ Kap. 14,16; Ps 81,13; Röm 1,24.26.28", "o. Gottesdienst zu tun\n℘ 5Mo 4,19; 2Kö 17,16; Jer 7,18; 19,13"] },
      { number: 43, text: "Ihr nahmt das Zelt des Moloch mit und das Sternbild des Gottes Räfan*, die Bilder, die ihr gemacht hattet, sie anzubeten; und ich werde euch verpflanzen über Babylon hinaus.«*", footnotes: ["o. Raifan, Refan", "℘ Am 5,25-27"] },
      { number: 44, text: "Unsere Väter hatten das Zelt des Zeugnisses in der Wüste, wie der, welcher zu Mose redete, befohlen hatte, es nach dem Muster zu machen, das er gesehen hatte*.", footnotes: ["℘ 2Mo 25,40"] },
      { number: 45, text: "Und unsere Väter übernahmen es und führten es mit Josua* ein bei der Besitzergreifung des Landes der Nationen*, die Gott austrieb von dem Angesicht unserer Väter hinweg*, bis zu den Tagen Davids,", footnotes: ["griech. Jesus", "℘ Jos 3,14", "℘ Jos 18,1; Neh 9,24; Ps 44,4"] },
      { number: 46, text: "der Gnade fand vor Gott und eine Wohnstätte zu finden begehrte für den Gott Jakobs*.", footnotes: ["℘ 2Sam 7,2; 1Kö 8,17; Ps 132,4.5"] },
      { number: 47, text: "Salomo aber baute ihm ein Haus*.", footnotes: ["℘ 1Kö 6,1"] },
      { number: 48, text: "Aber der Höchste wohnt nicht in Wohnungen, die mit Händen gemacht sind*, wie der Prophet spricht:", footnotes: ["℘ Kap. 17,24; 1Kö 8,27"] },
      { number: 49, text: "»Der Himmel ist mein Thron und die Erde der Schemel meiner Füße*. Was für ein Haus wollt ihr mir bauen, spricht der Herr, oder welches ist der Ort meiner Ruhe?", footnotes: ["℘ Mt 5,34.35"] },
      { number: 50, text: "Hat nicht meine Hand dies alles gemacht?«*", footnotes: ["℘ Jes 66,1.2"] },
      { number: 51, text: "Ihr Halsstarrigen und Unbeschnittenen an Herz und Ohren*! Ihr widerstrebt allezeit dem Heiligen Geist; wie eure Väter*, so auch ihr.", footnotes: ["℘ Jer 6,10; 9,25", "℘ 2Mo 32,9; 33,3; 4Mo 27,14; Jes 63,10"] },
      { number: 52, text: "Welchen der Propheten haben eure Väter nicht verfolgt*? Und sie haben die getötet*, welche die* Ankunft des Gerechten* vorher verkündigten, dessen Verräter und Mörder ihr jetzt geworden seid*,", footnotes: ["℘ 2Chr 36,16; Neh 9,26; Mt 5,12; Lk 11,47; 13,34", "℘ Kap. 2,36", "w. über die", "℘ Kap. 3,14", "℘ Kap. 3,15; 1Thes 2,15"] },
      { number: 53, text: "die ihr das Gesetz durch Anordnung von Engeln empfangen* und nicht befolgt* habt*.", footnotes: ["℘ Hebr 2,2", "o. beachtet, eingehalten", "℘ Lk 23,24.25"] },
      { number: 54, text: "Als sie aber dies hörten, wurden ihre Herzen durchbohrt*, und sie knirschten mit den Zähnen gegen ihn*.", heading: "Steinigung des Stephanus — Verfolgung der Gemeinde", footnotes: ["℘ Kap. 5,33", "℘ Ps 35,16"] },
      { number: 55, text: "Da er aber voll Heiligen Geistes war* und fest zum Himmel schaute, sah er die Herrlichkeit Gottes und Jesus zur Rechten Gottes stehen*;", footnotes: ["℘ Kap. 6,5", "℘ Lk 22,69; 1Petr 3,22"] },
      { number: 56, text: "und er sprach: Siehe, ich sehe die Himmel geöffnet* und den Sohn des Menschen zur Rechten Gottes stehen*!", footnotes: ["℘ Kap. 10,11", "℘ Hebr 10,12"] },
      { number: 57, text: "Sie schrien aber mit lauter Stimme, hielten ihre Ohren zu und stürzten einmütig auf ihn los." },
      { number: 58, text: "Und als sie ihn aus der Stadt hinausgestoßen hatten, steinigten sie ihn*. Und die Zeugen* legten ihre Kleider ab zu den Füßen eines jungen Mannes mit Namen Saulus*.", footnotes: ["℘ Kap. 14,19", "℘ Kap. 6,13; 5Mo 17,7", "℘ Kap. 22,20"] },
      { number: 59, text: "Und sie steinigten den Stephanus*, der betete* und sprach: Herr Jesus, nimm meinen Geist auf*!", footnotes: ["℘ Mt 23,37", "w. rief an", "℘ Lk 23,46"] },
      { number: 60, text: "Und niederkniend rief er mit lauter Stimme: Herr, rechne ihnen diese Sünde nicht zu*! Und als er dies gesagt hatte, entschlief er.", footnotes: ["℘ Lk 23,34; 2Tim 4,16"] },
    ]},
    { number: 8, verses: [
      { number: 1, text: "Saulus aber willigte in seine Tötung mit ein*. An jenem Tag entstand aber eine große Verfolgung gegen die Gemeinde* in Jerusalem*; und alle wurden in die Landschaften von Judäa und Samaria zerstreut*, ausgenommen die Apostel.", footnotes: ["℘ Kap. 22,20", "o. Versammlung", "℘ 1Thes 2,14", "℘ Kap. 11,19"] },
      { number: 2, text: "Gottesfürchtige Männer aber bestatteten den Stephanus* und stellten eine große Klage über ihn an.", footnotes: ["℘ Mt 14,12"] },
      { number: 3, text: "Saulus aber verwüstete die Gemeinde*, indem er der Reihe nach in die Häuser ging; und er schleppte sowohl Männer als auch Frauen fort und überlieferte sie ins Gefängnis*.", footnotes: ["o. Versammlung", "℘ Kap. 9,2; 22,4; 26,9-11; 1Kor 15,9; Gal 1,13.23; Phil 3,6; 1Tim 1,13"] },
      { number: 4, text: "Die Zerstreuten nun gingen umher und verkündigten* das Wort.", heading: "Philippus in Samaria — Simon der Zauberer", footnotes: ["o. verkündigten als Evangelium"] },
      { number: 5, text: "Philippus* aber ging hinab in eine Stadt Samarias und predigte ihnen den Christus.", footnotes: ["℘ Kap. 6,5"] },
      { number: 6, text: "Die Volksmengen achteten einmütig auf das, was von Philippus geredet wurde, indem sie zuhörten und die Zeichen sahen, die er tat*.", footnotes: ["℘ Kap. 2,43; 4,30"] },
      { number: 7, text: "Denn von vielen, die unreine Geister hatten, fuhren sie aus*, mit lauter Stimme schreiend*; und viele Gelähmte und Lahme wurden geheilt*.", footnotes: ["℘ Kap. 5,16", "℘ Mt 8,29", "℘ Kap. 2,43; 4,30"] },
      { number: 8, text: "Und es war große Freude in jener Stadt*.", footnotes: ["℘ Kap. 13,48"] },
      { number: 9, text: "Ein Mann aber, mit Namen Simon, befand sich vorher in der Stadt, der trieb Zauberei* und brachte das Volk* von Samaria außer sich, indem er von sich selbst sagte, dass er etwas Großes* sei;", footnotes: ["℘ Kap. 13,8", "griech. ethnos; sonst gewöhnlich mit »Nation« übersetzt", "w. ein Großer"] },
      { number: 10, text: "dem hingen alle, vom Kleinen* bis zum Großen, an und sagten: Dieser ist die Kraft Gottes, die man die große nennt.", footnotes: ["o. Geringen"] },
      { number: 11, text: "Sie hingen ihm an, weil er sie lange Zeit mit den Zaubereien außer sich gebracht hatte." },
      { number: 12, text: "Als sie aber dem Philippus glaubten, der das Evangelium vom Reich* Gottes und dem Namen Jesu Christi verkündigte, ließen sie sich taufen*, sowohl Männer als auch Frauen*.", footnotes: ["o. von der Königsherrschaft", "w. wurden sie getauft", "℘ Kap. 2,41"] },
      { number: 13, text: "Auch Simon selbst glaubte, und als er getauft war, hielt er sich zu Philippus; und als er die Zeichen und großen Wunder sah, die geschahen, geriet er außer sich." },
      { number: 14, text: "Als die Apostel in Jerusalem gehört hatten, dass Samaria das Wort Gottes angenommen habe*, sandten sie Petrus und Johannes zu ihnen*.", heading: "Petrus und Johannes in Samaria — Abweisung Simons des Zauberers", footnotes: ["℘ Kap. 11,1; 1Thes 2,13", "℘ Kap. 11,22"] },
      { number: 15, text: "Als diese hinabgekommen waren, beteten sie für sie, damit sie den Heiligen Geist empfangen möchten*;", footnotes: ["℘ Kap. 2,38"] },
      { number: 16, text: "denn er war noch auf keinen von ihnen gefallen, sondern sie waren allein getauft auf den Namen des Herrn Jesus." },
      { number: 17, text: "Dann legten sie ihnen die Hände auf*, und sie empfingen den Heiligen Geist*! —", footnotes: ["℘ Kap. 6,6", "℘ Kap. 19,5.6; Hebr 2,4"] },
      { number: 18, text: "Als aber Simon sah, dass durch das Auflegen der Hände der Apostel der Geist gegeben wurde, brachte er ihnen Geld" },
      { number: 19, text: "und sagte: Gebt auch mir diese Macht*, dass der, dem ich die Hände auflege, den Heiligen Geist empfängt!", footnotes: ["o. Vollmacht"] },
      { number: 20, text: "Petrus aber sprach zu ihm: Dein Geld fahre mit dir ins Verderben, weil du gemeint hast, dass die Gabe Gottes durch Geld zu erlangen sei!" },
      { number: 21, text: "Du hast weder Teil noch Recht* an dieser Sache, denn dein Herz ist nicht aufrichtig vor Gott.", footnotes: ["w. Los"] },
      { number: 22, text: "Tu nun Buße über diese deine Bosheit und bitte den Herrn, ob dir etwa der Anschlag deines Herzens vergeben werde*!", footnotes: ["℘ 2Tim 2,25"] },
      { number: 23, text: "Denn ich sehe, dass du voll bitterer Galle* und in Banden der Ungerechtigkeit bist*.", footnotes: ["℘ 5Mo 29,17", "w. zu Galle der Bitterkeit und einer Fessel der Ungerechtigkeit geworden bist"] },
      { number: 24, text: "Simon aber antwortete und sprach: Bittet ihr für mich den Herrn, damit nichts über mich komme von dem, was ihr gesagt habt!" },
      { number: 25, text: "Nachdem sie nun das Wort des Herrn bezeugt und geredet hatten, kehrten sie nach Jerusalem zurück und verkündigten das Evangelium vielen Dörfern der Samariter." },
      { number: 26, text: "Ein Engel des Herrn* aber redete zu Philippus und sprach: Steh auf und geh nach Süden* auf den Weg, der von Jerusalem nach Gaza hinabführt! Der ist öde.", heading: "Der Kämmerer aus Äthiopien", footnotes: ["℘ Kap. 5,19", "o. um die Mittagszeit"] },
      { number: 27, text: "Und er stand auf und ging hin. Und siehe, ein Äthiopier, ein Kämmerer*, ein Gewaltiger der Kandake*, der Königin der Äthiopier, der über ihren ganzen Schatz gesetzt war, war gekommen, um zu Jerusalem anzubeten*;", footnotes: ["w. Eunuch; im erweiterten Sinn für höhere Hofbeamte gebraucht; so auch V. 34—38", "Titel der Königinnen von Äthiopien", "℘ Joh 12,20"] },
      { number: 28, text: "und er war auf der Rückkehr und saß auf seinem Wagen und las den Propheten Jesaja." },
      { number: 29, text: "Der Geist aber sprach zu Philippus: Tritt hinzu und schließe dich diesem Wagen an*!", footnotes: ["℘ Kap. 10,19; 11,12; Mt 4,1"] },
      { number: 30, text: "Philippus aber lief hinzu und hörte ihn den Propheten Jesaja lesen und sprach: Verstehst du auch, was du liest?" },
      { number: 31, text: "Er aber sprach: Wie könnte ich denn, wenn nicht jemand mich anleitet? Und er bat den Philippus, dass er aufsteige und sich zu ihm setze." },
      { number: 32, text: "Die Stelle der Schrift aber, die er las, war diese: »Er wurde wie ein Schaf zur Schlachtung geführt, und wie ein Lamm stumm ist vor seinem Scherer, so tut er seinen Mund nicht auf." },
      { number: 33, text: "In seiner Erniedrigung wurde sein Gericht weggenommen. Wer aber wird sein Geschlecht beschreiben? Denn sein Leben wird von der Erde weggenommen.«*", footnotes: ["℘ Jes 53,7.8"] },
      { number: 34, text: "Der Kämmerer aber antwortete dem Philippus und sprach: Ich bitte dich, von wem sagt der Prophet dies? Von sich selbst oder von einem anderen?" },
      { number: 35, text: "Philippus aber tat seinen Mund auf und fing mit dieser Schrift an und verkündigte ihm das Evangelium von Jesus." },
      { number: 36, text: "Als sie aber auf dem Weg fortzogen, kamen sie an ein Wasser. Und der Kämmerer spricht: Siehe, da ist Wasser! Was hindert mich, getauft zu werden?" },
      { number: 37, text: "[T>]*", footnotes: ["Andere Handschr. fügen hinzu: Philippus aber sprach zu ihm: Wenn du von ganzem Herzen glaubst, ist es erlaubt. Er aber antwortete und sprach: Ich glaube, dass Jesus Christus der Sohn Gottes ist."] },
      { number: 38, text: "Und er befahl, den Wagen anzuhalten. Und sie stiegen beide in das Wasser hinab, sowohl Philippus als auch der Kämmerer, und er taufte ihn." },
      { number: 39, text: "Als sie aber aus dem Wasser heraufstiegen, entrückte der Geist des Herrn den Philippus*, und der Kämmerer sah ihn nicht mehr, denn er zog seinen Weg mit Freuden.", footnotes: ["℘ 1Kö 18,12; Hes 3,14"] },
      { number: 40, text: "Philippus aber fand man zu Aschdod*; und er zog hindurch und verkündigte das Evangelium allen Städten, bis er nach Cäsarea kam*.", footnotes: ["w. wurde zu Aschdod gefunden", "℘ Kap. 21,8"] },
    ]},
    { number: 9, verses: [
      { number: 1, text: "*Saulus aber schnaubte immer noch Drohung und Mord gegen die Jünger des Herrn*, ging zu dem Hohenpriester", heading: "Bekehrung des Saulus", footnotes: ["℘ Kap. 22,3-16; 26,9-20", "℘ 1Tim 1,13"] },
      { number: 2, text: "und erbat sich von ihm Briefe nach Damaskus an die Synagogen, damit, wenn er einige, die des Weges* wären*, fände, Männer wie auch Frauen, er sie gebunden nach Jerusalem führe*.", footnotes: ["d. h. des Weges Christi o. des christlichen Bekenntnisses", "℘ Kap. 19,9.23; 24,14.22", "℘ Kap. 8,3"] },
      { number: 3, text: "Als er aber hinzog, geschah es, dass er sich Damaskus näherte. Und plötzlich umstrahlte ihn ein Licht aus dem Himmel*;", footnotes: ["℘ 1Kor 15,8"] },
      { number: 4, text: "und er fiel auf die Erde und hörte eine Stimme, die zu ihm sprach: Saul, Saul, was verfolgst du mich*?", footnotes: ["℘ Lk 10,16"] },
      { number: 5, text: "Er aber sprach: Wer bist du, Herr? Er aber sagte: Ich bin Jesus, den du verfolgst." },
      { number: 6, text: "Doch steh auf und geh in die Stadt, und es wird dir gesagt werden, was du tun sollst!" },
      { number: 7, text: "Die Männer aber, die mit ihm des Weges zogen, standen sprachlos, da sie wohl die Stimme hörten, aber niemand sahen*.", footnotes: ["℘ Dan 10,7"] },
      { number: 8, text: "Saulus aber richtete sich von der Erde auf. Als sich aber seine Augen öffneten, sah er nichts. Und sie leiteten ihn bei der Hand und führten ihn nach Damaskus." },
      { number: 9, text: "Und er konnte drei Tage nicht sehen und aß nicht und trank nicht." },
      { number: 10, text: "Es war aber ein Jünger in Damaskus, mit Namen Hananias; und der Herr sprach zu ihm in einer Erscheinung: Hananias! Er aber sprach: Siehe, hier bin ich, Herr*!", footnotes: ["℘ 1Mo 22,1"] },
      { number: 11, text: "Der Herr aber sprach zu ihm: Steh auf und geh in die Straße, welche die »Gerade« genannt wird, und frage im Haus des Judas nach einem mit Namen Saulus von Tarsus*! Denn siehe, er betet;", footnotes: ["℘ Kap. 21,39; 23,34"] },
      { number: 12, text: "und er hat in der Erscheinung* einen Mann mit Namen Hananias gesehen, der hereinkam und ihm die Hände auflegte, damit er wieder sehend werde.", footnotes: ["℘ Kap. 16,9; 18,9"] },
      { number: 13, text: "Hananias aber antwortete: Herr, ich habe von vielen über diesen Mann gehört, wie viel Böses er deinen Heiligen in Jerusalem getan hat." },
      { number: 14, text: "Und hier hat er Vollmacht von den Hohenpriestern*, alle zu binden, die deinen Namen anrufen*.", footnotes: ["s. Anm. zu Kap. 4,23", "℘ 1Kor 1,2"] },
      { number: 15, text: "Der Herr aber sprach zu ihm: Geh hin! Denn dieser ist mir ein auserwähltes Werkzeug, meinen Namen zu tragen sowohl vor Nationen* als auch vor Könige* und Söhne Israels*.", footnotes: ["℘ Kap. 22,21; Röm 1,5; Eph 3,8", "℘ Kap. 25,23", "℘ Kap. 13,2; 20,24"] },
      { number: 16, text: "Denn ich werde ihm zeigen, wie vieles er für meinen Namen leiden muss*.", footnotes: ["℘ Kap. 20,23; 21,11; 2Kor 11,23-27; 2Tim 1,12"] },
      { number: 17, text: "Hananias aber ging hin und kam in das Haus; und er legte ihm die Hände auf* und sprach: Bruder Saul, der Herr hat mich gesandt durch Jesus — der dir erschienen ist auf dem Weg, den du kamst —, damit du wieder sehend und mit Heiligem Geist erfüllt werdest.", footnotes: ["℘ Kap. 6,6"] },
      { number: 18, text: "Und sogleich fiel es wie Schuppen von seinen Augen, und er wurde sehend, und stand auf und ließ sich taufen*.", footnotes: ["o. wurde getauft"] },
      { number: 19, text: "Und nachdem er Speise genommen hatte, kam er zu Kräften. Er war aber einige Tage bei den Jüngern in Damaskus.", heading: "Zeugnis des Saulus in Damaskus" },
      { number: 20, text: "Und sogleich predigte er in den Synagogen Jesus, dass dieser der Sohn Gottes ist*.", footnotes: ["℘ 2Kor 1,19; Gal 1,16"] },
      { number: 21, text: "Alle aber, die es hörten, gerieten außer sich und sagten: Ist dieser nicht der, welcher in Jerusalem die zugrunde richtete, die diesen Namen anrufen*, und dazu hierher gekommen war, dass er sie gebunden zu den Hohenpriestern führe*?", footnotes: ["℘ Kap. 26,10", "℘ Gal 1,23"] },
      { number: 22, text: "Saulus aber erstarkte noch mehr im Wort und brachte die Juden, die in Damaskus* wohnten, in Verwirrung, indem er bewies, dass dieser der Christus ist*.", footnotes: ["℘ Gal 1,17", "℘ Kap. 5,42"] },
      { number: 23, text: "Als aber viele Tage verflossen waren, ratschlagten die Juden miteinander, ihn umzubringen*.", footnotes: ["℘ V. 29; Kap. 13,50; 14,5; 17,5.13; 18,12; 20,3; 23,12; 25,3; 2Kor 11,26"] },
      { number: 24, text: "Es wurde aber dem Saulus ihr Anschlag bekannt. Und sie bewachten auch die Tore sowohl bei Tag als auch bei Nacht, damit sie ihn umbrächten." },
      { number: 25, text: "Die Jünger aber nahmen ihn bei Nacht und ließen ihn durch die Mauer hinab, indem sie ihn in einem Korb hinunterließen*.", footnotes: ["℘ 2Kor 11,32.33"] },
      { number: 26, text: "Als er aber nach Jerusalem gekommen war*, versuchte er, sich den Jüngern anzuschließen*; und alle fürchteten sich vor ihm, da sie nicht glaubten, dass er ein Jünger sei.", heading: "Zeugnis des Saulus in Jerusalem", footnotes: ["℘ Kap. 22,17", "℘ Gal 1,18"] },
      { number: 27, text: "Barnabas* aber nahm ihn und brachte ihn zu den Aposteln und erzählte ihnen, wie er auf dem Weg den Herrn gesehen habe und dass der zu ihm geredet und wie er in Damaskus freimütig im Namen Jesu gesprochen habe.", footnotes: ["℘ Kap. 4,36"] },
      { number: 28, text: "Und er ging mit ihnen aus und ein in Jerusalem und sprach freimütig im Namen des Herrn*.", footnotes: ["℘ Röm 15,19"] },
      { number: 29, text: "Und er redete und stritt mit den Hellenisten*; sie aber trachteten, ihn umzubringen*.", footnotes: ["s. Anm. zu Kap. 6,1", "℘ V. 23"] },
      { number: 30, text: "Als die Brüder es aber erfuhren, brachten sie ihn nach Cäsarea hinab und sandten ihn weg nach Tarsus*.", footnotes: ["℘ Kap. 11,25; Gal 1,21"] },
      { number: 31, text: "So hatte denn die Gemeinde* durch ganz Judäa und Galiläa und Samaria hin Frieden und wurde erbaut und wandelte in der Furcht des Herrn und mehrte sich* durch den Trost* des Heiligen Geistes.", footnotes: ["o. Versammlung", "℘ Kap. 2,47", "o. die Ermahnung; o. den Beistand"] },
      { number: 32, text: "Es geschah aber, dass Petrus, indem er überall hindurchzog, auch zu den Heiligen hinabkam, die zu Lydda wohnten.", heading: "Heilung des Äneas" },
      { number: 33, text: "Er fand aber dort einen Menschen mit Namen Äneas, der seit acht Jahren zu Bett lag; er war gelähmt*.", footnotes: ["℘ Lk 5,18"] },
      { number: 34, text: "Und Petrus sprach zu ihm: Äneas! Jesus Christus heilt dich. Steh auf und mach dir selbst dein Bett*! Und sogleich stand er auf*.", footnotes: ["℘ Kap. 3,6", "℘ Kap. 14,10; Lk 5,25"] },
      { number: 35, text: "Und es sahen ihn alle, die zu Lydda und Scharon wohnten; die bekehrten sich zum Herrn*.", footnotes: ["℘ Kap. 11,21"] },
      { number: 36, text: "In Joppe aber war eine Jüngerin mit Namen Tabita, die übersetzt heißt: Dorkas*. Diese war reich an guten Werken* und Almosen*, die sie übte.", heading: "Auferweckung der Tabita", footnotes: ["d. h. Gazelle", "℘ 1Tim 2,10", "℘ Kap. 10,2"] },
      { number: 37, text: "Es geschah aber in jenen Tagen, dass sie krank wurde und starb. Und als man sie gewaschen hatte, legte man sie in ein Obergemach." },
      { number: 38, text: "Da aber Lydda nahe bei Joppe war, sandten die Jünger, als sie gehört hatten, dass Petrus dort sei, zwei Männer zu ihm und baten: Zögere nicht, zu uns zu kommen!" },
      { number: 39, text: "Petrus aber stand auf und ging mit ihnen; und als er angekommen war, führten sie ihn in das Obergemach. Und alle Witwen traten weinend zu ihm und zeigten ihm die Unter- und Oberkleider, die Dorkas gemacht hatte, während sie bei ihnen war." },
      { number: 40, text: "Petrus aber trieb alle hinaus*, kniete nieder und betete. Und er wandte sich zu dem Leichnam und sprach: Tabita, steh auf*! Sie aber schlug ihre Augen auf, und als sie den Petrus sah, setzte sie sich auf.", footnotes: ["℘ Lk 8,54", "℘ Mk 5,40.41"] },
      { number: 41, text: "Er aber gab ihr die Hand und richtete sie auf*; er rief aber die Heiligen und die Witwen und stellte sie lebend vor.", footnotes: ["℘ Kap. 20,12"] },
      { number: 42, text: "Es wurde aber durch ganz Joppe hin bekannt, und viele glaubten an den Herrn." },
      { number: 43, text: "Es geschah aber, dass er viele Tage in Joppe bei einem Gerber Simon blieb*.", footnotes: ["℘ Kap. 10,6"] },
    ]},
    { number: 10, verses: [
      { number: 1, text: "Ein Mann aber in Cäsarea mit Namen Kornelius — ein Hauptmann von der sogenannten Italischen Schar*,", heading: "Der Hauptmann Kornelius in Cäsarea", footnotes: ["Ehrenname einer militärischen Einheit; vgl. Anm. zu Mk 15,16"] },
      { number: 2, text: "fromm und gottesfürchtig mit seinem ganzen Haus, der dem Volk viele Almosen gab* und allezeit zu Gott betete* —", footnotes: ["℘ Kap. 9,36; Lk 7,5", "℘ Kap. 16,14; 18,7"] },
      { number: 3, text: "sah in einer Erscheinung ungefähr um die neunte Stunde des Tages* deutlich, wie ein Engel Gottes zu ihm hereinkam* und zu ihm sagte: Kornelius!", footnotes: ["d. i. nachmittags etwa drei bis vier Stunden vor Sonnenuntergang; vgl. auch Anm. zu Mt 20,3\n℘ Kap. 3,1", "℘ Kap. 5,19"] },
      { number: 4, text: "Er aber sah ihn gespannt an und wurde von Furcht erfüllt* und sagte: Was ist, Herr? Er sprach aber zu ihm: Deine Gebete und deine Almosen sind hinaufgestiegen zum Gedächtnis vor Gott.", footnotes: ["℘ Lk 1,12"] },
      { number: 5, text: "Und jetzt sende Männer nach Joppe und lass Simon holen, der den Beinamen Petrus hat!" },
      { number: 6, text: "Dieser herbergt bei einem Gerber Simon, dessen Haus am Meer ist*.", footnotes: ["℘ Kap. 9,43"] },
      { number: 7, text: "Als aber der Engel, der mit ihm redete, weggegangen war, rief er zwei seiner Hausknechte und einen frommen Soldaten von denen, die beständig bei ihm waren;" },
      { number: 8, text: "und als er ihnen alles erzählt hatte, sandte er sie nach Joppe*.", footnotes: ["℘ V. 30-33"] },
      { number: 9, text: "*Am folgenden Tag aber, während jene reisten und sich der Stadt näherten, stieg Petrus um die sechste Stunde* auf das Dach, um zu beten*.", heading: "Des Petrus Sendung zu den Heiden nach Cäsarea", footnotes: ["℘ Kap. 11,5-12", "d. i. zwischen 11 und 12 Uhr vormittags; vgl. auch Anm. zu Mt 20,3", "℘ Dan 6,11"] },
      { number: 10, text: "Er wurde aber hungrig und verlangte zu essen. Während sie ihm aber zubereiteten, kam eine Verzückung über ihn*.", footnotes: ["℘ Kap. 22,17"] },
      { number: 11, text: "Und er sieht den Himmel geöffnet* und ein Gefäß, gleich einem großen, leinenen Tuch, herabkommen, an vier Zipfeln auf die Erde herabgelassen;", footnotes: ["℘ Kap. 7,56; Hes 1,1"] },
      { number: 12, text: "darin waren allerlei vierfüßige und kriechende Tiere der Erde und Vögel des Himmels." },
      { number: 13, text: "Und eine Stimme erging an ihn: Steh auf, Petrus, schlachte und iss!" },
      { number: 14, text: "Petrus aber sprach: Keineswegs, Herr! Denn niemals habe ich irgendetwas Gemeines* oder Unreines gegessen*.", footnotes: ["d. h. kultisch Unreines; entsprechend auch in V. 15.28", "℘ 3Mo 20,25; Hes 4,14"] },
      { number: 15, text: "Und wieder erging eine Stimme zum zweiten Mal an ihn: Was Gott gereinigt hat, mach du nicht gemein*!", footnotes: ["℘ Mt 15,11"] },
      { number: 16, text: "Dies aber geschah dreimal; und das Gefäß wurde sogleich hinaufgenommen in den Himmel." },
      { number: 17, text: "Als aber Petrus bei sich selbst in Verlegenheit war, was wohl diese Erscheinung bedeuten möchte, die er gesehen hatte, siehe, da standen die Männer, die von Kornelius gesandt waren und Simons Haus erfragt hatten, vor dem Tor;" },
      { number: 18, text: "und als sie gerufen hatten, erkundigten sie sich, ob Simon mit dem Beinamen Petrus dort herberge." },
      { number: 19, text: "Während aber Petrus über die Erscheinung nachsann, sprach der Geist zu ihm*: Siehe, drei Männer suchen dich.", footnotes: ["℘ Kap. 8,29"] },
      { number: 20, text: "Steh aber auf, geh hinab und zieh mit ihnen, ohne irgend zu zweifeln, weil ich sie gesandt habe!" },
      { number: 21, text: "Petrus aber ging zu den Männern hinab und sprach: Siehe, ich bin's, den ihr sucht. Was ist die Ursache, weshalb ihr kommt?" },
      { number: 22, text: "Sie aber sprachen: Kornelius, ein Hauptmann, ein gerechter und gottesfürchtiger Mann, und der ein gutes Zeugnis hat von der ganzen Nation der Juden, ist von einem heiligen Engel göttlich angewiesen worden, dich in sein Haus holen zu lassen und Worte von dir zu hören." },
      { number: 23, text: "Als er sie nun hereingerufen hatte, beherbergte er sie. Am folgenden Tag aber machte er sich auf und zog mit ihnen fort, und einige der Brüder von Joppe gingen mit ihm;" },
      { number: 24, text: "und am folgenden Tag kamen sie* nach Cäsarea. Kornelius aber, der seine Verwandten und nächsten Freunde zusammengerufen hatte, erwartete sie.", footnotes: ["mit anderen Handschr.: kam er"] },
      { number: 25, text: "*Als es aber geschah, dass Petrus hereinkam, ging Kornelius ihm entgegen, fiel ihm zu Füßen und huldigte ihm.", heading: "Petrus in Cäsarea — Bekehrung des Kornelius", footnotes: ["℘ Kap. 11,13-17"] },
      { number: 26, text: "Petrus aber richtete ihn auf und sprach: Steh auf! Auch ich bin ein Mensch*.", footnotes: ["℘ Kap. 14,14.15; Offb 19,10"] },
      { number: 27, text: "Und während er sich mit ihm unterhielt, ging er hinein und findet viele versammelt." },
      { number: 28, text: "Und er sprach zu ihnen: Ihr wisst, wie unerlaubt es für einen jüdischen Mann ist, sich einem Fremdling* anzuschließen oder zu ihm zu kommen*; und mir hat Gott gezeigt, keinen Menschen gemein oder unrein zu nennen.", footnotes: ["o. Stammesfremden, d. h. Nichtisraeliten", "℘ Kap. 11,2.3"] },
      { number: 29, text: "Darum kam ich auch ohne Widerrede, als ich geholt wurde. Ich frage nun: Aus welchem Grund habt ihr mich holen lassen?" },
      { number: 30, text: "Und Kornelius sprach: Vor vier Tagen betete ich in meinem Haus bis zu dieser, der neunten Stunde; und siehe, ein Mann stand vor mir in glänzendem Gewand*", footnotes: ["℘ Kap. 1,10"] },
      { number: 31, text: "und spricht: Kornelius! Dein Gebet ist erhört, und deiner Almosen ist gedacht worden vor Gott." },
      { number: 32, text: "Sende nun nach Joppe und lass Simon holen mit dem Beinamen Petrus! Dieser herbergt im Hause Simons, eines Gerbers, am Meer.*", footnotes: ["Andere Handschr. fügen hinzu: Der wird, wenn er hierher gekommen ist, zu dir reden."] },
      { number: 33, text: "Sofort nun sandte ich zu dir*, und du hast wohlgetan, dass du gekommen bist. Jetzt sind wir nun alle vor Gott zugegen, um alles zu hören, was dir vom Herrn aufgetragen ist*.", footnotes: ["℘ V. 3-8", "℘ 5Mo 5,27"] },
      { number: 34, text: "Petrus aber tat den Mund auf und sprach*: In Wahrheit begreife ich, dass Gott die Person nicht ansieht*,", footnotes: ["℘ Kap. 15,7", "℘ Mt 22,16; Röm 2,11; Gal 2,6; Eph 6,9; Kol 3,25; Jak 2,1; 1Petr 1,17"] },
      { number: 35, text: "sondern in jeder Nation ist, wer ihn fürchtet und Gerechtigkeit wirkt, ihm angenehm*.", footnotes: ["℘ Ps 15,2; 147,11; Röm 2,26"] },
      { number: 36, text: "Das Wort, das er den Söhnen Israels gesandt hat, indem er Frieden verkündigte* durch Jesus Christus* — dieser ist aller Herr* —", footnotes: ["o. als Evangelium verkündigte", "℘ Eph 2,17", "℘ Kap. 2,36; Röm 10,12; Offb 17,14"] },
      { number: 37, text: "kennt ihr; die Sache*, die, angefangen von Galiläa, durch ganz Judäa hin geschehen ist, nach der Taufe, die Johannes predigte*:", footnotes: ["o. Rede", "℘ Lk 3,3"] },
      { number: 38, text: "Jesus von Nazareth*, wie Gott ihn mit Heiligem Geist und mit Kraft gesalbt hat*, der umherging und wohltat und alle heilte, die von dem Teufel überwältigt waren*, denn Gott war mit ihm*.", footnotes: ["℘ Mt 2,23", "℘ Kap. 4,27", "℘ Mt 4,23", "℘ Kap. 2,22"] },
      { number: 39, text: "Und wir sind Zeugen alles dessen, was er sowohl im Lande der Juden als auch in Jerusalem getan hat*; den haben sie auch umgebracht, indem sie ihn an ein Holz hängten*.", footnotes: ["℘ Kap. 1,8.22", "℘ Kap. 2,36"] },
      { number: 40, text: "Diesen hat Gott am dritten Tag auferweckt* und ihn sichtbar werden lassen,", footnotes: ["℘ Kap. 2,24"] },
      { number: 41, text: "nicht dem ganzen Volk, sondern den von Gott zuvor erwählten Zeugen*, uns, die wir mit ihm gegessen und getrunken haben, nachdem er aus den Toten auferstanden war*.", footnotes: ["℘ Kap. 1,3.8; Joh 14,22", "℘ Lk 24,43; Joh 21,13"] },
      { number: 42, text: "Und er hat uns befohlen, dem Volk zu predigen* und eindringlich zu bezeugen, dass er der von Gott verordnete Richter der Lebenden und der Toten ist*.", footnotes: ["℘ Kap. 13,47; Mk 16,15", "℘ Kap. 17,31; Joh 5,22; Röm 14,9; 2Tim 4,1"] },
      { number: 43, text: "Diesem geben alle Propheten Zeugnis, dass jeder, der an ihn glaubt, Vergebung der Sünden empfängt durch seinen Namen*.", footnotes: ["℘ Kap. 4,12; Jes 53,5.6"] },
      { number: 44, text: "Während Petrus noch diese Worte redete, fiel der Heilige Geist auf alle, die das Wort hörten." },
      { number: 45, text: "Und die Gläubigen aus der Beschneidung, so viele ihrer mit Petrus gekommen waren, gerieten außer sich, dass auch auf die Nationen die Gabe des Heiligen Geistes ausgegossen worden war;" },
      { number: 46, text: "denn sie hörten sie in Sprachen* reden und Gott erheben*. Dann antwortete Petrus:", footnotes: ["o. Zungen", "℘ Kap. 2,4; 1Kor 14,2"] },
      { number: 47, text: "Könnte wohl jemand das Wasser verwehren, dass diese nicht getauft würden, die den Heiligen Geist empfangen haben wie auch wir?" },
      { number: 48, text: "Und er befahl, dass sie getauft würden im Namen Jesu Christi. Dann baten sie ihn, einige Tage zu bleiben*.", footnotes: ["℘ Joh 4,40"] },
    ]},
    { number: 11, verses: [
      { number: 1, text: "*Die Apostel aber und die Brüder, die in Judäa waren, hörten, dass auch die Nationen das Wort Gottes angenommen hatten*.", heading: "Petrus verteidigt in Jerusalem seine Sendung zu den Heiden", footnotes: ["℘ Kap. 10,9-48", "℘ Kap. 8,14"] },
      { number: 2, text: "Und als Petrus nach Jerusalem hinaufkam, stritten die aus der Beschneidung mit ihm" },
      { number: 3, text: "und sagten: Du bist bei unbeschnittenen Männern eingekehrt und hast mit ihnen gegessen*!", footnotes: ["℘ Kap. 10,28; Gal 2,12"] },
      { number: 4, text: "Petrus aber fing an und setzte es ihnen der Reihe nach auseinander und sprach:" },
      { number: 5, text: "Ich war in der Stadt Joppe im Gebet, und ich sah in einer Verzückung eine Erscheinung, wie ein Gefäß herabkam, gleich einem großen leinenen Tuch, an vier Zipfeln herabgelassen aus dem Himmel; und es kam bis zu mir." },
      { number: 6, text: "Und als ich gespannt hineinschaute, bemerkte und sah ich die vierfüßigen Tiere der Erde und die wilden Tiere und die kriechenden und die Vögel des Himmels." },
      { number: 7, text: "Ich hörte aber auch eine Stimme, die zu mir sagte: Steh auf, Petrus, schlachte und iss!" },
      { number: 8, text: "Ich sprach aber: Keineswegs, Herr! Denn niemals ist Gemeines* oder Unreines in meinen Mund gekommen.", footnotes: ["d. h. kultisch Unreines; entsprechend auch in V. 9"] },
      { number: 9, text: "Eine Stimme aber antwortete zum zweiten Mal aus dem Himmel: Was Gott gereinigt hat, mach du nicht gemein!" },
      { number: 10, text: "Dies aber geschah dreimal; und alles wurde wieder hinaufgezogen in den Himmel." },
      { number: 11, text: "Und siehe, sogleich standen vor dem Haus, in dem ich war, drei Männer, die von Cäsarea zu mir gesandt waren." },
      { number: 12, text: "Der Geist aber sagte mir, ich solle ohne Bedenken mit ihnen gehen*. Es kamen aber auch diese sechs Brüder mit mir, und wir kehrten in das Haus des Mannes ein.", footnotes: ["℘ Kap. 8,29"] },
      { number: 13, text: "Und er erzählte uns, wie er den Engel in seinem Haus habe stehen sehen und sagen: Sende nach Joppe und lass Simon mit dem Beinamen Petrus holen!" },
      { number: 14, text: "Der wird Worte zu dir reden, durch die du gerettet werden wirst, du und dein ganzes Haus*.", footnotes: ["℘ Kap. 16,15.31; 18,8; Joh 4,53"] },
      { number: 15, text: "Während ich aber zu reden begann, fiel der Heilige Geist auf sie, so wie auch auf uns im Anfang*.", footnotes: ["℘ Kap. 2,4"] },
      { number: 16, text: "Ich gedachte aber an das Wort des Herrn, wie er sagte: Johannes taufte zwar mit Wasser, ihr aber werdet mit* Heiligem Geist getauft werden*.", footnotes: ["o. in", "℘ Kap. 1,5"] },
      { number: 17, text: "Wenn nun Gott ihnen die gleiche Gabe gegeben hat wie auch uns, die wir an den Herrn Jesus Christus geglaubt haben*, wer war ich, dass ich hätte Gott wehren können? —", footnotes: ["℘ Kap. 5,32"] },
      { number: 18, text: "Als sie aber dies gehört hatten, beruhigten sie sich und verherrlichten Gott und sagten: Dann hat Gott also auch den Nationen die Buße gegeben zum Leben*.", footnotes: ["℘ Kap. 15,3; 20,21; Lk 24,47"] },
      { number: 19, text: "Die nun zerstreut waren durch die Bedrängnis, die wegen Stephanus entstanden war*, zogen hindurch bis nach Phönizien und Zypern und Antiochia und redeten zu niemand das Wort als allein zu Juden*.", heading: "Barnabas und Saulus bei Juden- und Heidenchristen in Antiochia", footnotes: ["℘ Kap. 8,1-4", "℘ Mt 10,6"] },
      { number: 20, text: "Es waren aber unter ihnen einige Männer von Zypern und Kyrene, die, als sie nach Antiochia kamen, auch zu den Griechen* redeten, indem sie das Evangelium von dem Herrn Jesus verkündigten.", footnotes: ["Darunter wurden alle griech. sprechenden und griech. beeinflussten nichtjüdischen Menschen des östl. Mittelmeerraumes verstanden."] },
      { number: 21, text: "Und des Herrn Hand war mit ihnen*, und eine große Zahl, die gläubig wurde, bekehrte sich zum Herrn*.", footnotes: ["℘ Lk 1,66", "℘ Kap. 9,35"] },
      { number: 22, text: "Es kam aber die Rede von ihnen zu den Ohren der Gemeinde* in Jerusalem, und sie sandten Barnabas aus*, dass er hindurchzöge bis nach Antiochia*;", footnotes: ["o. Versammlung", "℘ Kap. 4,36", "℘ Kap. 8,14"] },
      { number: 23, text: "der freute sich, als er hingekommen war und die Gnade Gottes sah, und ermahnte alle, mit Herzensentschluss bei dem Herrn zu verharren*.", footnotes: ["℘ Kap. 13,43; 14,22"] },
      { number: 24, text: "Denn er war ein guter Mann und voll Heiligen Geistes und Glaubens*. Und eine zahlreiche Menge wurde dem Herrn hinzugetan*.", footnotes: ["℘ Kap. 6,5", "℘ Kap. 2,47"] },
      { number: 25, text: "Er zog aber aus nach Tarsus, um Saulus aufzusuchen*;", footnotes: ["℘ Kap. 9,27.30"] },
      { number: 26, text: "und als er ihn gefunden hatte, brachte er ihn nach Antiochia. Es geschah ihnen aber, dass sie ein ganzes Jahr in der Gemeinde* zusammenkamen und eine zahlreiche Menge lehrten und dass die Jünger zuerst in Antiochia Christen genannt wurden*.", footnotes: ["o. Versammlung", "℘ Kap. 26,28; 1Petr 4,16"] },
      { number: 27, text: "In diesen Tagen aber kamen Propheten von Jerusalem nach Antiochia herab*.", heading: "Prophezeiung des Agabus", footnotes: ["℘ Kap. 13,1; 15,32"] },
      { number: 28, text: "Einer aber von ihnen, mit Namen Agabus*, stand auf und zeigte durch den Geist eine große Hungersnot an, die über den ganzen Erdkreis kommen sollte; sie trat auch unter Klaudius* ein.", footnotes: ["℘ Kap. 21,10", "römischer Kaiser (41—54 n. Chr.)\n℘ Kap. 18,2"] },
      { number: 29, text: "Sie beschlossen aber, dass, je nachdem wie einer der Jünger begütert war, jeder von ihnen zur Hilfeleistung den Brüdern, die in Judäa wohnten, etwas senden sollte*;", footnotes: ["℘ Gal 6,10"] },
      { number: 30, text: "das taten sie auch, indem sie es durch die Hand des Barnabas und Saulus an die Ältesten sandten*.", footnotes: ["℘ Kap. 12,25; 24,1; Röm 15,25.26; 1Kor 16,3.4; Gal 2,10"] },
    ]},
    { number: 12, verses: [
      { number: 1, text: "Um jene Zeit aber legte Herodes*, der König, Hand an einige von der Gemeinde*, sie zu misshandeln*;", heading: "Hinrichtung des Jakobus — Gefangenschaft und Befreiung des Petrus", footnotes: ["Herodes Agrippa I., unter römischer Oberherrschaft seit 37 n. Chr. König in Palästina, gestorben im Jahre 44 (vgl. V. 19—23). Danach wurde Palästina wieder einem römischen Statthalter unterstellt.", "o. Versammlung", "℘ Kap. 4,3"] },
      { number: 2, text: "er tötete aber Jakobus, den Bruder des Johannes*, mit dem Schwert*.", footnotes: ["℘ Mt 4,21", "℘ Mk 10,39; Lk 11,49"] },
      { number: 3, text: "Und als er sah, dass es den Juden gefiel*, ließ er weiterhin auch Petrus festnehmen — es waren aber die Tage der ungesäuerten Brote*.", footnotes: ["℘ Kap. 24,27; 25,9", "℘ 2Mo 12,15"] },
      { number: 4, text: "Den setzte er auch, nachdem er ihn ergriffen hatte, ins Gefängnis und übergab ihn an vier Abteilungen von je vier Soldaten zur Bewachung, wobei er beabsichtigte, ihn nach dem Passah dem Volk vorzuführen." },
      { number: 5, text: "Petrus nun wurde im Gefängnis verwahrt; aber von der Gemeinde* geschah ein anhaltendes Gebet für ihn zu Gott.", footnotes: ["o. Versammlung"] },
      { number: 6, text: "Als aber Herodes ihn vorführen wollte, schlief Petrus in jener Nacht zwischen zwei Soldaten, gebunden mit zwei Ketten, und Wächter vor der Tür verwahrten das Gefängnis." },
      { number: 7, text: "Und siehe, ein Engel des Herrn stand da*, und ein Licht leuchtete im Kerker; und er schlug Petrus an die Seite, weckte ihn und sagte: Steh schnell auf! Und die Ketten fielen ihm von den Händen*.", footnotes: ["℘ Kap. 5,19", "℘ Kap. 16,26"] },
      { number: 8, text: "Und der Engel sprach zu ihm: Gürte dich und binde deine Sandalen unter! Er aber tat es. Und er spricht zu ihm: Wirf dein Oberkleid um und folge mir!" },
      { number: 9, text: "Und er ging hinaus und folgte und wusste nicht, dass es Wirklichkeit war, was durch den Engel geschah; er meinte aber, eine Erscheinung zu sehen." },
      { number: 10, text: "Als sie aber durch die erste und die zweite Wache gegangen waren, kamen sie an das eiserne Tor, das in die Stadt führte, das sich ihnen von selbst öffnete; und sie traten hinaus und gingen eine Straße entlang, und sogleich schied der Engel von ihm." },
      { number: 11, text: "Und als Petrus zu sich selbst kam, sprach er: Nun weiß ich in Wahrheit, dass der Herr seinen Engel gesandt und mich gerettet hat* aus der Hand des Herodes und aller Erwartung des Volkes der Juden.", footnotes: ["℘ Ps 34,8; Dan 3,28; 6,23"] },
      { number: 12, text: "Und als er das erkannte, kam er an das Haus der Maria, der Mutter des Johannes mit dem Beinamen Markus*, wo viele versammelt waren und beteten.", footnotes: ["℘ V. 25; Kap. 13,5; 15,37; Kol 4,10; 2Tim 4,11; Phim 24; 1Petr 5,13"] },
      { number: 13, text: "Als er aber an die Tür des Tores klopfte, kam eine Magd mit Namen Rhode herbei, um zu öffnen*.", footnotes: ["w. gehorchen; hier als Fachausdruck für die Tätigkeit des Türhüters"] },
      { number: 14, text: "Und als sie die Stimme des Petrus erkannte, öffnete sie vor Freude das Tor nicht; sie lief aber hinein und verkündete, Petrus stehe vor dem Tor." },
      { number: 15, text: "Sie aber sprachen zu ihr: Du bist von Sinnen. Sie aber beteuerte, dass es so sei. Sie aber sprachen: Es ist sein Engel*.", footnotes: ["℘ Mt 18,10"] },
      { number: 16, text: "Petrus aber fuhr fort zu klopfen. Als sie aber geöffnet hatten, sahen sie ihn und waren außer sich." },
      { number: 17, text: "Er aber winkte ihnen mit der Hand, zu schweigen, und erzählte ihnen, wie der Herr ihn aus dem Gefängnis herausgeführt habe; und er sprach: Berichtet dies Jakobus* und den Brüdern! Und er ging hinaus und zog an einen anderen Ort.", footnotes: ["℘ Kap. 15,13; 21,18; Mt 13,55; Gal 1,19; Jak 1,1"] },
      { number: 18, text: "Als es aber Tag geworden war, gab es eine nicht geringe Bestürzung unter den Soldaten, was wohl aus Petrus geworden sei.", heading: "Ende des Königs Herodes (Agrippa I.)" },
      { number: 19, text: "Als aber Herodes nach ihm verlangte und ihn nicht fand*, zog er die Wächter zur Untersuchung und befahl, sie abzuführen*; und er ging von Judäa nach Cäsarea hinab und verweilte dort.", footnotes: ["℘ Kap. 5,22", "d. h. zur Hinrichtung"] },
      { number: 20, text: "Er war aber sehr erbittert gegen die Tyrer und Sidonier. Sie kamen aber einmütig zu ihm, und nachdem sie Blastus, den Kämmerer des Königs, überredet hatten, baten sie um Frieden, weil ihr Land von dem königlichen Land ernährt wurde." },
      { number: 21, text: "An einem festgesetzten Tag aber hielt Herodes, nachdem er königliche Kleider angelegt und sich auf den Thron* gesetzt hatte, eine öffentliche Rede an sie.", footnotes: ["o. Rednertribüne (im Theater)"] },
      { number: 22, text: "Das Volk aber rief ihm zu: Eines Gottes Stimme und nicht eines Menschen*!", footnotes: ["℘ Hes 28,2"] },
      { number: 23, text: "Sogleich aber schlug ihn ein Engel des Herrn, dafür, dass er nicht Gott die Ehre gab*. Und von Würmern zerfressen, verschied er.", footnotes: ["℘ Dan 5,23"] },
      { number: 24, text: "Das Wort Gottes aber wuchs und mehrte sich*.", footnotes: ["℘ Kap. 6,7"] },
      { number: 25, text: "Barnabas aber und Saulus kehrten, nachdem sie den Dienst erfüllt hatten*, von Jerusalem zurück und nahmen auch Johannes mit dem Beinamen Markus mit*.", heading: "Aussendung des Barnabas und Paulus zur ersten Missionsreise", footnotes: ["℘ Kap. 11,30", "℘ V. 12"] },
    ]},
    { number: 13, verses: [
      { number: 1, text: "Es waren aber in Antiochia, in der dortigen Gemeinde*, Propheten* und Lehrer*: Barnabas* und Simeon, genannt Niger, und Luzius von Kyrene und Manaën, der mit Herodes*, dem Vierfürsten*, auferzogen worden war, und Saulus.", footnotes: ["o. Versammlung", "℘ Kap. 11,27", "℘ Eph 4,11", "℘ Kap. 4,36", "Herodes Antipas (4 v. Chr. bis 39 n. Chr.); s. auch Anm. zu Mt 14,1", "℘ Mt 14,1"] },
      { number: 2, text: "Während sie aber dem Herrn dienten und fasteten, sprach der Heilige Geist: Sondert mir nun Barnabas und Saulus zu dem Werk aus, zu dem ich sie berufen habe*!", footnotes: ["℘ Kap. 9,15; Röm 1,1; 1Tim 1,12; 2,7"] },
      { number: 3, text: "Da fasteten und beteten sie; und als sie ihnen die Hände aufgelegt hatten*, entließen sie sie*.", footnotes: ["℘ Kap. 6,6", "℘ Kap. 14,26"] },
      { number: 4, text: "Sie nun, ausgesandt von dem Heiligen Geist, gingen hinab nach Seleuzia, und von dort segelten sie nach Zypern.", heading: "Barnabas und Paulus auf Zypern" },
      { number: 5, text: "Und als sie in Salamis waren, verkündigten sie das Wort Gottes in den Synagogen der Juden*. Sie hatten aber auch Johannes zum Diener*.", footnotes: ["℘ Kap. 14,1; 17,1.2; 18,4.19; 19,8", "℘ V. 13; Kap. 12,12"] },
      { number: 6, text: "Als sie aber die ganze Insel bis Paphos durchzogen hatten, fanden sie einen Mann, einen Magier, einen falschen Propheten, einen Juden, mit Namen Barjesus," },
      { number: 7, text: "der bei dem Prokonsul* Sergius Paulus war, einem verständigen Mann. Dieser rief Barnabas und Saulus herbei und begehrte das Wort Gottes zu hören.", footnotes: ["Ein Prokonsul verwaltete eine römische Provinz für den römischen Senat, ein Prokurator (in unserer Übersetzung »Statthalter«) für den römischen Kaiser."] },
      { number: 8, text: "Elymas aber, der Magier* — denn so wird sein Name übersetzt —, widerstand ihnen* und suchte den Prokonsul vom Glauben abzubringen.", footnotes: ["℘ Kap. 8,9", "℘ 2Tim 3,8"] },
      { number: 9, text: "Saulus aber, der auch Paulus heißt, blickte, mit Heiligem Geist erfüllt, fest auf ihn hin" },
      { number: 10, text: "und sprach: Du, voll aller List und aller Bosheit, Sohn des Teufels, Feind aller Gerechtigkeit! Willst du nicht aufhören, die geraden Wege des Herrn zu verkehren?" },
      { number: 11, text: "Und jetzt siehe, die Hand des Herrn ist auf dir! Und du wirst blind sein und die Sonne eine Zeit lang nicht sehen. Und sogleich fiel Dunkel und Finsternis auf ihn*; und er tappte umher und suchte solche, die ihn an der Hand leiteten.", footnotes: ["℘ 2Kö 6,18"] },
      { number: 12, text: "Dann, als der Prokonsul sah, was geschehen war, glaubte er, erstaunt über die Lehre des Herrn*.", footnotes: ["℘ Mt 7,28"] },
      { number: 13, text: "Als aber Paulus und seine Begleiter von Paphos abgefahren waren, kamen sie nach Perge in Pamphylien. Johannes aber sonderte sich von ihnen ab und kehrte nach Jerusalem zurück*.", heading: "Tätigkeit in Antiochia in Pisidien", footnotes: ["℘ Kap. 15,38"] },
      { number: 14, text: "Sie aber zogen von Perge aus hindurch und kamen nach Antiochia in Pisidien; und sie gingen am Tag des Sabbats* in die Synagoge* und setzten sich.", footnotes: ["℘ Kap. 16,13", "℘ V. 5"] },
      { number: 15, text: "Aber nach dem Vorlesen des Gesetzes und der Propheten* sandten die Vorsteher der Synagoge zu ihnen und sagten: Ihr Brüder *, wenn ihr ein Wort der Ermahnung an das Volk habt, so redet!", footnotes: ["℘ Kap. 15,21; Lk 4,16.17", "w. Männer, Brüder (ein Hebraismus, gew. bei der Anrede verwendet)"] },
      { number: 16, text: "Paulus aber stand auf, winkte mit der Hand und sprach*: Männer von Israel und ihr, die ihr Gott fürchtet, hört:", footnotes: ["℘ Kap. 21,40; 26,1"] },
      { number: 17, text: "Der Gott dieses Volkes Israel erwählte unsere Väter* und erhöhte das Volk in der Fremdlingschaft im Land Ägypten*, und mit erhobenem Arm führte er sie von dort heraus*;", footnotes: ["℘ 1Chr 16,13; Neh 9,7; Ps 135,4; Jes 41,8", "℘ Ps 105,24", "℘ 2Mo 12,51; 5Mo 4,37"] },
      { number: 18, text: "und eine Zeit von etwa vierzig Jahren ertrug er sie in der Wüste*.", footnotes: ["℘ 2Mo 16,35; 5Mo 1,31"] },
      { number: 19, text: "Und nachdem er sieben Nationen im Land Kanaan vertilgt hatte*, ließ er sie deren Land erben*", footnotes: ["℘ 5Mo 7,1", "℘ 5Mo 12,10"] },
      { number: 20, text: "für etwa vierhundertfünfzig Jahre. Und danach gab er ihnen* Richter bis zu Samuel, dem Propheten*.", footnotes: ["Andere Handschr. lesen: Und danach, für etwa 450 Jahre, gab er ihnen", "℘ Ri 2,16; 1Sam 3,20; 7,15"] },
      { number: 21, text: "Und von da an begehrten sie einen König*, und Gott gab ihnen Saul, den Sohn des Kisch, einen Mann aus dem Stamm Benjamin*, vierzig Jahre lang.", footnotes: ["℘ 1Sam 8,5", "℘ 1Sam 10,20-24"] },
      { number: 22, text: "Und nachdem er ihn verworfen hatte*, erweckte er ihnen David zum König*, welchem er auch Zeugnis gab und sprach: »Ich habe David gefunden*, den Sohn Isais, einen Mann nach meinem Herzen*, der meinen ganzen Willen tun wird.«*", footnotes: ["℘ 1Sam 15,23", "℘ 1Chr 10,14", "℘ Ps 89,21", "℘ 1Sam 13,14", "℘ V. 36; 1Kö 15,5"] },
      { number: 23, text: "Aus dessen Nachkommenschaft* hat Gott nach Verheißung* dem Israel als Retter Jesus gebracht*,", footnotes: ["w. Samen", "℘ 2Sam 7,12; Ps 132,11", "℘ Kap. 4,12; Mt 1,1.21"] },
      { number: 24, text: "nachdem Johannes vor dessen Auftreten die Taufe der Buße dem ganzen Volk Israel verkündigt hatte*.", footnotes: ["℘ Kap. 19,4; Mt 3,1-11"] },
      { number: 25, text: "Als aber Johannes seinen Lauf erfüllte, sprach er: Was ihr meint, dass ich sei, bin ich nicht, sondern siehe, es kommt einer nach mir, dem ich nicht würdig bin, die Sandale an den Füßen zu lösen*.", footnotes: ["℘ Mk 1,7"] },
      { number: 26, text: "Ihr Brüder*, Söhne des Geschlechts Abrahams und ihr, die unter euch Gott fürchten, uns ist das Wort dieser Rettung gesandt*.", footnotes: ["w. Männer, Brüder (ein Hebraismus, gew. bei der Anrede verwendet)", "℘ V. 46"] },
      { number: 27, text: "Denn die zu Jerusalem wohnen und ihre Obersten haben, da sie diesen nicht erkannten*, auch die Stimmen der Propheten erfüllt, die jeden Sabbat gelesen werden, indem sie über ihn Gericht hielten*.", footnotes: ["℘ Joh 8,19; 1Kor 2,8", "℘ Mk 14,53; Lk 24,44"] },
      { number: 28, text: "Und obschon sie keine todeswürdige Schuld fanden, baten sie den Pilatus, dass er umgebracht werde*.", footnotes: ["℘ Mt 27,23; Joh 19,15"] },
      { number: 29, text: "Und nachdem sie alles vollendet hatten, was über ihn geschrieben ist, nahmen sie ihn vom Holz herab und legten ihn in eine Gruft*.", footnotes: ["℘ Mt 27,59.60"] },
      { number: 30, text: "Gott aber hat ihn aus den Toten auferweckt*,", footnotes: ["℘ Kap. 2,24; 25,19"] },
      { number: 31, text: "und er ist mehrere Tage hindurch denen erschienen, die mit ihm hinaufgezogen waren von Galiläa nach Jerusalem, die jetzt seine Zeugen an das Volk sind*.", footnotes: ["℘ Kap. 1,3.8; 10,41"] },
      { number: 32, text: "Und wir verkündigen euch die gute Botschaft* von der zu den Vätern geschehenen Verheißung,", footnotes: ["o. das Evangelium"] },
      { number: 33, text: "dass Gott sie uns, ihren Kindern, erfüllt hat, indem er Jesus erweckte; wie auch im zweiten* Psalm geschrieben steht: »Du bist mein Sohn, heute habe ich dich gezeugt.«*", footnotes: ["Mehrere alte Handschr. lesen »im ersten«, da der 1. Psalm von den Juden nicht gezählt, sondern als Eingang des Psalters betrachtet wurde.", "℘ Ps 2,7; Hebr 1,5"] },
      { number: 34, text: "Dass er ihn aber aus den Toten auferweckt hat, so dass er nicht mehr zur Verwesung zurückkehrte, hat er so ausgesprochen: »Ich werde euch die zuverlässigen heiligen Güter Davids geben.«*", footnotes: ["℘ Jes 55,3"] },
      { number: 35, text: "Deshalb sagt er auch an einer anderen Stelle: »Du wirst nicht zugeben, dass dein Frommer die Verwesung sehe.«*", footnotes: ["℘ Kap. 2,31; Ps 16,10"] },
      { number: 36, text: "Denn David freilich entschlief, nachdem er seinem Geschlecht nach dem Willen Gottes gedient hatte*, und wurde zu seinen Vätern versammelt und sah die Verwesung*.", footnotes: ["℘ V. 22", "℘ Kap. 2,29"] },
      { number: 37, text: "Der aber, den Gott auferweckt hat, sah die Verwesung nicht*.", footnotes: ["℘ Kap. 2,31; Ps 16,10"] },
      { number: 38, text: "So sei es euch nun kund, ihr Brüder*, dass durch diesen euch Vergebung der Sünden verkündigt wird*; und von allem, wovon ihr durch das Gesetz Moses nicht gerechtfertigt werden konntet*,", footnotes: ["w. Männer, Brüder (ein Hebraismus, gew. bei der Anrede verwendet)", "℘ Kap. 5,31; 1Kor 15,17", "℘ Röm 8,3"] },
      { number: 39, text: "wird durch diesen jeder Glaubende gerechtfertigt*.", footnotes: ["℘ Röm 3,26; Gal 2,16; Hebr 9,15"] },
      { number: 40, text: "Seht nun zu, dass nicht eintreffe, was in den Propheten gesagt ist:" },
      { number: 41, text: "»Seht, ihr Verächter, und wundert euch und verschwindet! Denn ich wirke ein Werk in euren Tagen, ein Werk, das ihr nicht glauben werdet, wenn es euch jemand erzählt.«*", footnotes: ["℘ Hab 1,5"] },
      { number: 42, text: "Als sie aber hinausgingen, baten sie, dass am folgenden Sabbat diese Worte noch einmal zu ihnen geredet werden möchten." },
      { number: 43, text: "Als aber die Synagogenversammlung sich aufgelöst hatte, folgten viele der Juden und der anbetenden* Proselyten dem Paulus und Barnabas, die zu ihnen sprachen und ihnen zuredeten, beharrlich bei der Gnade Gottes zu bleiben*.", footnotes: ["»Anbetende« (Proselyten): Das ist die Bezeichnung für gottesfürchtige Heiden, die sich zur Synagoge hielten, ohne durch die Beschneidung Proselyten im echten Sinn (vgl. Anm. zu Mt 23,15) zu werden.", "℘ Kap. 11,23; 1Petr 5,12"] },
      { number: 44, text: "Am nächsten Sabbat aber versammelte sich fast die ganze Stadt, um das Wort Gottes zu hören." },
      { number: 45, text: "Als aber die Juden die Volksmengen sahen, wurden sie von Eifersucht* erfüllt* und widersprachen dem, was von Paulus geredet wurde, und lästerten*.", footnotes: ["o. Neid", "℘ Kap. 17,5", "℘ Kap. 14,2; 18,6"] },
      { number: 46, text: "Paulus aber und Barnabas sprachen freimütig: Zu euch musste notwendig das Wort Gottes zuerst geredet werden*; weil ihr es aber von euch stoßt und euch selber des ewigen Lebens nicht für würdig haltet, siehe, so wenden wir uns zu den Nationen*.", footnotes: ["℘ V. 26; Kap. 3,26", "℘ Kap. 18,6; 28,25-28; Mt 21,43; Röm 11,11"] },
      { number: 47, text: "Denn so hat uns der Herr geboten*: »Ich habe dich zum Licht der Nationen gesetzt, dass du zum Heil seiest bis an das Ende der Erde.«*", footnotes: ["℘ Kap. 10,42", "℘ Kap. 26,23; Jes 49,6; Lk 2,32"] },
      { number: 48, text: "Als aber die aus den Nationen es hörten, freuten sie sich* und verherrlichten das Wort des Herrn*; und es glaubten, so viele zum ewigen Leben verordnet waren*.", footnotes: ["℘ Kap. 8,8", "℘ 2Thes 3,1", "℘ Röm 8,29.30"] },
      { number: 49, text: "Das Wort des Herrn aber wurde ausgebreitet durch die ganze Gegend*.", footnotes: ["℘ Kap. 6,7"] },
      { number: 50, text: "Die Juden aber erregten die anbetenden* vornehmen Frauen und die Ersten der Stadt und erweckten eine Verfolgung gegen Paulus und Barnabas und vertrieben sie aus ihren Grenzen*.", footnotes: ["»Anbetende« (Proselyten): Das ist die Bezeichnung für gottesfürchtige Heiden, die sich zur Synagoge hielten, ohne durch die Beschneidung Proselyten im echten Sinn (vgl. Anm. zu Mt 23,15) zu werden.", "℘ Kap. 9,23; 1Thes 2,16; 2Tim 3,11"] },
      { number: 51, text: "Sie aber schüttelten den Staub von ihren Füßen gegen sie ab* und kamen nach Ikonion.", footnotes: ["℘ Kap. 18,6; Mt 10,14"] },
      { number: 52, text: "Die Jünger aber wurden mit Freude und Heiligem Geist erfüllt*.", footnotes: ["℘ 1Thes 1,6"] },
    ]},
    { number: 14, verses: [
      { number: 1, text: "Es geschah aber zu Ikonion, dass sie zusammen in die Synagoge der Juden gingen* und so redeten, dass eine große Menge, sowohl von Juden als auch von Griechen*, glaubte.", heading: "Aufenthalt in Ikonion", footnotes: ["℘ Kap. 13,5", "Darunter wurden alle griech. sprechenden und griech. beeinflussten nichtjüd. Menschen des östl. Mittelmeerraumes verstanden."] },
      { number: 2, text: "Die Juden aber, die nicht gehorchen wollten*, reizten und erbitterten die Seelen derer aus den Nationen gegen die Brüder*.", footnotes: ["o. die den Glaubensgehorsam verweigerten", "℘ Kap. 13,45"] },
      { number: 3, text: "Sie verweilten nun lange Zeit und sprachen freimütig in dem Herrn, der dem Wort seiner Gnade Zeugnis gab, indem er Zeichen und Wunder geschehen ließ durch ihre Hände*.", footnotes: ["℘ Kap. 2,43"] },
      { number: 4, text: "Die Menge der Stadt aber war entzweit, und die einen waren mit den Juden, die anderen mit den Aposteln*.", footnotes: ["℘ Lk 12,51.52"] },
      { number: 5, text: "Als aber ein heftiges Bestreben entstand, sowohl von denen aus den Nationen als auch von den Juden samt ihren Obersten, sie zu misshandeln und zu steinigen*,", footnotes: ["℘ V. 19; Kap. 9,23"] },
      { number: 6, text: "entflohen sie, als sie es bemerkten, in die Städte von Lykaonien, Lystra und Derbe und die Umgegend*;", footnotes: ["℘ Mt 10,23"] },
      { number: 7, text: "und dort verkündigten sie das Evangelium." },
      { number: 8, text: "Und ein Mann in Lystra saß da, kraftlos an den Füßen, lahm von seiner Mutter Leib an, der niemals umhergegangen war*.", heading: "Heilung eines Lahmen in Lystra — Steinigung des Paulus", footnotes: ["℘ Kap. 3,2"] },
      { number: 9, text: "Dieser hörte Paulus reden; als der ihn fest anblickte und sah, dass er Glauben hatte, geheilt* zu werden*,", footnotes: ["o. gerettet", "℘ Mt 9,28"] },
      { number: 10, text: "sprach er mit lauter Stimme: Stelle dich gerade hin auf deine Füße*! Und er sprang auf und ging umher*.", footnotes: ["℘ Hes 2,1", "℘ Kap. 9,34"] },
      { number: 11, text: "Als die Volksmengen aber sahen, was Paulus tat, erhoben sie ihre Stimme und sagten auf Lykaonisch: Die Götter sind den Menschen gleich geworden und sind zu uns herabgekommen*.", footnotes: ["℘ Kap. 28,6"] },
      { number: 12, text: "Und sie nannten den Barnabas Zeus, den Paulus aber Hermes*, weil er es war, der das Wort führte.", footnotes: ["Während Zeus bei den Griechen der höchste Gott war, hatte Hermes als Götterbote die Aufträge der Götter (z.B. an die Menschen) auszurichten."] },
      { number: 13, text: "Der Priester des Zeustempels aber, der vor der Stadt war, brachte Stiere und Kränze an die Tore und wollte mit den Volksmengen opfern." },
      { number: 14, text: "Als aber die Apostel Barnabas und Paulus es hörten, zerrissen sie ihre Kleider, sprangen hinaus unter die Volksmenge und riefen" },
      { number: 15, text: "und sprachen: Männer, warum tut ihr dies? Auch wir sind Menschen von gleichen Empfindungen wie ihr* und verkündigen euch*, dass ihr euch von diesen nichtigen Götzen* bekehren sollt zu dem lebendigen Gott*, der den Himmel und die Erde und das Meer gemacht hat und alles, was in ihnen ist*.", footnotes: ["℘ Kap. 10,26", "o. verkündigen euch als Evangelium", "℘ 1Sam 12,21; Jer 14,22; Jon 2,9", "℘ Jer 10,10; 1Thes 1,9", "℘ Kap. 4,24"] },
      { number: 16, text: "Er ließ in den vergangenen Geschlechtern alle Nationen in ihren eigenen Wegen gehen*,", footnotes: ["℘ Kap. 7,42; Ps 147,20"] },
      { number: 17, text: "obwohl er sich doch nicht unbezeugt gelassen hat*, indem er Gutes tat und euch vom Himmel Regen und fruchtbare Zeiten gab* und eure Herzen mit Speise und Fröhlichkeit erfüllte*.", footnotes: ["℘ Röm 1,19", "℘ Ps 65,11; Mt 5,45", "℘ Ps 147,8; Jer 5,24; 1Tim 6,17"] },
      { number: 18, text: "Und als sie dies sagten, beruhigten sie mit Mühe die Volksmengen, dass sie ihnen nicht opferten." },
      { number: 19, text: "Es kamen aber aus Antiochia und Ikonion Juden an, und nachdem sie die Volksmengen überredet und Paulus gesteinigt hatten*, schleiften sie ihn zur Stadt hinaus, da sie meinten, er sei gestorben*.", footnotes: ["℘ V. 5; Kap. 7,58", "℘ 2Kor 11,25; 2Tim 3,11"] },
      { number: 20, text: "Als aber die Jünger ihn umringten, stand er auf und ging in die Stadt hinein; und am folgenden Tag zog er mit Barnabas aus nach Derbe." },
      { number: 21, text: "Und als sie jener Stadt das Evangelium verkündigt und viele zu Jüngern gemacht hatten, kehrten sie nach Lystra und Ikonion und Antiochia zurück.", heading: "Evangeliumsverkündigung in Derbe und Rückkehr nach Antiochia" },
      { number: 22, text: "Sie stärkten* die Seelen der Jünger und ermahnten* sie, im Glauben zu verharren*, und sagten, dass wir durch viele Bedrängnisse in das Reich* Gottes hineingehen müssen*.", footnotes: ["℘ Kap. 15,41; 16,5; 18,23; Röm 1,11", "℘ Kap. 16,40", "℘ Kap. 11,23", "o. in die Königsherrschaft", "℘ 1Thes 3,3.4"] },
      { number: 23, text: "Als sie ihnen aber in jeder Gemeinde* Älteste gewählt hatten*, beteten* sie mit Fasten und befahlen sie dem Herrn, an den sie gläubig geworden waren.", footnotes: ["o. Versammlung", "℘ Tit 1,5", "℘ Kap. 6,6"] },
      { number: 24, text: "Und nachdem sie Pisidien durchzogen hatten, kamen sie nach Pamphylien;" },
      { number: 25, text: "und als sie in Perge das Wort geredet hatten, gingen sie hinab nach Attalia;" },
      { number: 26, text: "und von da segelten sie ab nach Antiochia, von wo sie der Gnade Gottes befohlen worden waren zu dem Werk, das sie erfüllt hatten*.", footnotes: ["℘ Kap. 13,1-3"] },
      { number: 27, text: "Als sie aber angekommen waren und die Gemeinde* zusammengebracht hatten, erzählten sie alles, was Gott mit ihnen getan* und dass er den Nationen eine Tür des Glaubens geöffnet habe*.", footnotes: ["o. Versammlung", "℘ Kap. 15,4.12; 21,19", "℘ 1Kor 16,9"] },
      { number: 28, text: "Sie verweilten aber eine nicht geringe Zeit bei den Jüngern*.", footnotes: ["℘ Kap. 15,33; 18,23"] },
    ]},
    { number: 15, verses: [
      { number: 1, text: "Und einige kamen von Judäa herab* und lehrten die Brüder: Wenn ihr nicht beschnitten worden seid nach der Weise Moses*, so könnt ihr nicht gerettet werden*.", heading: "Apostelkonzil zu Jerusalem", footnotes: ["℘ Gal 2,4.12", "℘ 3Mo 12,3", "℘ Gal 5,2"] },
      { number: 2, text: "Als nun ein Zwiespalt entstand und ein nicht geringer Wortwechsel zwischen ihnen und Paulus und Barnabas*, ordneten sie an, dass Paulus und Barnabas und einige andere von ihnen zu den Aposteln und Ältesten nach Jerusalem hinaufgehen sollten wegen dieser Streitfrage*.", footnotes: ["℘ Gal 2,5", "℘ Gal 2,1.2"] },
      { number: 3, text: "Sie nun erhielten von der Gemeinde* das Geleit, durchzogen Phönizien und Samaria und erzählten die Bekehrung derer aus den Nationen*; und sie machten allen Brüdern große Freude*.", footnotes: ["o. Versammlung", "℘ Röm 15,18", "℘ Kap. 11,18"] },
      { number: 4, text: "Als sie aber nach Jerusalem gekommen waren, wurden sie von der Gemeinde* und den Aposteln und Ältesten aufgenommen*, und sie verkündeten alles, was Gott mit ihnen getan hatte*.", footnotes: ["o. Versammlung", "℘ Kap. 21,17", "℘ Kap. 14,27"] },
      { number: 5, text: "Einige aber von denen aus der Sekte der Pharisäer, die gläubig waren, traten auf und sagten: Man muss sie beschneiden und ihnen gebieten, das Gesetz Moses zu halten*.", footnotes: ["℘ Gal 5,3"] },
      { number: 6, text: "Die Apostel aber und die Ältesten versammelten sich, um diese Angelegenheit zu besehen." },
      { number: 7, text: "Als aber viel Wortwechsel entstanden war, stand Petrus auf und sprach zu ihnen: Ihr Brüder*, ihr wisst, dass Gott mich vor langer Zeit unter euch auserwählt hat, dass die Nationen durch meinen Mund das Wort des Evangeliums hören und glauben sollten*.", footnotes: ["w. Männer, Brüder (ein Hebraismus, gew. bei der Anrede verwendet)", "℘ Kap. 10,34.35"] },
      { number: 8, text: "Und Gott, der Herzenskenner*, gab ihnen Zeugnis, indem er ihnen den Heiligen Geist gab wie auch uns*;", footnotes: ["℘ Kap. 1,24; Ps 44,22", "℘ Kap. 5,32"] },
      { number: 9, text: "und er machte keinen Unterschied zwischen uns und ihnen*, da er durch den Glauben ihre Herzen reinigte*.", footnotes: ["℘ Röm 10,12", "℘ Ps 51,9; Tit 2,14"] },
      { number: 10, text: "Nun denn, was versucht ihr Gott, ein Joch auf den Hals der Jünger zu legen, das weder unsere Väter noch wir zu tragen vermochten*?", footnotes: ["℘ Mt 23,4; Gal 4,3"] },
      { number: 11, text: "Vielmehr glauben wir, durch die Gnade des Herrn Jesus in derselben Weise gerettet zu werden* wie auch jene*.", footnotes: ["℘ Eph 2,8; Tit 3,7", "℘ Röm 3,22.23; Gal 2,15.16"] },
      { number: 12, text: "Die ganze Menge aber schwieg und hörte Barnabas und Paulus zu, die erzählten, wie viele Zeichen und Wunder Gott unter den Nationen durch sie getan habe*.", footnotes: ["℘ V. 4"] },
      { number: 13, text: "Als sie aber schwiegen, antwortete Jakobus* und sprach: Ihr Brüder*, hört mich!", footnotes: ["℘ Kap. 12,17", "w. Männer, Brüder (ein Hebraismus, gew. bei der Anrede verwendet)"] },
      { number: 14, text: "Simon hat erzählt, wie Gott zuerst darauf gesehen hat, aus den Nationen ein Volk zu nehmen für seinen Namen*.", footnotes: ["℘ V. 7-9"] },
      { number: 15, text: "Und hiermit stimmen die Worte der Propheten überein, wie geschrieben steht:" },
      { number: 16, text: "»Nach diesem will ich zurückkehren und wieder aufbauen die Hütte* Davids, die verfallen ist, und ihre Trümmer will ich wieder bauen und sie wieder aufrichten*;", footnotes: ["o. das Zelt", "℘ Jes 61,4"] },
      { number: 17, text: "damit die Übrigen der Menschen den Herrn suchen* und alle Nationen*, über die mein Name angerufen ist, spricht der Herr, der dieses tut«*,", footnotes: ["℘ Kap. 17,27", "℘ Ps 22,27.28; Sach 8,22", "℘ Am 9,11.12"] },
      { number: 18, text: "was von jeher* bekannt ist.", footnotes: ["o. von Ewigkeit (griech. Äon) her"] },
      { number: 19, text: "Deshalb urteile ich, man solle die, welche sich von den Nationen zu Gott bekehren, nicht beunruhigen," },
      { number: 20, text: "sondern ihnen schreiben, dass sie sich enthalten von den Verunreinigungen der Götzen* und von der Unzucht* und vom Erstickten und vom Blut*.", footnotes: ["℘ 1Kor 10,14.21", "o. Hurerei\n℘ 1Kor 6,13.18; Eph 5,3; Kol 3,5; 1Thes 4,3; Hebr 12,16", "℘ V. 29; Kap. 21,25; 1Mo 9,4; 3Mo 3,17; 17,12"] },
      { number: 21, text: "Denn Mose hat von alten Zeiten* her in jeder Stadt solche, die ihn predigen, da er an jedem Sabbat in den Synagogen gelesen wird*.", footnotes: ["o. Geschlechtern", "℘ Kap. 13,15.27"] },
      { number: 22, text: "Dann schien es den Aposteln und den Ältesten samt der ganzen Gemeinde* gut, Männer aus ihrer Mitte zu erwählen und sie mit Paulus und Barnabas nach Antiochia zu senden: Judas mit dem Beinamen Barsabbas* und Silas*, führende Männer unter den Brüdern.", heading: "Brief an die Gemeinde in Antiochia", footnotes: ["o. Versammlung", "℘ Kap. 1,23", "℘ V. 32.40; 1Thes 1,1; 1Petr 5,12"] },
      { number: 23, text: "Und sie schrieben und sandten durch ihre Hand: »Die Apostel und die Ältesten, eure Brüder, an die Brüder aus den Nationen zu Antiochia und in Syrien und Zilizien ihren Gruß." },
      { number: 24, text: "Weil wir gehört haben, dass einige, die aus unserer Mitte hervorgegangen sind, euch mit Worten beunruhigt und eure Seelen verstört haben — denen wir keine Befehle gegeben haben —," },
      { number: 25, text: "schien es uns, nachdem wir einstimmig geworden, gut, Männer auszuwählen und sie zu euch zu senden mit unseren geliebten Brüdern Barnabas und Paulus," },
      { number: 26, text: "Leuten, die ihr Leben hingegeben haben für den Namen unseres Herrn Jesus Christus*.", footnotes: ["℘ Kap. 13,50; 14,19"] },
      { number: 27, text: "Wir haben nun Judas und Silas gesandt, die auch selbst mündlich dasselbe verkünden werden." },
      { number: 28, text: "Denn es hat dem Heiligen Geist und uns gut geschienen, keine größere Last auf euch zu legen* als diese notwendigen Stücke:", footnotes: ["℘ Offb 2,24"] },
      { number: 29, text: "euch zu enthalten von Götzenopfern und von Blut und von Ersticktem und von Unzucht*. Wenn ihr euch davor bewahrt, so werdet ihr wohl tun*. Lebt wohl*!«", footnotes: ["o. Hurerei\n℘ V. 20", "o. so wird es euch wohlergehen", "℘ Kap. 16,4"] },
      { number: 30, text: "Nachdem sie nun entlassen waren, kamen sie nach Antiochia hinab; und sie versammelten die Menge und übergaben den Brief." },
      { number: 31, text: "Als sie ihn aber gelesen hatten, freuten sie sich über den Trost." },
      { number: 32, text: "Und Judas und Silas, die auch selbst Propheten waren*, ermunterten* die Brüder mit vielen Worten und stärkten sie.", footnotes: ["℘ Kap. 11,27", "o. ermahnten, trösteten"] },
      { number: 33, text: "Nachdem sie sich aber eine Zeit lang aufgehalten hatten*, wurden sie mit Frieden von den Brüdern entlassen zu denen, die sie gesandt hatten.", footnotes: ["℘ Kap. 14,28"] },
      { number: 34, text: "[T>]*", footnotes: ["Andere Handschr. fügen hinzu: Silas hielt es aber für gut, dort zu bleiben."] },
      { number: 35, text: "Paulus aber und Barnabas verweilten in Antiochia* und lehrten und verkündigten* mit noch vielen anderen das Wort des Herrn.", heading: "Paulus und Barnabas trennen sich — Paulus bricht mit Silas zur zweiten Missionsreise auf", footnotes: ["℘ Gal 2,11", "o. verkündigten als Evangelium"] },
      { number: 36, text: "Nach einigen Tagen aber sprach Paulus zu Barnabas: Lass uns nun zurückkehren und die Brüder besuchen in jeder Stadt, in der wir das Wort des Herrn verkündigt haben, und sehen, wie es ihnen geht*.", footnotes: ["℘ 2Kor 11,28"] },
      { number: 37, text: "Barnabas aber wollte auch Johannes, mit dem Beinamen Markus, mitnehmen*.", footnotes: ["℘ Kap. 12,12"] },
      { number: 38, text: "Paulus aber hielt es für richtig, den nicht mitzunehmen, der aus Pamphylien von ihnen gewichen und nicht mit ihnen gegangen war zu dem Werk*.", footnotes: ["℘ Kap. 13,13"] },
      { number: 39, text: "Es entstand nun eine Erbitterung, so dass sie sich voneinander trennten und Barnabas den Markus mitnahm und nach Zypern segelte." },
      { number: 40, text: "Paulus aber wählte sich Silas* und zog aus, von den Brüdern der Gnade Gottes befohlen.", footnotes: ["℘ V. 22"] },
      { number: 41, text: "Er durchzog aber Syrien und Zilizien und stärkte die Gemeinden*.", footnotes: ["o. Versammlungen\n℘ Kap. 14,22"] },
    ]},
    { number: 16, verses: [
      { number: 1, text: "Er gelangte aber nach Derbe und Lystra. Und siehe, dort war ein Jünger mit Namen Timotheus*, der Sohn einer jüdischen gläubigen Frau*, aber eines griechischen Vaters;", heading: "Timotheus wird Begleiter des Paulus", footnotes: ["℘ 2Kor 1,1; 1Tim 1,2", "℘ 2Tim 1,5"] },
      { number: 2, text: "er hatte ein gutes Zeugnis von den Brüdern in Lystra und Ikonion*.", footnotes: ["℘ Kap. 6,3"] },
      { number: 3, text: "Paulus wollte, dass dieser mit ihm ausziehe, und er nahm und beschnitt ihn um der Juden willen, die in jenen Orten waren*; denn sie kannten alle seinen Vater, dass er ein Grieche war*.", footnotes: ["℘ 1Kor 9,20", "℘ Gal 2,3"] },
      { number: 4, text: "Als sie aber die Städte durchzogen, teilten sie ihnen zur Befolgung die Beschlüsse mit, die von den Aposteln und Ältesten in Jerusalem festgesetzt waren*.", footnotes: ["℘ Kap. 15,23-29"] },
      { number: 5, text: "Die Gemeinden* nun wurden im Glauben gefestigt* und nahmen täglich an Zahl zu*.", footnotes: ["o. Versammlungen", "℘ Kap. 14,22; 1Thes 3,2", "w. wurden täglich überreich an Zahl\n℘ Kap. 2,47"] },
      { number: 6, text: "Sie durchzogen aber Phrygien und die galatische Landschaft*, nachdem sie von dem Heiligen Geist verhindert worden waren, das Wort in Asien* zu reden;", heading: "Ruf nach Mazedonien", footnotes: ["℘ Kap. 18,23", "Gemeint ist der westl. Teil Kleinasiens, die römische Provinz »Asia«; zuweilen wurde auch nur der südwestl. Teil Kleinasiens darunter verstanden."] },
      { number: 7, text: "als sie aber in die Nähe von Mysien kamen, versuchten sie, nach Bithynien zu reisen, und der Geist Jesu erlaubte es ihnen nicht." },
      { number: 8, text: "Als sie aber an Mysien vorübergezogen waren, gingen sie nach Troas hinab." },
      { number: 9, text: "Und es erschien dem Paulus in der Nacht ein Gesicht*: Ein mazedonischer Mann stand da und bat ihn und sprach: Komm herüber nach Mazedonien und hilf uns!", footnotes: ["℘ Kap. 9,12"] },
      { number: 10, text: "Als er aber das Gesicht gesehen hatte, suchten wir* sogleich nach Mazedonien abzureisen, da wir schlossen, dass Gott uns gerufen habe, ihnen das Evangelium zu verkündigen.", footnotes: ["Beginn des »Wir-Berichts«; deutet die Teilnahme des Verfassers Lukas an."] },
      { number: 11, text: "Wir fuhren nun von Troas ab und kamen geradewegs nach Samothrake und des folgenden Tages nach Neapolis", heading: "Reise nach Philippi — Bekehrung der Lydia" },
      { number: 12, text: "und von da nach Philippi*, das die erste Stadt jenes Teiles von Mazedonien ist, eine Kolonie*. In dieser Stadt aber verweilten wir einige Tage.", footnotes: ["℘ Phil 1,1", "Eine Kolonie war eine Stadt mit römischem Bürgerrecht; z. T. waren hier ausgediente Soldaten angesiedelt."] },
      { number: 13, text: "Und am Tag des Sabbats* gingen wir hinaus vor das Tor an einen Fluss, wo wir eine Gebetsstätte* vermuteten; und wir setzten uns nieder und redeten zu den Frauen, die zusammengekommen waren.", footnotes: ["℘ Kap. 13,14", "In Orten, in denen die Juden keine Synagoge besaßen, trafen sie sich an einer bestimmten Gebetsstätte, hier am Fluss, wahrscheinlich im Blick auf die Reinigungsgebote."] },
      { number: 14, text: "Und eine Frau mit Namen Lydia, eine Purpurkrämerin aus der Stadt Thyatira, die Gott anbetete*, hörte zu; deren Herz öffnete der Herr, dass sie achtgab auf das, was von Paulus geredet wurde.", footnotes: ["»Anbetende« wurden gottesfürchtige Heiden genannt, die sich zum jüd. Glauben und zur Synagoge hielten, ohne Proselyten im strengen Sinn (vgl. Anm. zu Mt 23,15) zu werden.\n℘ Kap. 10,2"] },
      { number: 15, text: "Als sie aber getauft worden war und ihr Haus*, bat sie und sagte: Wenn ihr urteilt, dass ich an den Herrn gläubig sei*, so kehrt in mein Haus ein und bleibt*! Und sie nötigte uns.", footnotes: ["℘ Kap. 11,14", "o. dass ich dem Herrn treu sei", "℘ Mt 10,11"] },
      { number: 16, text: "Es geschah aber, als wir zur Gebetsstätte gingen, dass uns eine Magd begegnete, die einen Wahrsagegeist* hatte; sie brachte ihren Herren großen Gewinn durch Wahrsagen*.", heading: "Die Magd mit dem Wahrsagegeist — Paulus und Silas in Gefangenschaft", footnotes: ["w. Geist Python; ein Ausdruck, der sich ursprünglich auf das wahrsagende Delphische Orakel bezieht, dann aber allgemein zur Bezeichnung eines Wahrsagegeistes gebraucht wurde", "℘ Kap. 19,24; 5Mo 18,10"] },
      { number: 17, text: "Diese folgte dem Paulus und uns nach und schrie und sprach: Diese Menschen sind Knechte* Gottes, des Höchsten*, die euch den Weg des Heils* verkündigen*.", footnotes: ["w. Sklaven", "℘ Kap. 19,15", "o. der Rettung", "℘ Jak 2,19"] },
      { number: 18, text: "Dies aber tat sie viele Tage. Paulus aber wurde unwillig, wandte sich um und sprach zu dem Geist: Ich gebiete dir im Namen Jesu Christi, von ihr auszufahren! Und er fuhr aus zu derselben Stunde*.", footnotes: ["℘ Kap. 5,16; Mk 1,25.26"] },
      { number: 19, text: "Als aber ihre Herren sahen, dass die Hoffnung auf ihren Gewinn dahin* war*, griffen sie Paulus und Silas und schleppten sie auf den Markt zu den Vorstehern*.", footnotes: ["w. ausgefahren", "℘ Kap. 19,27", "Gemeint ist die oberste Behörde der Stadt."] },
      { number: 20, text: "Und sie führten sie zu den Hauptleuten* und sprachen: Diese Menschen, die Juden sind, verwirren ganz und gar unsere Stadt*", footnotes: ["w. Strategen; so wurden im griech. Bereich zuweilen die beiden Prätoren genannt, die als oberste Beamte einer Kolonie (vgl. Anm. zu V. 12) vorstanden", "℘ Kap. 17,6"] },
      { number: 21, text: "und verkündigen Gebräuche, die anzunehmen oder auszuüben uns nicht erlaubt ist, da wir Römer sind*.", footnotes: ["℘ Kap. 18,13"] },
      { number: 22, text: "Und die Volksmenge erhob sich zusammen gegen sie, und die Hauptleute rissen ihnen die Kleider ab und befahlen, sie mit Ruten zu schlagen." },
      { number: 23, text: "Und als sie ihnen viele Schläge gegeben hatten*, warfen sie sie ins Gefängnis* und befahlen dem Kerkermeister, sie sicher zu verwahren*.", footnotes: ["℘ 2Kor 11,25", "℘ 2Kor 6,5", "℘ Kap. 4,3"] },
      { number: 24, text: "Dieser warf sie, als er solchen Befehl empfangen hatte, in das innere Gefängnis und befestigte ihre Füße im Block*.", footnotes: ["℘ 1Thes 2,2"] },
      { number: 25, text: "Um Mitternacht aber beteten Paulus und Silas und lobsangen Gott*; und die Gefangenen hörten ihnen zu.", heading: "Bekehrung des Kerkermeisters", footnotes: ["℘ Ps 119,62; Jak 5,13"] },
      { number: 26, text: "Plötzlich aber geschah ein großes Erdbeben, so dass die Grundfesten des Gefängnisses erschüttert wurden; und sofort öffneten sich alle Türen, und aller Fesseln lösten sich*.", footnotes: ["℘ Kap. 12,7"] },
      { number: 27, text: "Als aber der Kerkermeister aus dem Schlaf aufwachte und die Türen des Gefängnisses geöffnet sah, zog er das Schwert und wollte sich umbringen, da er meinte, die Gefangenen seien entflohen." },
      { number: 28, text: "Paulus aber rief mit lauter Stimme und sprach: Tu dir kein Leid an! Denn wir sind alle hier." },
      { number: 29, text: "Er aber forderte Licht und sprang hinein; und zitternd fiel er vor Paulus und Silas nieder." },
      { number: 30, text: "Und er führte sie heraus und sprach: Ihr Herren, was muss ich tun, dass ich gerettet werde*?", footnotes: ["℘ Kap. 2,37"] },
      { number: 31, text: "Sie aber sprachen: Glaube an den Herrn Jesus, und du wirst gerettet werden*, du und dein Haus*.", footnotes: ["℘ Kap. 20,21", "℘ Kap. 11,14"] },
      { number: 32, text: "Und sie redeten das Wort des Herrn zu ihm samt allen, die in seinem Haus waren." },
      { number: 33, text: "Und er nahm sie in jener Stunde der Nacht zu sich und wusch ihnen die Striemen ab; und er ließ sich taufen* und alle die Seinen sogleich*.", footnotes: ["o. er wurde getauft\n℘ Kap. 2,38", "℘ V. 15"] },
      { number: 34, text: "Und er führte sie hinauf in sein Haus, ließ ihnen den Tisch decken* und jubelte, an Gott gläubig geworden, mit seinem ganzen Haus.", footnotes: ["w. setzte ihnen einen Tisch vor"] },
      { number: 35, text: "Als es aber Tag geworden war, sandten die Hauptleute die Rutenträger und sagten: Lass jene Menschen los!", heading: "Befreiung des Paulus und Silas" },
      { number: 36, text: "Der Kerkermeister aber berichtete dem Paulus diese Worte: Die Hauptleute haben hergesandt, damit ihr losgelassen werdet. So geht denn jetzt hinaus und zieht hin in Frieden!" },
      { number: 37, text: "Paulus aber sprach zu ihnen: Nachdem sie uns, die wir Römer sind, öffentlich unverurteilt geschlagen*, haben sie uns ins Gefängnis geworfen, und jetzt stoßen sie uns heimlich aus? Nicht doch; sondern lass sie selbst kommen und uns hinausführen!", footnotes: ["℘ Kap. 22,25; 23,27"] },
      { number: 38, text: "Die Rutenträger aber meldeten diese Worte den Hauptleuten; und sie fürchteten sich, als sie hörten, dass sie Römer seien*.", footnotes: ["℘ Kap. 22,29"] },
      { number: 39, text: "Und sie kamen und redeten ihnen zu; und sie führten sie hinaus und baten sie, dass sie aus der Stadt gehen möchten*.", footnotes: ["℘ Lk 8,37"] },
      { number: 40, text: "Als sie aber aus dem Gefängnis herausgegangen waren, gingen sie zu Lydia; und als sie die Brüder gesehen hatten*, ermahnten* sie sie und zogen weg.", footnotes: ["℘ Kap. 14,22", "o. ermunterten, trösteten"] },
    ]},
    { number: 17, verses: [
      { number: 1, text: "Nachdem sie aber durch Amphipolis und Apollonia gereist waren, kamen sie nach Thessalonich*, wo eine Synagoge der Juden war.", heading: "Verkündigung und Verfolgung in Thessalonich", footnotes: ["℘ 1Thes 1,1"] },
      { number: 2, text: "Nach seiner Gewohnheit aber ging Paulus zu ihnen hinein* und unterredete sich an drei Sabbaten mit ihnen aus den Schriften*,", footnotes: ["℘ Kap. 13,5", "℘ Kap. 18,4"] },
      { number: 3, text: "indem er eröffnete und darlegte*, dass der Christus leiden und aus den Toten auferstehen musste*, und dass dieser der Christus ist; der Jesus, den ich euch verkündige*.", footnotes: ["℘ Kap. 28,23", "℘ Kap. 3,18", "℘ Kap. 5,42"] },
      { number: 4, text: "Und einige von ihnen ließen sich überzeugen* und gesellten sich zu Paulus und Silas und eine große Menge von den anbetenden* Griechen* und nicht wenige der vornehmsten Frauen*.", footnotes: ["℘ Kap. 28,24; 1Thes 2,13", "»Anbetende« wurden gottesfürchtige Nichtjuden genannt, die sich zur Synagoge hielten, ohne Proselyten im strengen Sinn (vgl. Anm. zu Mt 23,15) zu werden.", "℘ V. 17", "℘ V. 34"] },
      { number: 5, text: "Die Juden aber wurden eifersüchtig* und nahmen einige böse Männer vom Gassenpöbel zu sich, machten einen Volksauflauf und brachten die Stadt in Aufruhr; und sie traten vor das Haus Jasons und suchten sie unter das Volk zu führen.", footnotes: ["℘ Kap. 13,45"] },
      { number: 6, text: "Als sie sie aber nicht fanden, schleppten sie Jason und einige Brüder vor die Obersten der Stadt* und riefen: Diese, die den Erdkreis aufgewiegelt haben*, sind auch hierher gekommen,", footnotes: ["w. Politarchen; Titel der obersten Beamten in Thessalonich\n℘ 1Thes 3,4", "℘ Kap. 16,20"] },
      { number: 7, text: "die hat Jason beherbergt; und diese alle handeln gegen die Verordnungen des Kaisers, da sie sagen, dass ein anderer König sei: Jesus*.", footnotes: ["℘ Lk 23,2"] },
      { number: 8, text: "Sie beunruhigten aber die Volksmenge und die Obersten der Stadt, die dies hörten." },
      { number: 9, text: "Und nachdem sie von Jason und den Übrigen Bürgschaft genommen hatten, ließen sie sie frei." },
      { number: 10, text: "Die Brüder aber sandten sogleich in der Nacht sowohl Paulus als auch Silas nach Beröa; die gingen, als sie angekommen waren, in die Synagoge der Juden.", heading: "Verkündigung und Verfolgung in Beröa" },
      { number: 11, text: "Diese aber waren edler als die in Thessalonich; sie nahmen mit aller Bereitwilligkeit das Wort auf und untersuchten täglich die Schriften, ob dies sich so verhielte*.", footnotes: ["℘ Joh 5,39"] },
      { number: 12, text: "Viele nun von ihnen glaubten, und von den griechischen vornehmen Frauen und Männern nicht wenige." },
      { number: 13, text: "Als aber die Juden von Thessalonich erfuhren, dass auch in Beröa das Wort Gottes von Paulus verkündigt wurde, kamen sie auch dorthin und beunruhigten und erregten die Volksmengen*.", footnotes: ["℘ Kap. 9,23"] },
      { number: 14, text: "Da sandten aber die Brüder sogleich den Paulus fort*, dass er nach dem Meer hin gehe. Aber sowohl Silas als auch Timotheus blieben dort*.", footnotes: ["℘ 1Thes 2,15", "℘ 1Thes 3,1"] },
      { number: 15, text: "Die aber den Paulus geleiteten, brachten ihn bis nach Athen*; und als sie für Silas und Timotheus Befehl empfangen hatten, dass sie sobald wie möglich zu ihm kommen sollten, reisten sie ab*.", footnotes: ["℘ 1Thes 3,1", "℘ Kap. 18,5"] },
      { number: 16, text: "Während aber Paulus sie in Athen erwartete, wurde sein Geist in ihm erregt, da er die Stadt voll von Götzenbildern sah.", heading: "Paulus in Athen" },
      { number: 17, text: "Er unterredete sich nun in der Synagoge mit den Juden und mit den Anbetern* und auf dem Markt an jedem Tag mit denen, die gerade herbeikamen.", footnotes: ["»Anbetende« wurden gottesfürchtige Nichtjuden genannt, die sich zur Synagoge hielten, ohne Proselyten im strengen Sinn (vgl. Anm. zu Mt 23,15) zu werden.\n℘ V. 4"] },
      { number: 18, text: "Aber auch einige der epikureischen und stoischen Philosophen* griffen ihn an; und einige sagten: Was will wohl dieser Schwätzer sagen? Andere aber: Er scheint ein Verkündiger fremder Götter* zu sein, weil er das Evangelium von Jesus und der Auferstehung verkündigte.", footnotes: ["Anhänger griech. Philosophenschulen", "w. Dämonen"] },
      { number: 19, text: "Und sie ergriffen ihn, führten ihn zum Areopag* und sagten: Können wir erfahren, was diese neue Lehre ist, von der du redest?", footnotes: ["ein dem griech. Kriegsgott Ares geweihter Hügel in Athen, wo sich auch der athenische Gerichtshof befand"] },
      { number: 20, text: "Denn du bringst etwas Fremdes vor unsere Ohren. Wir möchten nun wissen, was das sein mag." },
      { number: 21, text: "Alle Athener aber und die Fremden, die sich da aufhielten, brachten ihre Zeit mit nichts anderem zu, als etwas Neues zu sagen und zu hören." },
      { number: 22, text: "Paulus aber stand mitten auf dem Areopag und sprach: Männer von Athen, ich sehe, dass ihr in jeder Beziehung den Göttern sehr ergeben* seid.", footnotes: ["w. dem Dämonendienst ergebener als andere"] },
      { number: 23, text: "Denn als ich umherging und eure Heiligtümer betrachtete, fand ich auch einen Altar, an dem die Aufschrift war: Einem unbekannten Gott. *Was ihr nun, ohne es zu kennen, verehrt, das* verkündige ich euch.", footnotes: ["mit mehreren alten Handschr.: Den ihr nun, ohne ihn zu kennen, verehrt, den", "mit mehreren alten Handschr.: Den ihr nun, ohne ihn zu kennen, verehrt, den"] },
      { number: 24, text: "Der Gott, der die Welt gemacht hat und alles, was darin ist*, er, der Herr des Himmels und der Erde*, wohnt nicht in Tempeln, die mit Händen gemacht sind*,", footnotes: ["℘ Kap. 4,24", "℘ Mt 11,25", "℘ Kap. 7,48"] },
      { number: 25, text: "auch wird er nicht von Menschenhänden bedient, als wenn er noch etwas nötig hätte*, da er selbst allen Leben und Odem* und alles gibt*.", footnotes: ["℘ Ps 50,9.12", "℘ 1Mo 2,7; Ps 104,30; Jes 42,5", "℘ 1Kor 8,6"] },
      { number: 26, text: "Und er hat aus einem* jede Nation der Menschen* gemacht, dass sie auf dem ganzen Erdboden wohnen*, wobei er festgesetzte Zeiten und die Grenzen ihrer Wohnung bestimmt hat*,", footnotes: ["mit mehreren alten Handschr.: aus einem Blute", "o. das ganze Menschengeschlecht", "℘ 1Mo 9,19", "℘ 5Mo 32,8; Hi 14,5; Ps 74,17"] },
      { number: 27, text: "dass sie Gott suchen*, ob sie ihn vielleicht tastend fühlen und finden möchten, obwohl er ja* nicht fern ist von jedem von uns*.", footnotes: ["℘ Kap. 15,17", "o. der ja wirklich", "℘ Röm 1,19"] },
      { number: 28, text: "Denn in ihm leben wir und bewegen uns und sind wir, wie auch einige eurer Dichter* gesagt haben: Denn wir sind auch sein Geschlecht*.", footnotes: ["Gemeint ist wahrscheinlich hauptsächlich der griech. Dichter Aratus; er lebte im 3. Jh. v. Chr. in Zilizien, also in des Paulus Heimat. Der Satz findet sich auch bei dem stoischen Philosophen Kleanthes.", "℘ Ps 82,6"] },
      { number: 29, text: "Da wir nun Gottes Geschlecht sind*, sollen wir nicht meinen, dass das Göttliche dem Gold und Silber oder Stein, einem Gebilde der Kunst und der Erfindung des Menschen, gleich sei*.", footnotes: ["℘ 1Mo 1,27", "℘ Kap. 19,26; Jes 40,18; Röm 1,23"] },
      { number: 30, text: "Nachdem nun Gott die Zeiten der Unwissenheit übersehen hat, gebietet er jetzt den Menschen, dass sie alle überall Buße tun sollen*,", footnotes: ["℘ Kap. 26,20; Lk 24,47"] },
      { number: 31, text: "weil er einen Tag festgesetzt hat, an dem er den Erdkreis richten wird* in Gerechtigkeit* durch einen Mann, den er dazu bestimmt hat*, und er hat allen dadurch den Beweis gegeben, dass er ihn auferweckt hat aus den Toten*.", footnotes: ["℘ Mt 12,36", "℘ Ps 9,9", "℘ Kap. 10,42; Röm 2,16", "℘ Kap. 2,24"] },
      { number: 32, text: "Als sie aber von Totenauferstehung hörten, spotteten die einen*, die anderen aber sprachen: Wir wollen dich darüber auch nochmals hören*.", footnotes: ["℘ Kap. 23,8", "℘ Kap. 24,25"] },
      { number: 33, text: "So ging Paulus aus ihrer Mitte fort." },
      { number: 34, text: "Einige Männer aber schlossen sich ihm an und glaubten, unter denen auch Dionysius war, der Areopagit*, und eine Frau mit Namen Damaris und andere mit ihnen*.", footnotes: ["Mitglied des Gerichtshofes; vgl. Anm. zu V. 19", "℘ V. 4"] },
    ]},
    { number: 18, verses: [
      { number: 1, text: "Danach schied er von Athen und kam nach Korinth*.", heading: "Tätigkeit des Paulus in Korinth", footnotes: ["℘ 1Kor 1,2; 2,1"] },
      { number: 2, text: "Und er fand einen Juden namens Aquila, aus Pontus gebürtig, der kürzlich aus Italien gekommen war, und Priszilla*, seine Frau — weil Klaudius* befohlen hatte, dass alle Juden sich aus Rom entfernen sollten*. Er ging zu ihnen,", footnotes: ["℘ V. 18.26; Röm 16,3; 1Kor 16,19; 2Tim 4,19", "℘ Kap. 11,28", "Kaiser Klaudius (41—54 n. Chr.) hatte diesen Befehl im Jahre 49 erlassen."] },
      { number: 3, text: "und weil er gleichen Handwerks war, blieb er bei ihnen und arbeitete*; denn sie waren Zeltmacher ihres Handwerks.", footnotes: ["℘ Kap. 20,34; 1Kor 4,12; 2Kor 11,27; 1Thes 2,9; 2Thes 3,8"] },
      { number: 4, text: "Er unterredete sich aber in der Synagoge an jedem Sabbat* und überzeugte Juden und Griechen*.", footnotes: ["℘ Kap. 13,5", "℘ 1Kor 3,6"] },
      { number: 5, text: "Als aber sowohl Silas als auch Timotheus aus Mazedonien herabkamen*, wurde Paulus durch das Wort gedrängt und bezeugte den Juden, dass Jesus der Christus sei*.", footnotes: ["℘ Kap. 17,14.15; 2Kor 1,19; 1Thes 3,6", "℘ Kap. 5,42"] },
      { number: 6, text: "Als sie aber widerstrebten und lästerten*, schüttelte er die Kleider aus* und sprach zu ihnen: Euer Blut komme auf euren Kopf! Ich bin rein*; von jetzt an werde ich zu den Nationen gehen*.", footnotes: ["℘ Kap. 13,45", "℘ Kap. 13,51", "d. h. von eurem Blut\n℘ Kap. 20,26; Hes 3,19", "℘ Kap. 13,46"] },
      { number: 7, text: "Und er ging von dort fort und kam in das Haus eines Gottesfürchtigen* namens Titius Justus, dessen Haus an die Synagoge stieß.", footnotes: ["w. eines Gott Anbetenden; so wurden Nichtjuden genannt, die sich zur Synagoge hielten, ohne Proselyten im strengen Sinn (vgl. Anm. zu Mt 23,15) zu werden\n℘ Kap. 10,2"] },
      { number: 8, text: "Krispus aber, der Vorsteher der Synagoge, glaubte an den Herrn mit seinem ganzen Haus*; und viele Korinther, die hörten, wurden gläubig und ließen sich taufen*.", footnotes: ["℘ Kap. 11,14; 1Kor 1,14", "w. wurden getauft\n℘ Kap. 2,41"] },
      { number: 9, text: "Der Herr aber sprach durch eine Erscheinung in der Nacht zu Paulus*: Fürchte dich nicht*, sondern rede, und schweige nicht!", footnotes: ["℘ Kap. 9,12", "℘ Kap. 27,24; 1Kor 2,3"] },
      { number: 10, text: "Denn ich bin mit dir*, und niemand soll dich angreifen, dir Böses zu tun; denn ich habe ein großes Volk in dieser Stadt.", footnotes: ["℘ 1Mo 28,15; 2Mo 3,12; Jos 1,5; Jes 41,10; 43,5; Jer 1,8"] },
      { number: 11, text: "Und er hielt sich ein Jahr und sechs Monate dort auf und lehrte unter ihnen das Wort Gottes*.", footnotes: ["℘ 1Kor 3,6"] },
      { number: 12, text: "Als aber Gallio Prokonsul von Achaja war*, traten die Juden einmütig gegen Paulus auf* und führten ihn vor den Richterstuhl", heading: "Vergebliche Anklage vor dem Prokonsul Gallio in Korinth", footnotes: ["Er war es im Jahre 51/52 n. Chr.; vgl. auch Anm. zu Kap. 13,7.", "℘ Kap. 9,23"] },
      { number: 13, text: "und sagten: Dieser überredet die Menschen, Gott entgegen dem Gesetz* zu verehren*.", footnotes: ["d. h. in gesetzwidriger Weise", "℘ Kap. 16,21"] },
      { number: 14, text: "Als aber Paulus den Mund öffnen wollte, sagte Gallio zu den Juden: Wenn es ein Unrecht oder eine böse Handlung wäre, Juden, so hätte ich euch vernünftigerweise ertragen;" },
      { number: 15, text: "wenn es aber Streitfragen sind über Worte und Namen* und das Gesetz, das ihr habt*, so seht ihr selbst zu, über diese Dinge will ich nicht Richter sein*.", footnotes: ["o. Personen", "℘ Kap. 25,19", "℘ Kap. 23,29; Joh 18,31"] },
      { number: 16, text: "Und er trieb sie von dem Richterstuhl weg." },
      { number: 17, text: "Alle aber ergriffen Sosthenes*, den Vorsteher der Synagoge, und schlugen ihn vor dem Richterstuhl; und Gallio bekümmerte sich nicht um dies alles.", footnotes: ["℘ 1Kor 1,1"] },
      { number: 18, text: "Nachdem aber Paulus noch viele Tage dageblieben war, nahm er Abschied von den Brüdern und segelte nach Syrien ab und mit ihm Priszilla und Aquila, nachdem er sich in Kenchreä das Haupt hatte scheren lassen, denn er hielt ein Gelübde*.", heading: "Rückreise über Ephesus nach Antiochia", footnotes: ["℘ Kap. 21,23.24"] },
      { number: 19, text: "Sie kamen aber nach Ephesus*, und er ließ jene dort zurück; er selbst aber ging in die Synagoge und unterredete sich mit den Juden*.", footnotes: ["℘ Eph 1,1", "℘ Kap. 13,5"] },
      { number: 20, text: "Als sie ihn aber baten, dass er längere Zeit bleiben möchte, willigte er nicht ein," },
      { number: 21, text: "sondern nahm Abschied von ihnen und sagte: Ich werde, wenn Gott will*, wieder zu euch zurückkehren*. Und er fuhr von Ephesus ab.", footnotes: ["℘ 1Kor 4,19; Hebr 6,3; Jak 4,15", "℘ Kap. 19,1"] },
      { number: 22, text: "Und als er zu Cäsarea gelandet war, ging er hinauf* und begrüßte die Gemeinde* und zog hinab nach Antiochia.", footnotes: ["d. h. nach Jerusalem\n℘ Kap. 21,15", "o. Versammlung"] },
      { number: 23, text: "Und als er einige Zeit dort zugebracht hatte*, reiste er ab und durchzog der Reihe nach die galatische Landschaft und Phrygien* und stärkte alle Jünger*.", heading: "Beginn der dritten Missionsreise des Paulus — Apollos in Ephesus", footnotes: ["℘ Kap. 14,28", "℘ Kap. 16,6", "℘ Kap. 14,22"] },
      { number: 24, text: "Ein Jude aber mit Namen Apollos*, aus Alexandria gebürtig, ein beredter Mann, der mächtig war in den Schriften, kam nach Ephesus.", footnotes: ["℘ 1Kor 3,5.6; Tit 3,13"] },
      { number: 25, text: "Dieser war im Weg des Herrn unterwiesen, und, brennend im Geist*, redete und lehrte er sorgfältig die Dinge von Jesus, obwohl er nur die Taufe des Johannes kannte*.", footnotes: ["℘ Röm 12,11", "℘ Kap. 19,3.4"] },
      { number: 26, text: "Und dieser fing an, freimütig in der Synagoge zu reden. Als aber Priszilla und Aquila* ihn hörten, nahmen sie ihn zu sich und legten ihm den Weg Gottes genauer aus.", footnotes: ["℘ V. 2"] },
      { number: 27, text: "Als er aber nach Achaja reisen wollte, schrieben die Brüder den Jüngern und ermahnten* sie, ihn aufzunehmen*. Dieser war, als er hinkam, den Glaubenden durch die Gnade sehr behilflich;", footnotes: ["o. ermunterten", "℘ 3Jo 8"] },
      { number: 28, text: "denn kräftig widerlegte er die Juden öffentlich, indem er durch die Schriften bewies, dass Jesus der Christus ist*.", footnotes: ["℘ Kap. 5,42"] },
    ]},
    { number: 19, verses: [
      { number: 1, text: "Es geschah aber, während Apollos in Korinth war, dass Paulus, nachdem er die höher gelegenen Gegenden durchzogen hatte, nach Ephesus kam*. Und er fand einige Jünger", heading: "Paulus und die Johannesjünger in Ephesus", footnotes: ["℘ Kap. 18,21; 1Kor 16,8"] },
      { number: 2, text: "und sprach zu ihnen: Habt ihr den Heiligen Geist empfangen, als ihr gläubig geworden seid*? Sie aber sprachen zu ihm: Wir haben nicht einmal gehört, ob der Heilige Geist überhaupt da ist.", footnotes: ["℘ Kap. 2,38"] },
      { number: 3, text: "Und er sprach: Worauf seid ihr denn getauft worden? Sie aber sagten: Auf die Taufe des Johannes." },
      { number: 4, text: "Paulus aber sprach: Johannes hat mit der Taufe der Buße getauft*, indem er dem Volk sagte, dass sie an den glauben sollten, der nach ihm komme, das ist an Jesus*.", footnotes: ["w. Johannes hat die Taufe der Buße (o. der Sinnesänderung) getauft\n℘ Kap. 13,24", "℘ Joh 1,15.27"] },
      { number: 5, text: "Als sie es aber gehört hatten, ließen sie sich auf den Namen des Herrn Jesus taufen*;", footnotes: ["w. wurden sie auf den Namen des Herrn Jesus getauft"] },
      { number: 6, text: "und als Paulus ihnen die Hände aufgelegt hatte, kam der Heilige Geist auf sie*, und sie redeten in Sprachen* und weissagten*.", footnotes: ["℘ Kap. 8,16.17", "o. Zungen\n℘ Kap. 2,4", "℘ 1Kor 14,39"] },
      { number: 7, text: "Es waren aber insgesamt etwa zwölf Männer." },
      { number: 8, text: "Er ging aber in die Synagoge* und sprach freimütig drei Monate lang, indem er sich mit ihnen unterredete und sie von den Dingen des Reiches* Gottes überzeugte*.", heading: "Tätigkeit des Paulus in Ephesus", footnotes: ["℘ Kap. 13,5", "o. der Königsherrschaft", "℘ Kap. 1,3"] },
      { number: 9, text: "Als aber einige sich verhärteten und ungehorsam blieben* und vor der Menge schlecht redeten von dem Weg*, trennte er sich von ihnen und sonderte die Jünger ab und redete täglich in der Schule des Tyrannus.", footnotes: ["o. den Glaubensgehorsam verweigerten", "d. h. von dem Weg Christi o. des christlichen Bekenntnisses\n℘ Kap. 9,2"] },
      { number: 10, text: "Dies aber geschah zwei Jahre lang, so dass alle, die in Asien* wohnten, sowohl Juden als auch Griechen, das Wort des Herrn hörten*.", footnotes: ["d. i. die röm. Provinz Asien; vgl. auch Anm. zu Kap. 16,6", "℘ Kap. 20,21"] },
      { number: 11, text: "Und ungewöhnliche Wunderwerke* tat Gott durch die Hände des Paulus*,", footnotes: ["o. Machttaten; griech. dynamis", "℘ Kap. 2,43; Röm 15,18"] },
      { number: 12, text: "so dass man sogar Schweißtücher oder Schurze von seinem Leib weg auf die Kranken legte und die Krankheiten von ihnen wichen und die bösen Geister ausfuhren*.", footnotes: ["℘ Kap. 5,5.16"] },
      { number: 13, text: "Aber auch einige von den umherziehenden jüdischen Beschwörern unternahmen es, über die, welche böse Geister hatten, den Namen des Herrn Jesus anzurufen*, indem sie sagten: Ich beschwöre euch bei dem Jesus, den Paulus predigt!", footnotes: ["w. zu nennen"] },
      { number: 14, text: "Es waren aber sieben Söhne eines jüdischen Hohenpriesters Skevas, die dies taten." },
      { number: 15, text: "Der böse Geist aber antwortete und sprach zu ihnen: Jesus kenne ich, und von Paulus weiß ich*. Aber ihr, wer seid ihr?", footnotes: ["℘ Kap. 16,17"] },
      { number: 16, text: "Und der Mensch, in dem der böse Geist war, sprang auf sie los und bezwang sie miteinander und überwältigte sie, so dass sie nackt und verwundet aus jenem Haus entflohen." },
      { number: 17, text: "Dies aber wurde allen bekannt, sowohl Juden als auch Griechen, die zu Ephesus wohnten; und Furcht fiel auf sie alle*, und der Name des Herrn Jesus wurde erhoben.", footnotes: ["℘ Kap. 5,5.11"] },
      { number: 18, text: "Viele aber von denen, die gläubig geworden waren, kamen und bekannten und gestanden ihre Taten." },
      { number: 19, text: "Zahlreiche aber von denen, die Zauberei* getrieben hatten*, trugen die Bücher zusammen und verbrannten sie vor allen; und sie berechneten ihren Wert und kamen auf 50 000 Silberdrachmen*.", footnotes: ["w. vorwitzige Sachen", "℘ 5Mo 18,10.11", "w. Silbergeldstücke; s. Tabelle »Münzen und Geldeinheiten«"] },
      { number: 20, text: "So wuchs das Wort des Herrn mit Macht und erwies sich kräftig*.", footnotes: ["℘ Kap. 6,7"] },
      { number: 21, text: "Als dies aber beendet war, nahm sich Paulus im Geist vor, nachdem er Mazedonien und Achaja durchzogen habe*, nach Jerusalem zu reisen*, und sprach: Nachdem ich dort gewesen bin, muss ich auch Rom sehen*.", footnotes: ["℘ Kap. 20,1.2; 1Kor 16,5", "℘ Kap. 20,16.22; Röm 15,25", "℘ Kap. 23,11; Röm 1,10.11"] },
      { number: 22, text: "Er sandte aber zwei von denen, die ihm halfen, Timotheus und Erastus*, nach Mazedonien, und er selbst verweilte eine Zeit lang in Asien.", footnotes: ["℘ Röm 16,23; 2Tim 4,20"] },
      { number: 23, text: "Es entstand aber um jene Zeit ein nicht geringer Aufruhr betreffs des Weges*.", heading: "Der Aufstand des Demetrius", footnotes: ["d. h. des Weges Christi o. der christlichen Nachfolge\n℘ Kap. 9,2"] },
      { number: 24, text: "Denn einer mit Namen Demetrius, ein Silberschmied, der silberne Tempel der Artemis machte, verschaffte den Kunsthandwerkern nicht geringen Erwerb*;", footnotes: ["℘ Kap. 16,16"] },
      { number: 25, text: "und nachdem er diese samt den damit beschäftigten Arbeitern versammelt hatte, sprach er: Männer, ihr wisst, dass aus diesem Erwerb unser Wohlstand kommt;" },
      { number: 26, text: "und ihr seht und hört, dass dieser Paulus nicht allein von Ephesus, sondern beinahe von ganz Asien* eine große Volksmenge überredet und abgewandt hat, da er sagt, dass das keine Götter seien, die mit Händen gemacht werden*.", footnotes: ["d. i. die röm. Provinz Asien; vgl. auch Anm. zu Kap. 16,6", "℘ Kap. 17,29"] },
      { number: 27, text: "Nicht allein aber ist für uns Gefahr, dass dieses Geschäft in Verruf kommt*, sondern auch, dass der Tempel der großen Göttin Artemis für nichts erachtet und auch ihre herrliche Größe, die ganz Asien* und der Erdkreis verehrt, vernichtet wird.", footnotes: ["℘ Kap. 16,19", "d. i. die röm. Provinz Asien; vgl. auch Anm. zu Kap. 16,6"] },
      { number: 28, text: "Als sie aber das hörten, wurden sie voller Wut*, schrien und sagten: Groß ist die Artemis der Epheser!", footnotes: ["℘ 2Kor 11,26"] },
      { number: 29, text: "Und die Stadt geriet in Verwirrung; und sie stürmten einmütig nach dem Theater und rissen die Mazedonier Gajus und Aristarch*, die Reisegefährten des Paulus, mit fort.", footnotes: ["℘ Kap. 20,4; 27,2; Kol 4,10; Phim 24"] },
      { number: 30, text: "Als aber Paulus unter das Volk gehen wollte, ließen die Jünger es nicht zu." },
      { number: 31, text: "Und auch einige von den Asiarchen*, die seine Freunde waren, sandten zu ihm und baten ihn, sich nicht nach dem Theater zu begeben.", footnotes: ["Beamte, die für den Kaiserkult (göttliche Verehrung der röm. Kaiser) in der röm. Provinz Asia (vgl. Anm. zu Kap. 16,6) verantwortlich waren."] },
      { number: 32, text: "Die einen nun schrien dies, die anderen jenes; denn die Versammlung war in Verwirrung, und die meisten wussten nicht, weshalb sie zusammengekommen waren." },
      { number: 33, text: "Aus der Volksmenge heraus verständigte man den Alexander*, den die Juden vorschoben. Alexander aber winkte mit der Hand und wollte sich vor dem Volk verantworten.", footnotes: ["℘ 1Tim 1,20; 2Tim 4,14"] },
      { number: 34, text: "Als sie aber erkannten, dass er ein Jude war, erhob sich eine Stimme aus aller Mund*, und sie schrien etwa zwei Stunden lang: Groß ist die Artemis der Epheser!", footnotes: ["w. aus allen"] },
      { number: 35, text: "Als aber der Stadtschreiber* die Volksmenge beruhigt hatte, spricht er: Männer von Ephesus, welcher Mensch ist denn, der nicht wüsste, dass die Stadt der Epheser eine Tempelhüterin der großen Artemis und des vom Himmel gefallenen Bildes ist?", footnotes: ["einer der höchsten Stadtbeamten, Leiter der Volksversammlungen"] },
      { number: 36, text: "Da nun dies unbestreitbar ist, so ist es nötig, dass ihr ruhig seid und nichts Übereiltes tut." },
      { number: 37, text: "Denn ihr habt diese Männer hergeführt, die weder Tempelräuber sind noch unsere Göttin lästern." },
      { number: 38, text: "Wenn nun Demetrius und die Kunsthandwerker mit ihm gegen jemand eine Sache haben, so werden Gerichtstage gehalten, und es sind Statthalter da. Mögen sie einander verklagen!" },
      { number: 39, text: "Wenn ihr aber wegen anderer Dinge ein Gesuch habt, so wird es in der gesetzlichen Versammlung erledigt werden." },
      { number: 40, text: "Denn wir sind auch in Gefahr, wegen des heutigen Aufruhrs angeklagt zu werden, da es keine Ursache gibt, weshalb wir uns über diesen Auflauf werden verantworten können. Und als er dies gesagt hatte, entließ er die Versammlung." },
    ]},
    { number: 20, verses: [
      { number: 1, text: "Nachdem aber der Tumult aufgehört hatte, ließ Paulus die Jünger kommen und ermahnte sie; und als er Abschied genommen hatte, ging er fort, um nach Mazedonien zu reisen*.", heading: "Reise durch Mazedonien und Griechenland und zurück bis Troas", footnotes: ["℘ Kap. 19,21; 2Kor 2,13; 1Tim 1,3"] },
      { number: 2, text: "Als er aber jene Gegenden durchzogen* und sie* mit vielen Worten ermahnt* hatte, kam er nach *Griechenland*.", footnotes: ["℘ Röm 15,19", "d. h. die dortigen Christen", "o. ermuntert, getröstet", "o. Griechenland, 3 nachdem er sich drei Monate (in Mazedonien) aufgehalten hatte. Da wurde", "℘ Kap. 19,21"] },
      { number: 3, text: "Und als er sich drei Monate aufgehalten hatte*, wurde*, als er nach Syrien abfahren wollte, von den Juden ein Anschlag gegen ihn unternommen*. Da entschloss er sich, durch Mazedonien zurückzukehren.", footnotes: ["℘ 1Kor 16,6", "o. Griechenland, 3 nachdem er sich drei Monate (in Mazedonien) aufgehalten hatte. Da wurde", "℘ Kap. 9,23"] },
      { number: 4, text: "Es begleitete ihn aber* Sopater, des Pyrrhus Sohn, ein Beröer; von den Thessalonichern aber Aristarch* und Sekundus und Gajus von Derbe und Timotheus und aus Asien Tychikus* und Trophimus*.", footnotes: ["Mehrere Handschr. fügen hinzu: bis nach Asien", "℘ Kap. 19,29", "℘ Eph 6,21; Kol 4,7; 2Tim 4,12; Tit 3,12", "℘ Kap. 21,29; 2Tim 4,20"] },
      { number: 5, text: "Diese gingen voraus und warteten auf uns in Troas." },
      { number: 6, text: "Wir aber segelten nach den Tagen der ungesäuerten Brote* von Philippi ab und kamen in fünf Tagen zu ihnen nach Troas, wo wir sieben Tage verweilten*.", footnotes: ["℘ 2Mo 12,15", "℘ Kap. 21,4; 28,14"] },
      { number: 7, text: "Am ersten Tag der Woche* aber, als wir versammelt waren, um Brot zu brechen*, unterredete sich Paulus mit ihnen, da er am folgenden Tag abreisen wollte; und er zog das Wort hinaus bis Mitternacht.", heading: "Auferweckung des Eutychus", footnotes: ["℘ Lk 24,1", "℘ Kap. 2,42.46"] },
      { number: 8, text: "Es waren aber viele Lampen in dem Obersaal, wo wir versammelt waren." },
      { number: 9, text: "Ein junger Mann aber mit Namen Eutychus saß im Fenster und wurde von tiefem Schlaf überwältigt, während Paulus noch weiterredete*; und vom Schlaf überwältigt, fiel er vom dritten Stock hinunter und wurde tot aufgehoben.", footnotes: ["o. sich unterredete; so auch V. 11"] },
      { number: 10, text: "Paulus aber ging hinab und warf sich über ihn, und ihn umfassend* sagte er: Macht keinen Lärm! Denn seine Seele ist in ihm.", footnotes: ["℘ 1Kö 17,21"] },
      { number: 11, text: "Und als er hinaufgestiegen war und das Brot gebrochen und gegessen und lange bis zum Anbruch des Tages geredet hatte, reiste er so ab." },
      { number: 12, text: "Sie brachten aber den Jungen lebend und wurden nicht wenig getröstet*.", footnotes: ["℘ Kap. 9,40"] },
      { number: 13, text: "Wir aber gingen voraus auf das Schiff und fuhren ab nach Assos und wollten dort den Paulus aufnehmen; denn so hatte er es angeordnet, da er selbst zu Fuß gehen wollte.", heading: "Reise nach Milet" },
      { number: 14, text: "Als er aber in Assos mit uns zusammentraf, nahmen wir ihn auf und kamen nach Mitylene." },
      { number: 15, text: "Und als wir von da abgesegelt waren, kamen wir am folgenden Tag Chios gegenüber an; am anderen Tag aber legten wir in Samos an und* kamen am folgenden Tag nach Milet;", footnotes: ["Andere Handschr. fügen hinzu: nachdem wir in Trogyllion geblieben waren, kamen wir"] },
      { number: 16, text: "denn Paulus hatte sich entschlossen, an Ephesus vorbeizufahren, damit er nicht veranlasst würde, in Asien* Zeit zu versäumen; denn er eilte, um, wenn es ihm möglich wäre, am Pfingsttag in Jerusalem zu sein*.", footnotes: ["d. i. die röm. Provinz Asien; vgl. auch Anm. zu Kap. 16,6", "℘ Kap. 19,21"] },
      { number: 17, text: "Von Milet aber sandte er nach Ephesus und rief die Ältesten der Gemeinde* herüber.", heading: "Abschiedsworte des Paulus an die Ältesten von Ephesus", footnotes: ["o. Versammlung; so auch V. 28"] },
      { number: 18, text: "Als sie aber zu ihm gekommen waren, sprach er zu ihnen: Ihr wisst, wie ich vom ersten Tag an, da ich nach Asien kam*, die ganze Zeit bei euch gewesen bin", footnotes: ["℘ 1Thes 2,1"] },
      { number: 19, text: "und dem Herrn diente* mit aller Demut und unter Tränen* und Versuchungen, die mir durch die Nachstellungen der Juden widerfuhren*;", footnotes: ["o. Sklave war", "℘ 2Kor 2,4", "℘ V. 3"] },
      { number: 20, text: "wie ich nichts zurückgehalten habe von dem, was nützlich ist, dass ich es euch nicht verkündigt und euch gelehrt hätte, öffentlich und in den Häusern*,", footnotes: ["℘ Kap. 5,42"] },
      { number: 21, text: "da ich sowohl Juden als auch Griechen* die Buße zu Gott* und den Glauben an unseren Herrn Jesus Christus bezeugte*.", footnotes: ["Darunter wurden alle griech. sprechenden und griech. beeinflussten nichtjüdischen Menschen des östl. Mittelmeerraumes verstanden.\n℘ Kap. 19,10", "℘ Kap. 11,18", "℘ Kap. 2,38; 16,31"] },
      { number: 22, text: "Und nun siehe, gebunden im Geist, gehe ich nach Jerusalem* und weiß nicht, was mir dort begegnen wird,", footnotes: ["℘ V. 16"] },
      { number: 23, text: "außer dass der Heilige Geist mir von Stadt zu Stadt bezeugt und sagt, dass Fesseln und Bedrängnisse auf mich warten*.", footnotes: ["℘ Kap. 9,16"] },
      { number: 24, text: "Aber ich achte mein Leben nicht der Rede wert*, damit ich meinen Lauf vollende* und den Dienst, den ich von dem Herrn Jesus empfangen habe*: das Evangelium der Gnade Gottes zu bezeugen*.", footnotes: ["℘ Kap. 21,13", "℘ 2Tim 4,7", "℘ Kap. 9,15", "℘ Eph 3,8"] },
      { number: 25, text: "Und nun siehe, ich weiß, dass ihr alle, unter denen ich umhergegangen bin und das Reich* gepredigt habe, mein Angesicht nicht mehr sehen werdet*.", footnotes: ["o. die Königsherrschaft", "℘ V. 38"] },
      { number: 26, text: "Deshalb bezeuge ich euch am heutigen Tag, dass ich rein bin vom Blut aller*;", footnotes: ["℘ Kap. 18,6"] },
      { number: 27, text: "denn ich habe nicht zurückgehalten, euch den ganzen Ratschluss Gottes zu verkündigen." },
      { number: 28, text: "Habt acht auf euch selbst* und auf die ganze Herde, in welcher der Heilige Geist euch als Aufseher* eingesetzt hat, die Gemeinde Gottes* zu hüten*, die er* sich erworben hat* durch das Blut seines eigenen* Sohnes*!", footnotes: ["℘ Lk 17,3", "℘ Phil 1,1", "nach anderen Handschr.: Gemeinde des Herrn", "℘ Jer 3,15; Eph 4,11; 1Petr 5,2.3", "d. i. Gott", "℘ Ps 74,2", "℘ 1Kor 6,20; Eph 1,7; Hebr 9,12; 1Petr 1,19; Offb 5,9", "o. durch sein eigenes Blut"] },
      { number: 29, text: "Ich weiß, dass nach meinem Abschied grausame Wölfe* zu euch hereinkommen werden, die die Herde nicht verschonen.", footnotes: ["℘ Mt 7,15"] },
      { number: 30, text: "Und aus eurer eigenen Mitte werden Männer aufstehen, die verkehrte Dinge reden*, um die Jünger abzuziehen hinter sich her*.", footnotes: ["℘ 2Petr 2,1", "℘ 1Jo 2,19"] },
      { number: 31, text: "Darum wacht* und denkt daran, dass ich drei Jahre lang Nacht und Tag nicht aufgehört habe*, einen jeden* unter Tränen zu ermahnen!", footnotes: ["℘ 1Kor 16,13", "℘ 2Kor 11,27", "℘ 1Thes 2,11"] },
      { number: 32, text: "Und nun befehle ich euch Gott und dem Wort seiner Gnade, das die Kraft hat, aufzuerbauen und ein Erbe unter allen Geheiligten zu geben*.", footnotes: ["℘ Kap. 26,18; Eph 1,11; Kol 1,12; Hebr 9,15; 1Petr 1,4"] },
      { number: 33, text: "Ich habe von niemandem Silber oder Gold oder Kleidung begehrt*.", footnotes: ["℘ 1Sam 12,3; 2Kor 7,2; 1Thes 2,5"] },
      { number: 34, text: "Ihr selbst wisst, dass meinen Bedürfnissen und denen, die bei mir waren, diese Hände gedient haben*.", footnotes: ["℘ Kap. 18,3"] },
      { number: 35, text: "Ich habe euch in allem gezeigt, dass man so arbeitend* sich der Schwachen annehmen* und an die Worte des Herrn Jesus denken müsse, der selbst gesagt hat: Geben ist seliger* als Nehmen*.", footnotes: ["℘ 1Thes 4,11", "℘ 1Thes 5,14", "o. glückseliger", "Ist so in den Evangelien nicht enthalten; offensichtlich ein mündlich überlieferter Ausspruch Jesu.\n℘ Lk 14,12-14; Eph 4,28"] },
      { number: 36, text: "Und als er dies gesagt hatte, kniete er nieder und betete mit ihnen allen*.", footnotes: ["℘ Kap. 21,5"] },
      { number: 37, text: "Es entstand aber lautes Weinen bei allen; und sie fielen Paulus um den Hals und küssten ihn*,", footnotes: ["o. küssten ihn zärtlich"] },
      { number: 38, text: "am meisten betrübt über das Wort, das er gesagt hatte, sie würden sein Angesicht nicht mehr sehen*. Sie geleiteten ihn aber zu dem Schiff.", footnotes: ["℘ V. 25"] },
    ]},
    { number: 21, verses: [
      { number: 1, text: "Als wir aber abfuhren, nachdem wir uns von ihnen losgerissen hatten, kamen wir geraden Laufs nach Kos, am folgenden Tag aber nach Rhodos und von da nach Patara.", heading: "Rückkehr von der dritten Missionsreise — Weissagungen über Paulus" },
      { number: 2, text: "Und wir fanden ein Schiff, das nach Phönizien übersetzte, stiegen ein und fuhren ab." },
      { number: 3, text: "Als wir aber Zypern gesichtet und es links hatten liegen lassen, segelten wir nach Syrien und legten zu Tyrus an, denn dort hatte das Schiff die Ladung abzuliefern." },
      { number: 4, text: "Nachdem wir die Jünger gefunden hatten, blieben wir sieben Tage dort*. Diese sagten dem Paulus durch den Geist, er möge nicht nach Jerusalem hinaufgehen*.", footnotes: ["℘ Kap. 20,6", "℘ V. 12"] },
      { number: 5, text: "Als wir aber die Tage vollendet hatten, zogen wir fort und reisten weiter; und sie alle geleiteten uns mit Frauen und Kindern bis außerhalb der Stadt, und wir knieten am Ufer nieder und beteten*.", footnotes: ["℘ Kap. 20,36"] },
      { number: 6, text: "Und nachdem wir voneinander Abschied genommen hatten, stiegen wir in das Schiff, jene aber kehrten heim." },
      { number: 7, text: "Als wir nun die Fahrt beendet hatten, gelangten wir von Tyrus nach Ptolemaïs; und wir begrüßten die Brüder und blieben einen Tag bei ihnen." },
      { number: 8, text: "Am folgenden Tag aber zogen wir aus und kamen nach Cäsarea*; und wir gingen in das Haus des Philippus, des Evangelisten, der einer von den Sieben war*, und blieben bei ihm.", footnotes: ["℘ Kap. 8,40", "℘ Kap. 6,5"] },
      { number: 9, text: "Dieser aber hatte vier Töchter, Jungfrauen, die weissagten." },
      { number: 10, text: "Als wir nun mehrere Tage blieben, kam ein Prophet mit Namen Agabus* von Judäa herab.", footnotes: ["℘ Kap. 11,28"] },
      { number: 11, text: "Und er kam zu uns und nahm den Gürtel des Paulus und band sich die Füße und die Hände und sprach: Dies sagt der Heilige Geist: Den Mann, dem dieser Gürtel gehört, werden die Juden in Jerusalem* so binden und in die Hände der Nationen überliefern*.", footnotes: ["℘ V. 33", "℘ Kap. 9,16; Joh 16,13"] },
      { number: 12, text: "Als wir aber dies hörten, baten sowohl wir als auch die Einheimischen, dass er nicht nach Jerusalem hinaufgehen möchte." },
      { number: 13, text: "Paulus aber antwortete: Was macht ihr, dass ihr weint und mir das Herz brecht? Denn ich bin bereit, nicht allein gebunden zu werden, sondern auch in Jerusalem für den Namen des Herrn Jesus zu sterben*.", footnotes: ["℘ Kap. 20,24"] },
      { number: 14, text: "Als er sich aber nicht überreden ließ, schwiegen wir und sprachen: Der Wille des Herrn geschehe*!", footnotes: ["℘ Mt 6,10"] },
      { number: 15, text: "Nach diesen Tagen aber machten wir uns bereit und gingen hinauf nach Jerusalem*.", footnotes: ["℘ Kap. 18,22"] },
      { number: 16, text: "Es gingen auch einige der Jünger aus Cäsarea mit uns und brachten uns zu einem gewissen Mnason, einem Zyprer, einem alten Jünger, bei dem wir herbergen sollten." },
      { number: 17, text: "Als wir aber in Jerusalem angekommen waren, nahmen uns die Brüder freudig auf*.", footnotes: ["℘ Kap. 15,4"] },
      { number: 18, text: "Am folgenden Tag aber ging Paulus mit uns zu Jakobus*, und alle Ältesten kamen dahin.", heading: "Paulus in Jerusalem", footnotes: ["℘ Kap. 12,17"] },
      { number: 19, text: "Und als er sie begrüßt hatte, erzählte er eines nach dem anderen, was Gott unter den Nationen durch seinen Dienst getan hatte*.", footnotes: ["℘ Kap. 14,27"] },
      { number: 20, text: "Sie aber, als sie es gehört hatten, verherrlichten Gott* und sprachen zu ihm: Du siehst, Bruder, wie viele Tausende* der Juden es gibt, die gläubig geworden sind, und alle sind Eiferer für das Gesetz*.", footnotes: ["℘ Gal 1,24", "w. Zehntausende; griech. Myriaden", "℘ Kap. 22,3"] },
      { number: 21, text: "Es ist ihnen aber über dich berichtet worden, dass du alle Juden, die unter den Nationen sind, Abfall von Mose lehrest und sagest, sie sollen weder die Kinder beschneiden noch nach den Gebräuchen wandeln*.", footnotes: ["℘ Kap. 6,14"] },
      { number: 22, text: "Was nun? Jedenfalls werden sie hören, dass du gekommen bist." },
      { number: 23, text: "Tu nun dies, was wir dir sagen: Wir haben vier Männer, die ein Gelübde* auf sich genommen haben*.", footnotes: ["den folgenden Angaben nach offensichtlich ein Nasiräer-Gelübde; vgl. 4Mo 6,1ff", "℘ 4Mo 6,2"] },
      { number: 24, text: "Diese nimm zu dir und reinige dich mit ihnen und trage die Kosten für sie, damit sie das Haupt scheren lassen*! Und alle werden erkennen, dass nichts an dem ist, was ihnen über dich berichtet worden ist, sondern dass du selbst auch zum Gesetz stehst und es befolgst*.", footnotes: ["℘ Kap. 18,18; 4Mo 6,13-18", "o. beachtest, einhältst\n℘ 1Kor 9,20"] },
      { number: 25, text: "Was aber die Gläubigen aus den Nationen betrifft, so haben wir geschrieben und verfügt, dass sie sich sowohl vor dem Götzenopfer als auch vor Blut und Ersticktem und Unzucht* hüten sollen*.", footnotes: ["o. Hurerei", "℘ Kap. 15,20"] },
      { number: 26, text: "Dann nahm Paulus die Männer zu sich, und nachdem er sich am folgenden Tag gereinigt hatte*, ging er mit ihnen in den Tempel und kündigte die Erfüllung der Tage der Reinigung an, bis für einen jeden von ihnen das Opfer dargebracht war*.", footnotes: ["℘ Kap. 24,18", "℘ 4Mo 6,21"] },
      { number: 27, text: "Als aber die sieben Tage beinahe vollendet waren, sahen ihn die Juden aus Asien* im Tempel* und brachten die ganze Volksmenge in Aufregung und legten die Hände an ihn*", heading: "Tumult der Juden und Gefangennahme des Paulus", footnotes: ["d. i. die röm. Provinz Asien; vgl. auch Anm. zu Kap. 16,6", "℘ Kap. 24,18", "℘ Kap. 26,21"] },
      { number: 28, text: "und schrien: Männer von Israel, helft! Dies ist der Mensch, der alle überall lehrt gegen das Volk und das Gesetz und diese Stätte*; und dazu hat er auch Griechen in den Tempel geführt und diese heilige Stätte verunreinigt*.", footnotes: ["℘ Kap. 6,13", "℘ Kap. 24,5.6; Hes 44,7"] },
      { number: 29, text: "Denn sie hatten vorher den Trophimus, den Epheser*, mit ihm in der Stadt gesehen, von dem sie meinten, dass Paulus ihn in den Tempel geführt habe.", footnotes: ["℘ Kap. 20,4"] },
      { number: 30, text: "Und die ganze Stadt kam in Bewegung, und es entstand ein Zusammenlauf des Volkes; und sie ergriffen Paulus und schleppten ihn aus dem Tempel, und sogleich wurden die Türen geschlossen." },
      { number: 31, text: "Während sie ihn aber zu töten suchten*, kam an den Obersten* der Schar* die Anzeige, dass ganz Jerusalem in Aufregung sei;", footnotes: ["℘ Kap. 26,21", "griech. Chiliarch; d.h. Tausendschaftsführer; der Militärtribun bei den Römern, Befehlshaber einer Kohorte", "Gemeint ist »Kohorte«, eine militärische Einheit der Römer von etwa 600 Mann."] },
      { number: 32, text: "der nahm sofort Soldaten und Hauptleute mit und lief zu ihnen hinab. Als sie aber den Obersten und die Soldaten sahen, hörten sie auf, den Paulus zu schlagen." },
      { number: 33, text: "Dann näherte sich der Oberste, ergriff ihn und befahl, ihn mit zwei Ketten zu fesseln*, und erkundigte sich, wer er denn sei und was er getan habe.", footnotes: ["℘ V. 11"] },
      { number: 34, text: "Die einen aber riefen dies, die anderen jenes in der Volksmenge. Da er aber wegen des Tumultes nichts Gewisses erfahren konnte, befahl er, ihn in das Lager* zu führen*.", footnotes: ["d. h. in das Standlager der römischen Garnison in Jerusalem", "℘ Kap. 22,24; 23,27"] },
      { number: 35, text: "Als er aber an die Stufen* kam, geschah es, dass er wegen der Gewalt der Volksmenge von den Soldaten getragen wurde;", footnotes: ["Das römische Lager befand sich auf der Burg Antonia, die mit dem Tempelbezirk durch eine Treppe verbunden war."] },
      { number: 36, text: "denn die Menge des Volkes folgte und schrie: Weg mit ihm*!", footnotes: ["℘ Kap. 22,22; 25,24; Lk 23,18"] },
      { number: 37, text: "Und als Paulus eben in das Lager hineingebracht werden sollte, spricht er zu dem Obersten: Ist es mir erlaubt, dir etwas zu sagen? Er aber sprach: Verstehst du Griechisch?" },
      { number: 38, text: "Du bist also nicht der Ägypter, der vor diesen Tagen eine Empörung gemacht und die viertausend Mann Sikarier* in die Wüste hinausgeführt hat?", footnotes: ["d. h. Dolchmänner; fanatische römerfeindliche Partei, die auch vor politischem Mord nicht zurückschreckte"] },
      { number: 39, text: "Paulus aber sprach: Ich bin ein jüdischer Mann aus Tarsus*, Bürger einer nicht unberühmten Stadt in Zilizien. Ich bitte dich aber, erlaube mir, zu dem Volk zu reden!", footnotes: ["℘ Kap. 9,11"] },
      { number: 40, text: "Als er es aber erlaubt hatte, winkte Paulus, auf den Stufen stehend, dem Volk mit der Hand*; nachdem aber eine große Stille eingetreten war, redete er sie in hebräischer Mundart an und sprach:", footnotes: ["℘ Kap. 13,16"] },
    ]},
    { number: 22, verses: [
      { number: 1, text: "*Ihr Brüder* und Väter, hört jetzt meine Verantwortung vor euch!*", heading: "Rede des Paulus an das Volk", footnotes: ["℘ V. 1-21: Kap. 9,1-30; 26,9-21", "w. Männer, Brüder (ein Hebraismus, gew. bei der Anrede verwendet)", "℘ Kap. 7,2"] },
      { number: 2, text: "Als sie aber hörten, dass er sie in hebräischer Mundart anredete, hielten sie noch mehr Ruhe. Und er spricht:" },
      { number: 3, text: "Ich bin ein jüdischer Mann, geboren in Tarsus in Zilizien*; aber auferzogen in dieser Stadt, zu den Füßen Gamaliels*, unterwiesen nach der Strenge des väterlichen Gesetzes*, war ich, wie ihr alle heute seid, ein Eiferer für Gott*.", footnotes: ["℘ Kap. 9,11", "℘ Kap. 5,34", "℘ Kap. 26,4.5", "℘ Kap. 21,20; Röm 10,2; Gal 1,14; Phil 3,5.6"] },
      { number: 4, text: "Ich habe diesen Weg* verfolgt bis auf den Tod, indem ich sowohl Männer als auch Frauen band und in die Gefängnisse überlieferte*,", footnotes: ["d. h. den Weg Christi o. des christlichen Bekenntnisses", "℘ Kap. 8,3"] },
      { number: 5, text: "wie auch der Hohepriester und die ganze Ältestenschaft mir Zeugnis gibt. Von ihnen empfing ich auch Briefe an die Brüder und reiste nach Damaskus, um auch diejenigen, die dort waren, gebunden nach Jerusalem zu führen, dass sie bestraft würden." },
      { number: 6, text: "Es geschah mir aber, als ich reiste und mich Damaskus näherte, dass um Mittag plötzlich aus dem Himmel ein helles Licht mich umstrahlte." },
      { number: 7, text: "Und ich fiel zu Boden und hörte eine Stimme, die zu mir sprach: Saul, Saul, was verfolgst du mich?" },
      { number: 8, text: "Ich aber antwortete: Wer bist du, Herr? Und er sprach zu mir: Ich bin Jesus, der Nazoräer*, den du verfolgst.", footnotes: ["eine andere Form für das bei Mk (und teilweise Lk) überlieferte »Nazarener«; vgl. auch Anm. zu Mt 2,23\n℘ Mt 2,23"] },
      { number: 9, text: "Die aber bei mir waren, sahen zwar das Licht, aber die Stimme dessen, der mit mir redete, hörten sie nicht*.", footnotes: ["℘ Dan 10,7"] },
      { number: 10, text: "Ich sagte aber: Was soll ich tun, Herr? Der Herr aber sprach zu mir: Steh auf und geh nach Damaskus! Und dort wird dir von allem gesagt werden, was dir zu tun verordnet ist." },
      { number: 11, text: "Da ich aber vor der Herrlichkeit jenes Lichtes nicht sehen konnte, wurde ich von denen, die bei mir waren, an der Hand geleitet und kam nach Damaskus." },
      { number: 12, text: "Ein gewisser Hananias aber, ein frommer Mann nach dem Gesetz, der ein gutes Zeugnis hatte von allen dort wohnenden Juden," },
      { number: 13, text: "kam zu mir, trat heran und sprach zu mir: Bruder Saul, sei wieder sehend! Und zu derselben Stunde schaute ich zu ihm auf." },
      { number: 14, text: "Er aber sprach: Der Gott unserer Väter* hat dich dazu bestimmt, seinen Willen zu erkennen und den Gerechten zu sehen* und eine Stimme aus seinem Mund zu hören.", footnotes: ["℘ Kap. 3,13", "℘ Kap. 3,14; 26,16; 1Kor 9,1"] },
      { number: 15, text: "Denn du wirst* ihm an alle Menschen ein Zeuge sein von dem, was du gesehen und gehört hast.", footnotes: ["o. sollst"] },
      { number: 16, text: "Und nun, was zögerst du? Steh auf, lass dich taufen und deine Sünden abwaschen*, indem du seinen Namen anrufst*!", footnotes: ["℘ Kap. 2,38", "℘ Röm 10,13"] },
      { number: 17, text: "Es geschah mir aber, als ich nach Jerusalem zurückgekehrt war* und im Tempel betete, dass ich in Verzückung geriet*", footnotes: ["℘ Kap. 9,26", "℘ Kap. 10,10"] },
      { number: 18, text: "und ihn sah*, der zu mir sprach: Eile und geh schnell aus Jerusalem hinaus! Denn sie werden dein Zeugnis über mich nicht annehmen.", footnotes: ["℘ Kap. 3,14; 26,16; 1Kor 9,1"] },
      { number: 19, text: "Und ich sprach: Herr, sie selbst wissen, dass ich die an dich Glaubenden ins Gefängnis werfen und hin und her in den Synagogen schlagen ließ*;", footnotes: ["gemeint ist die Strafe der Geißelung; vgl. Anm. zu Mt 10,17\n℘ Mt 10,17"] },
      { number: 20, text: "und als das Blut deines Zeugen* Stephanus vergossen wurde, stand auch ich dabei und willigte mit ein und bewachte die Kleider derer, die ihn umbrachten*.", footnotes: ["℘ Offb 2,13", "℘ Kap. 7,58; 8,1"] },
      { number: 21, text: "Und er sprach zu mir: Geh hin! Denn ich werde dich weit weg zu den Nationen senden*.", footnotes: ["℘ Kap. 9,15"] },
      { number: 22, text: "Sie hörten ihm aber zu bis zu diesem Wort und erhoben ihre Stimme und sagten: Weg von der Erde mit einem solchen, denn es darf nicht sein, dass er lebt*!", footnotes: ["℘ Kap. 21,36"] },
      { number: 23, text: "Als sie aber schrien und die Kleider abwarfen und Staub in die Luft schleuderten,", heading: "Paulus beruft sich auf sein römisches Bürgerrecht" },
      { number: 24, text: "befahl der Oberste, ihn ins Lager zu bringen*, und sagte, man solle ihn mit Geißelhieben ausforschen, damit er erfahre, um welcher Ursache willen sie so gegen ihn schrien.", footnotes: ["℘ Kap. 21,34"] },
      { number: 25, text: "Als sie ihn aber für die Riemen* ausgestreckt hatten, sprach Paulus zu dem Hauptmann, der dastand: Ist es euch erlaubt, einen Menschen, der Römer ist*, zu geißeln, und zwar unverurteilt?", footnotes: ["Die Geißeln bestanden aus Riemen.", "℘ Kap. 16,37"] },
      { number: 26, text: "Als es aber der Hauptmann hörte, ging er hin und meldete dem Obersten und sprach: Was hast du vor zu tun? Denn dieser Mensch ist ein Römer." },
      { number: 27, text: "Der Oberste aber kam herbei und sprach zu ihm: Sage mir, bist du ein Römer? Er aber sprach: Ja." },
      { number: 28, text: "Und der Oberste antwortete: Ich habe für eine große Summe dieses Bürgerrecht erworben. Paulus sprach: Ich aber bin sogar darin geboren." },
      { number: 29, text: "Sogleich nun ließen die, welche ihn ausforschen sollten, von ihm ab; aber auch der Oberste fürchtete sich, als er erfuhr, dass er ein Römer sei und weil er ihn gebunden hatte*.", footnotes: ["℘ Kap. 16,38"] },
      { number: 30, text: "Am folgenden Tag aber, da er mit Gewissheit erfahren wollte, weshalb er von den Juden angeklagt sei, machte er ihn los und befahl, dass die Hohenpriester* und der ganze Hohe Rat* zusammenkommen sollten; und er führte Paulus hinab und stellte ihn vor sie*.", heading: "Paulus vor dem Hohen Rat", footnotes: ["Nicht nur der amtierende Hohepriester, sondern alle männlichen Mitglieder der hohenpriesterlichen Familien wurden zu den »Hohenpriestern« gerechnet.", "w. Synedrium; so auch Kap. 23,1ff; s. Anm. zu Mt 26,59", "℘ Kap. 23,28"] },
    ]},
    { number: 23, verses: [
      { number: 1, text: "Paulus aber blickte den Hohen Rat fest an und sprach: Ihr Brüder*! Ich bin mit allem guten Gewissen vor Gott gewandelt bis auf diesen Tag*.", footnotes: ["w. Männer, Brüder (ein Hebraismus, gew. bei der Anrede verwendet); so auch V. 6", "℘ Kap. 24,16; 2Tim 1,3"] },
      { number: 2, text: "Der Hohepriester Hananias aber befahl denen, die bei ihm standen, ihn auf den Mund zu schlagen*.", footnotes: ["℘ Joh 18,22"] },
      { number: 3, text: "Da sprach Paulus zu ihm: Gott wird dich schlagen, du getünchte Wand*! Und du, sitzt du da, mich nach dem Gesetz zu richten, und, gegen das Gesetz handelnd, befiehlst du, mich zu schlagen?", footnotes: ["℘ Mt 23,27"] },
      { number: 4, text: "Die Dabeistehenden aber sprachen: Schmähst du den Hohenpriester Gottes?" },
      { number: 5, text: "Und Paulus sprach: Ich wusste nicht, Brüder, dass es der Hohepriester ist; denn es steht geschrieben: »Von dem Obersten deines Volkes sollst du nicht schlecht reden.«*", footnotes: ["℘ 2Mo 22,27"] },
      { number: 6, text: "Da aber Paulus wusste, dass der eine Teil von den Sadduzäern*, der andere aber von den Pharisäern* war, rief er in dem Hohen Rat: Ihr Brüder, ich bin ein Pharisäer*, ein Sohn von Pharisäern; wegen der Hoffnung und Auferstehung der Toten werde ich gerichtet*.", footnotes: ["Dies war eine jüdische Partei der Reichen unter dem führenden Einfluss der Hohenpriester, römerfreundlich, offen für hellenistisches Denken, stand in scharfem Gegensatz zur Partei der Pharisäer. Der Name geht viell. auf einen Hohenpriester Zadok zurück.", "religiöse Partei im Judentum, die auf genaue Einhaltung des Gesetzes Wert legte; s. auch Anm. zu Mt 3,7", "℘ Kap. 26,5; Phil 3,5", "℘ Kap. 24,15.21; 26,6-8; 28,20"] },
      { number: 7, text: "Als er aber dies gesagt hatte, entstand ein Zwiespalt unter den Pharisäern und den Sadduzäern, und die Menge teilte sich." },
      { number: 8, text: "Denn die Sadduzäer sagen, es gebe keine Auferstehung* noch Engel noch Geist; die Pharisäer aber bekennen beides.", footnotes: ["℘ Kap. 4,2; 17,32; 26,8; Mt 22,23; 1Kor 15,12"] },
      { number: 9, text: "Es entstand aber ein großes Geschrei, und einige der Schriftgelehrten von der Partei der Pharisäer standen auf und stritten und sagten: Wir finden an diesem Menschen nichts Böses*; wenn aber ein Geist oder ein Engel zu ihm geredet hat* . . .", footnotes: ["℘ V. 29; Kap. 25,25; 26,31; 28,18", "℘ Joh 12,29"] },
      { number: 10, text: "Als aber ein großer Zwiespalt* entstand, fürchtete der Oberste, Paulus möchte von ihnen zerrissen werden, und befahl, dass die Truppen hinabgingen und ihn aus ihrer Mitte wegrissen und in das Lager führten.", footnotes: ["o. Aufruhr"] },
      { number: 11, text: "In der folgenden Nacht aber stand der Herr bei ihm* und sprach: Sei guten Mutes! Denn wie du meine Sache in Jerusalem bezeugt hast, so musst du sie auch in Rom bezeugen*.", footnotes: ["℘ 2Tim 4,17", "℘ Kap. 18,9; 27,24"] },
      { number: 12, text: "Als es aber Tag geworden war, rotteten sich die Juden zusammen, verschworen sich mit einem Fluch und sagten, dass sie weder essen noch trinken würden, bis sie Paulus getötet hätten*.", heading: "Mordanschlag gegen Paulus", footnotes: ["℘ Kap. 9,23"] },
      { number: 13, text: "Es waren aber mehr als vierzig, die diese Verschwörung gemacht hatten." },
      { number: 14, text: "Sie kamen zu den Hohenpriestern* und den Ältesten und sprachen: Wir haben uns mit einem Fluch* verschworen, nichts zu genießen, bis wir den Paulus getötet haben.", footnotes: ["s. Anm. zu Kap.22,30", "griech. anathema; d. h. dem Gericht Gottes übergeben"] },
      { number: 15, text: "Macht ihr nun jetzt mit dem Hohen Rat dem Obersten Anzeige, damit er ihn zu euch herabführe, als wolltet ihr seine Sache genauer entscheiden! Wir aber sind bereit, ehe er nahe kommt, ihn umzubringen." },
      { number: 16, text: "Als aber der Neffe* des Paulus von der Nachstellung gehört hatte, kam er hin und ging in das Lager und meldete es dem Paulus.", footnotes: ["w. Sohn der Schwester"] },
      { number: 17, text: "Paulus aber rief einen von den Hauptleuten zu sich und sagte: Führe diesen jungen Mann zu dem Obersten, denn er hat ihm etwas zu melden!" },
      { number: 18, text: "Der nun nahm ihn zu sich und führte ihn zu dem Obersten und sagte: Der Gefangene Paulus rief mich herbei und bat mich, diesen jungen Mann zu dir zu führen, der dir etwas zu sagen habe." },
      { number: 19, text: "Der Oberste aber nahm ihn bei der Hand und zog sich mit ihm abseits zurück und fragte: Was ist es, das du mir zu melden hast?" },
      { number: 20, text: "Er aber sprach: Die Juden sind übereingekommen, dich zu bitten, dass du morgen den Paulus in den Hohen Rat hinabbringst, als wolle er etwas Genaueres über ihn erkunden." },
      { number: 21, text: "Du nun, lass dich nicht von ihnen überreden! Denn mehr als vierzig Männer von ihnen stellen ihm nach, die sich mit einem Fluch verschworen haben, weder zu essen noch zu trinken, bis sie ihn umgebracht haben; und jetzt sind sie bereit und erwarten die Zusage von dir." },
      { number: 22, text: "Der Oberste nun entließ den jungen Mann und befahl ihm: Sage niemandem, dass du mir dies mitgeteilt hast!" },
      { number: 23, text: "Und als er zwei von den Hauptleuten herbeigerufen hatte, sprach er: Macht zweihundert Soldaten bereit, damit sie bis Cäsarea ziehen, und siebzig Reiter und zweihundert Lanzenträger von der dritten Stunde der Nacht* an!", heading: "Paulus wird nach Cäsarea gebracht", footnotes: ["d. h. am Ende der ersten Nachtwache, ca. 21 Uhr; vgl. Anm. zu Mk 13,35"] },
      { number: 24, text: "Und sie sollten Tiere bereithalten, dass sie den Paulus darauf setzten und sicher zu Felix*, dem Statthalter, hinbrächten.", footnotes: ["etwa 52—60 n. Chr. Statthalter des römischen Kaisers in Judäa"] },
      { number: 25, text: "Und er schrieb einen Brief folgenden Inhalts:" },
      { number: 26, text: "Klaudius Lysias, dem hochedlen Statthalter Felix seinen Gruß!" },
      { number: 27, text: "Diesen Mann, der von den Juden ergriffen wurde und nahe daran war, von ihnen umgebracht zu werden, habe ich ihnen, indem ich mit den Truppen einschritt, entrissen*, da ich erfuhr, dass er ein Römer sei*.", footnotes: ["℘ Kap. 21,34", "℘ Kap. 16,37"] },
      { number: 28, text: "Da ich aber die Ursache wissen wollte, weshalb sie ihn anklagten, führte ich ihn in ihren Hohen Rat hinab*.", footnotes: ["℘ Kap. 22,30"] },
      { number: 29, text: "Da fand ich, dass er wegen Streitfragen ihres Gesetzes angeklagt war*, dass aber keine Anklage gegen ihn vorlag, die des Todes oder der Fesseln wert wäre*.", footnotes: ["℘ Kap. 18,14.15", "℘ V. 9"] },
      { number: 30, text: "Da mir aber ein Anschlag hinterbracht wurde, der gegen den Mann im Werk sei, habe ich ihn sofort zu dir gesandt und auch den Klägern befohlen, vor dir zu sagen, was gegen ihn vorliegt*.", footnotes: ["℘ Kap. 24,8"] },
      { number: 31, text: "Die Soldaten nun nahmen, wie ihnen befohlen war, den Paulus und führten ihn bei Nacht nach Antipatris." },
      { number: 32, text: "Am folgenden Tag aber ließen sie die Reiter mit ihm fortziehen und kehrten nach dem Lager zurück." },
      { number: 33, text: "Und als diese nach Cäsarea gekommen waren, übergaben sie dem Statthalter den Brief und führten ihm auch den Paulus vor*.", footnotes: ["℘ Kap. 25,23; Mt 10,18"] },
      { number: 34, text: "Als er es aber gelesen und gefragt hatte, aus welcher Provinz er sei, und erfahren, dass er aus Zilizien sei*,", footnotes: ["℘ Kap. 9,11"] },
      { number: 35, text: "sprach er: Ich werde dich verhören, wenn auch deine Ankläger angekommen sind. Und er befahl, dass er in dem Prätorium des Herodes* bewacht werde*.", footnotes: ["Der Amtssitz des Statthalters befand sich offensichtlich im ehemaligen Königspalast Herodes' d. Gr.; s. auch Anm. zu Mt 27,27.", "℘ Kap. 28,17"] },
    ]},
    { number: 24, verses: [
      { number: 1, text: "Nach fünf Tagen aber kam der Hohepriester Hananias mit einigen Ältesten und Tertullus, einem Anwalt*, herab, und sie machten bei dem Statthalter Anzeige gegen Paulus*.", heading: "Paulus wird beim Statthalter Felix verklagt", footnotes: ["griech. Rhetor; d. h. w. Redner", "℘ Kap. 25,2"] },
      { number: 2, text: "Als er aber gerufen worden war, begann Tertullus die Anklage und sprach: Da wir großen Frieden durch dich genießen und da durch deine Fürsorge für diese Nation Verbesserungen getroffen worden sind," },
      { number: 3, text: "so erkennen wir es allseits und überall, hochedler Felix, mit aller Dankbarkeit an." },
      { number: 4, text: "Damit ich dich aber nicht länger aufhalte, bitte ich dich, uns in Kürze nach deiner Geneigtheit* anzuhören.", footnotes: ["o. Milde"] },
      { number: 5, text: "Denn wir haben diesen Mann als eine Pest befunden und als einen, der unter allen Juden, die auf dem Erdkreis sind, Aufruhr erregt*, und als einen Anführer der Sekte der Nazoräer*;", footnotes: ["℘ Kap. 13,45", "eine andere Form für das bei Mk (und teilweise Lk) überlieferte »Nazarener«; vgl. auch Anm. zu Mt 2,23\n℘ V. 14; Kap. 28,22"] },
      { number: 6, text: "der auch versucht hat, den Tempel zu entheiligen*, den wir auch ergriffen haben;", footnotes: ["℘ Kap. 21,28"] },
      { number: 7, text: "[T>]*", footnotes: ["Andere Handschr. fügen hinzu: und nach unserem Gesetz richten wollten. 7 Lysias aber, der Oberst, kam hinzu und führte ihn mit großer Gewalt aus unseren Händen weg 8 und befahl seinen Anklägern, zu dir zu kommen;"] },
      { number: 8, text: "von ihm kannst du selbst, wenn du ihn verhört hast, über alles dies Gewissheit erhalten, dessen wir ihn anklagen*. —", footnotes: ["℘ Kap. 23,30"] },
      { number: 9, text: "Aber auch die Juden griffen Paulus mit an und sagten, dass dies sich so verhalte." },
      { number: 10, text: "Paulus aber antwortete, nachdem ihm der Statthalter zu reden gewinkt hatte: Da ich weiß, dass du seit vielen Jahren Richter über diese Nation bist, so verteidige ich meine Sache getrost.", heading: "Verteidigungsrede des Paulus vor Felix" },
      { number: 11, text: "Du kannst ja erfahren, dass es nicht mehr als zwölf Tage sind, seit ich hinaufging, um in Jerusalem anzubeten." },
      { number: 12, text: "Und sie haben mich weder im Tempel angetroffen, noch dass ich mit jemand in Unterredung war oder einen Auflauf der Volksmenge machte, weder in den Synagogen noch in der Stadt*;", footnotes: ["℘ Kap. 25,8; 28,17"] },
      { number: 13, text: "auch können sie dir das nicht beweisen, weswegen sie mich jetzt anklagen*.", footnotes: ["℘ Kap. 25,7"] },
      { number: 14, text: "Aber dies bekenne ich dir, dass ich nach dem Weg*, den sie eine Sekte* nennen, so dem Gott meiner Väter diene*, indem ich allem glaube, was in dem Gesetz und in den Propheten geschrieben steht,", footnotes: ["d. h. dem Weg Christi oder der christlichen Lehre\n℘ Kap. 9,2", "℘ V. 5", "℘ Röm 1,9"] },
      { number: 15, text: "und die Hoffnung zu Gott habe*, die auch selbst diese hegen, dass eine Auferstehung der Gerechten wie der Ungerechten sein wird*.", footnotes: ["℘ Kap. 26,6.7; 28,20", "℘ Kap. 23,6; Joh 5,29"] },
      { number: 16, text: "Darum übe ich mich auch, allezeit ein Gewissen ohne Anstoß zu haben vor Gott und den Menschen*.", footnotes: ["℘ Kap. 23,1; 2Kor 1,12; 8,21; 1Tim 1,19; Hebr 13,18; 1Petr 3,16"] },
      { number: 17, text: "Nach mehreren Jahren aber kam ich her, um Almosen für meine Nation und Opfer darzubringen*.", footnotes: ["℘ Kap. 11,30"] },
      { number: 18, text: "Bei diesen fanden sie mich, gereinigt im Tempel*, weder mit Auflauf noch mit Tumult;", footnotes: ["℘ Kap. 21,26.27"] },
      { number: 19, text: "es waren aber einige Juden aus Asien*, die hier vor dir sein und Klage führen sollten, wenn sie etwas gegen mich hätten.", footnotes: ["d. i. die röm. Provinz Asien; vgl. auch Anm. zu Kap. 16,6"] },
      { number: 20, text: "Oder lass diese selbst sagen, welches Unrecht sie gefunden haben, als ich vor dem Hohen Rat* stand,", footnotes: ["w. Synedrium; s. Anm. zu Mt 26,59"] },
      { number: 21, text: "es sei denn wegen dieses einen Ausrufs, den ich tat, als ich unter ihnen stand: Wegen der Auferstehung der Toten werde ich heute vor euch gerichtet*.", footnotes: ["℘ Kap. 23,6; Joh 5,29"] },
      { number: 22, text: "Felix aber, der von dem Weg* genauere Kenntnis hatte, vertagte ihre Sache* und sagte: Wenn Lysias, der Oberste, herabkommt, so will ich eure Sache entscheiden.", footnotes: ["d. h. dem Weg Christi oder der christlichen Lehre\n℘ Kap. 9,2", "w. sie"] },
      { number: 23, text: "Und er befahl dem Hauptmann, ihn in Gewahrsam zu halten und ihm Erleichterung zu geben und niemandem von den Seinen zu wehren, ihm zu dienen*.", footnotes: ["℘ Kap. 27,3; 28,16.30"] },
      { number: 24, text: "Nach einigen Tagen aber kam Felix herbei mit Drusilla*, seiner Frau, die eine Jüdin war, und ließ den Paulus holen und hörte ihn über den Glauben an Christus.", heading: "Paulus und Felix", footnotes: ["Schwester Agrippas II.; vgl. Anm. zu Kap. 25,13"] },
      { number: 25, text: "Als er aber über Gerechtigkeit und Enthaltsamkeit und das kommende Gericht redete, wurde Felix mit Furcht erfüllt und antwortete: Für jetzt geh hin! Wenn ich aber gelegene Zeit habe, werde ich dich rufen lassen*.", footnotes: ["℘ Kap. 17,32"] },
      { number: 26, text: "Zugleich hoffte er, dass ihm von Paulus Geld gegeben werde; deshalb ließ er ihn auch öfter holen und unterhielt sich mit ihm." },
      { number: 27, text: "Als aber zwei Jahre verflossen* waren, bekam Felix* den Porzius Festus zum Nachfolger; und da Felix sich bei den Juden in Gunst setzen wollte*, hinterließ er den Paulus gefangen*.", footnotes: ["o. erfüllt", "s. Anm. zu Kap. 23,24", "℘ Kap. 12,3", "℘ Kap. 25,14"] },
    ]},
    { number: 25, verses: [
      { number: 1, text: "Als nun Festus* in die Provinz gekommen war, ging er nach drei Tagen von Cäsarea hinauf nach Jerusalem.", heading: "Paulus wird beim Statthalter Festus verklagt — Berufung auf den Kaiser", footnotes: ["etwa 60—62 n. Chr. Statthalter des römischen Kaisers in Palästina"] },
      { number: 2, text: "Und die Hohenpriester* und die Vornehmsten der Juden machten Anzeige bei ihm gegen Paulus* und baten ihn,", footnotes: ["s. Anm. zu Kap. 22,30", "℘ Kap. 24,1"] },
      { number: 3, text: "indem sie es als eine Gunst für sich gegen ihn erbaten, dass er ihn nach Jerusalem kommen ließe; sie machten einen Anschlag, ihn unterwegs umzubringen*.", footnotes: ["℘ Kap. 9,23"] },
      { number: 4, text: "Festus nun antwortete, Paulus werde in Cäsarea behalten, er selbst aber wolle in Kürze abreisen." },
      { number: 5, text: "Die Angesehenen* unter euch nun, sprach er, mögen mit hinabreisen und, wenn etwas Unrechtes an dem Mann ist, ihn anklagen!", footnotes: ["o. Bevollmächtigten"] },
      { number: 6, text: "Nachdem er aber nicht mehr als acht oder zehn Tage unter ihnen verweilt hatte, ging er nach Cäsarea hinab; und am folgenden Tag setzte er sich auf den Richterstuhl und befahl, Paulus vorzuführen." },
      { number: 7, text: "Als er aber angekommen war, stellten sich die von Jerusalem herabgekommenen Juden um ihn her und brachten viele und schwere Beschuldigungen vor, die sie nicht beweisen konnten*,", footnotes: ["℘ Kap. 24,13"] },
      { number: 8, text: "da Paulus sich verteidigte: Weder gegen das Gesetz der Juden noch gegen den Tempel noch gegen den Kaiser habe ich in irgendeiner Weise gesündigt*.", footnotes: ["℘ Kap. 24,12"] },
      { number: 9, text: "Festus aber, der den Juden eine Gunst erweisen wollte*, antwortete dem Paulus und sagte: Willst du nach Jerusalem hinaufgehen und dort dieser Dinge wegen vor mir gerichtet werden?", footnotes: ["℘ Kap. 12,3"] },
      { number: 10, text: "Paulus aber sprach: Ich stehe vor dem Richterstuhl des Kaisers, wo ich gerichtet werden muss; den Juden habe ich kein Unrecht getan, wie auch du sehr wohl* weißt.", footnotes: ["w. besser"] },
      { number: 11, text: "Wenn ich nun Unrecht getan und etwas Todeswürdiges begangen habe, so weigere ich mich nicht zu sterben; wenn aber nichts an dem ist, wessen diese mich anklagen, so kann mich niemand ihnen preisgeben. Ich berufe mich auf den Kaiser*.", footnotes: ["℘ V. 25; Kap. 26,32; 28,19"] },
      { number: 12, text: "Dann besprach sich Festus mit dem Rat und antwortete: Auf den Kaiser hast du dich berufen, zum Kaiser sollst du gehen." },
      { number: 13, text: "Als aber einige Tage vergangen waren, kamen der König Agrippa* und Berenike* nach Cäsarea, den Festus zu begrüßen.", heading: "Paulus vor Festus und Herodes Agrippa II.", footnotes: ["Herodes Agrippa II., Sohn Agrippas I. (vgl. Anm. zu Kap. 12,1), seit dem Jahre 50 n. Chr. unter röm. Oberhoheit Herrscher über Teile Palästinas", "Schwester Agrippas II."] },
      { number: 14, text: "Als sie aber mehrere Tage dort verweilt hatten, legte Festus dem König die Sache des Paulus vor und sprach: Ein Mann ist von Felix gefangen zurückgelassen worden*,", footnotes: ["℘ Kap. 24,27"] },
      { number: 15, text: "dessentwegen, als ich zu Jerusalem war, die Hohenpriester und die Ältesten der Juden Anzeige machten, indem sie ein Urteil gegen ihn verlangten." },
      { number: 16, text: "Diesen antwortete ich: Es ist bei den Römern nicht Sitte, irgendeinen Menschen preiszugeben, ehe der Angeklagte seine Ankläger persönlich vor sich habe und Gelegenheit bekommt, sich wegen der Anklage zu verteidigen*.", footnotes: ["℘ Joh 7,51"] },
      { number: 17, text: "Als sie nun hierher zusammengekommen waren, setzte ich mich, ohne irgendeinen Aufschub, tags darauf auf den Richterstuhl und befahl, den Mann vorzuführen." },
      { number: 18, text: "Als die Ankläger auftraten, brachten sie gegen ihn keine Beschuldigung wegen Übeltaten vor, die ich vermutete." },
      { number: 19, text: "Sie hatten aber einige Streitfragen gegen ihn wegen ihres eigenen Gottesdienstes* und wegen eines gewissen Jesus, der gestorben ist, von dem Paulus sagte, er lebe*.", footnotes: ["℘ Kap. 18,15", "℘ Kap. 13,30"] },
      { number: 20, text: "Da ich aber hinsichtlich der Untersuchung wegen dieser Dinge in Verlegenheit war, sagte ich, ob er nach Jerusalem gehen und dort wegen dieser Dinge gerichtet werden wolle." },
      { number: 21, text: "Als aber Paulus Berufung einlegte und forderte, dass er für die Entscheidung des Augustus* in Gewahrsam gehalten werde, befahl ich, ihn in Gewahrsam zu halten, bis ich ihn zum Kaiser senden werde.", footnotes: ["d. h. Erhabener; Ehrenname der römischen Kaiser. Hier ist Kaiser Nero (54—68 n. Chr.) gemeint; so auch V. 25."] },
      { number: 22, text: "Agrippa aber sprach zu Festus: Ich möchte wohl auch selbst den Menschen hören*! — Morgen, sagte er, sollst du ihn hören.", footnotes: ["℘ Lk 23,8"] },
      { number: 23, text: "Als nun am folgenden Tag Agrippa und Berenike mit großem Gepränge gekommen und mit dem Obersten* und den vornehmsten Männern der Stadt in den Verhörsaal eingetreten waren und Festus Befehl gegeben hatte, wurde Paulus vorgeführt*.", footnotes: ["griech. Chiliarchen; d. h. Tausendschaftsführer", "℘ Kap. 9,15; 23,33"] },
      { number: 24, text: "Und Festus spricht: König Agrippa und ihr Männer alle, die ihr mit uns zugegen seid, ihr seht diesen, um dessentwillen mich die ganze Menge der Juden angegangen hat, in Jerusalem wie auch hier, indem sie gegen ihn schrien, er dürfe nicht mehr leben*.", footnotes: ["℘ Kap. 21,36"] },
      { number: 25, text: "Ich aber, da ich fand, dass er nichts Todeswürdiges begangen*, dieser selbst aber sich auch auf den Augustus berufen hat*, habe beschlossen, ihn zu senden.", footnotes: ["℘ Kap. 23,9", "℘ V. 11"] },
      { number: 26, text: "Über ihn habe ich dem Herrn nichts Gewisses zu schreiben. Deshalb habe ich ihn vor euch geführt und besonders vor dich, König Agrippa, damit ich, wenn die Untersuchung geschehen ist, etwas zu schreiben habe." },
      { number: 27, text: "Denn es scheint mir ungereimt, einen Gefangenen zu senden und nicht auch die gegen ihn vorliegenden Beschuldigungen mitzuteilen." },
    ]},
    { number: 26, verses: [
      { number: 1, text: "*Agrippa aber sprach zu Paulus: Es ist dir erlaubt, für dich selbst zu reden. Da streckte Paulus die Hand aus* und verteidigte sich:", heading: "Rede des Paulus vor Festus und Agrippa", footnotes: ["℘ V. 9-18: Kap. 9,1-30; 22,1-21", "℘ Kap. 13,16"] },
      { number: 2, text: "Ich schätze mich glücklich*, König Agrippa, dass ich mich über alles, dessen ich von den Juden angeklagt werde, heute vor dir verteidigen soll;", footnotes: ["o. glückselig"] },
      { number: 3, text: "besonders weil du ein hervorragender Kenner bist von allen Gebräuchen und Streitfragen, die unter den Juden sind. Darum bitte ich dich, mich langmütig anzuhören." },
      { number: 4, text: "Meinen Lebenswandel nun von Jugend auf, der von Anfang an unter meiner Nation in Jerusalem gewesen ist, wissen alle Juden*.", footnotes: ["℘ Kap. 22,3"] },
      { number: 5, text: "Sie kennen mich von der ersten Zeit her — wenn sie es bezeugen wollen —, dass ich nach der strengsten Sekte unserer Religion, als Pharisäer, lebte*.", footnotes: ["℘ Kap. 23,6"] },
      { number: 6, text: "Und nun stehe ich vor Gericht wegen der Hoffnung auf die von Gott an unsere Väter geschehene Verheißung*,", footnotes: ["℘ Kap. 23,6"] },
      { number: 7, text: "zu der unser zwölfstämmiges Volk, unablässig Nacht und Tag Gott dienend*, hinzugelangen hofft*. Wegen dieser Hoffnung, König, werde ich von den Juden angeklagt.", footnotes: ["℘ Kap. 24,15", "℘ Eph 1,12"] },
      { number: 8, text: "Warum wird es bei euch für etwas Unglaubliches gehalten, wenn Gott Tote auferweckt*?", footnotes: ["℘ Kap. 23,8; Lk 24,11"] },
      { number: 9, text: "Ich meinte freilich bei mir selbst, gegen den Namen Jesu, des Nazoräers*, viel Feindseliges tun zu müssen,", footnotes: ["eine andere Form für das bei Mk (und teilweise Lk) überlieferte »Nazarener«; vgl. auch Anm. zu Mt 2,23"] },
      { number: 10, text: "was ich auch in Jerusalem getan habe; und auch viele der Heiligen habe ich in Gefängnisse eingeschlossen, nachdem ich von den Hohenpriestern* die Vollmacht empfangen hatte; und wenn sie umgebracht wurden, so gab ich meine Stimme dazu.", footnotes: ["s. Anm. zu Kap. 22,30"] },
      { number: 11, text: "Und in allen Synagogen* zwang ich sie oftmals durch Strafen, zu lästern; und indem ich über die Maßen gegen sie wütete, verfolgte ich sie sogar bis in die ausländischen Städte*.", footnotes: ["w. durch alle Synagogen hin", "℘ Kap. 8,3"] },
      { number: 12, text: "Und als ich dabei mit Vollmacht und Erlaubnis von den Hohenpriestern nach Damaskus reiste," },
      { number: 13, text: "sah ich mitten am Tag auf dem Weg, König, vom Himmel her ein Licht, das den Glanz der Sonne übertraf, welches mich und die, die mit mir reisten, umstrahlte." },
      { number: 14, text: "Als wir aber alle zur Erde niedergefallen waren, hörte ich eine Stimme in hebräischer Mundart zu mir sagen: Saul, Saul, was verfolgst du mich? Es ist hart für dich, gegen den Stachel auszuschlagen!" },
      { number: 15, text: "Ich aber sprach: Wer bist du, Herr? Der Herr aber sprach: Ich bin Jesus, den du verfolgst." },
      { number: 16, text: "Aber richte dich auf und stelle dich auf deine Füße! Denn hierzu bin ich dir erschienen, dich zu einem Diener* und Zeugen dessen zu verordnen, was du gesehen hast*, wie auch dessen, worin ich dir erscheinen werde.", footnotes: ["℘ Eph 3,7", "℘ Kap. 22,14"] },
      { number: 17, text: "*Ich werde dich herausnehmen* aus dem Volk und den Nationen, zu denen ich dich sende*,", footnotes: ["w. Dich herausnehmend o. rettend", "w. Dich herausnehmend o. rettend", "℘ Jer 1,7; Röm 1,5"] },
      { number: 18, text: "ihre Augen zu öffnen*, dass sie sich bekehren von der Finsternis zum Licht* und von der Macht des Satans zu Gott*, damit sie Vergebung der Sünden empfangen* und ein Erbe unter denen, die durch den Glauben an mich geheiligt sind*.", footnotes: ["℘ Ps 146,8", "℘ Jes 49,6; 1Thes 5,5; 1Petr 2,9", "℘ Kol 1,13", "℘ Kap. 5,31", "℘ Kap. 20,32"] },
      { number: 19, text: "Daher, König Agrippa, war ich nicht ungehorsam der himmlischen Erscheinung," },
      { number: 20, text: "sondern verkündigte denen in Damaskus zuerst und in Jerusalem und in der ganzen Landschaft von Judäa und den Nationen, Buße zu tun* und sich zu Gott zu bekehren*, indem sie der Buße würdige Werke vollbrächten*.", footnotes: ["℘ Kap. 17,30", "℘ Kap. 2,38", "℘ Mt 3,8"] },
      { number: 21, text: "Deshalb haben mich die Juden im Tempel ergriffen und versucht, mich zu ermorden*.", footnotes: ["℘ Kap. 21,30.31"] },
      { number: 22, text: "Da ich nun Beistand von Gott erlangte, stehe ich bis zu diesem Tag* und bezeuge Klein und Groß — indem ich nichts sage außer dem, was auch die Propheten und Mose geredet haben, dass es geschehen werde* —,", footnotes: ["o. von Gott erlangte bis zu diesem Tag, stehe ich", "℘ Kap. 24,14; Lk 24,27; Röm 3,21"] },
      { number: 23, text: "dass der Christus leiden sollte*, dass er als Erster durch* Totenauferstehung* Licht verkündigen sollte, sowohl dem Volk als auch den Nationen*.", footnotes: ["℘ Kap. 3,18", "o. aus", "℘ Kol 1,18", "℘ Kap. 13,47"] },
      { number: 24, text: "Während er aber dies zur Verteidigung sagte, spricht Festus mit lauter Stimme: Du bist von Sinnen, Paulus! Die große Gelehrsamkeit bringt dich zum Wahnsinn." },
      { number: 25, text: "Paulus aber spricht: Ich bin nicht von Sinnen, hochedler Festus, sondern ich rede Worte der Wahrheit und der Besonnenheit." },
      { number: 26, text: "Denn der König weiß um diese Dinge, zu dem ich auch mit Freimütigkeit rede; denn ich bin überzeugt, dass ihm nichts hiervon verborgen ist, denn nicht in einem Winkel ist dies geschehen*.", footnotes: ["℘ Joh 18,20"] },
      { number: 27, text: "Glaubst du, König Agrippa, den Propheten? Ich weiß, dass du glaubst." },
      { number: 28, text: "Agrippa aber sprach zu Paulus: In kurzem überredest du mich, ein Christ zu werden*.", footnotes: ["℘ Kap. 11,26"] },
      { number: 29, text: "Paulus aber sprach: Ich möchte zu Gott beten, dass über kurz oder lang nicht allein du, sondern auch alle, die mich heute hören, solche werden, wie auch ich bin, ausgenommen diese Fesseln*.", footnotes: ["℘ 2Tim 2,9"] },
      { number: 30, text: "Und der König stand auf und der Statthalter und Berenike und die mit ihnen dasaßen." },
      { number: 31, text: "Und als sie sich zurückgezogen hatten, redeten sie miteinander und sagten: Dieser Mensch tut nichts, was des Todes oder der Fesseln wert wäre*.", footnotes: ["℘ Kap. 23,9"] },
      { number: 32, text: "Agrippa aber sprach zu Festus: Dieser Mensch hätte losgelassen werden können, wenn er sich nicht auf den Kaiser berufen hätte*.", footnotes: ["℘ Kap. 25,11"] },
    ]},
    { number: 27, verses: [
      { number: 1, text: "Als es aber beschlossen war, dass wir nach Italien absegeln sollten*, überlieferten sie sowohl Paulus als auch einige andere Gefangene einem Hauptmann mit Namen Julius von der Schar des Augustus*.", heading: "Beginn der Romreise", footnotes: ["℘ Kap. 25,25", "Ehrentitel militärischer Einheiten unter den römischen Hilfstruppen; s. auch die Anm. zu Kap. 25,21 und Mk 15,16"] },
      { number: 2, text: "Nachdem wir aber in ein adramyttisches Schiff gestiegen waren, das im Begriff stand, die Orte längs der Küste Asiens* zu befahren, fuhren wir ab; und es war bei uns Aristarch, ein Mazedonier aus Thessalonich*.", footnotes: ["d. i. die röm. Provinz Asien; vgl. auch Anm. zu Kap. 16,6", "℘ Kap. 19,29"] },
      { number: 3, text: "Und am anderen Tag legten wir in Sidon an. Und Julius behandelte den Paulus sehr wohlwollend und erlaubte ihm, zu den Freunden zu gehen, damit er ihrer Fürsorge teilhaftig wurde*.", footnotes: ["℘ Kap. 24,23"] },
      { number: 4, text: "Und von da fuhren wir ab und segelten unter Zypern hin, weil die Winde widrig waren." },
      { number: 5, text: "Und als wir das Meer von Zilizien und Pamphylien durchsegelt hatten, kamen wir nach Myra in Lyzien;" },
      { number: 6, text: "und als der Hauptmann dort ein alexandrinisches Schiff fand, das nach Italien segelte, brachte er uns auf dasselbe." },
      { number: 7, text: "Als wir aber viele Tage langsam segelten und mit Mühe in die Nähe von Knidos gekommen waren, segelten wir, da uns der Wind nicht heranließ, unter Kreta hin, gegen Salmone;" },
      { number: 8, text: "und als wir mit Mühe daran* entlangfuhren, kamen wir an einen Ort, Guthafen genannt, in dessen Nähe die Stadt Lasäa war.", footnotes: ["d. h. an der Insel Kreta"] },
      { number: 9, text: "Da aber viel Zeit verflossen und die Fahrt schon unsicher war, weil auch das Fasten schon vorüber war, mahnte Paulus", heading: "Sturm und Schiffbruch auf der Romreise" },
      { number: 10, text: "und sprach zu ihnen: Männer, ich sehe, dass die Fahrt mit Unheil und großem Schaden, nicht nur der Ladung und des Schiffes, sondern auch unseres Lebens, vor sich gehen wird." },
      { number: 11, text: "Der Hauptmann aber glaubte dem Steuermann und dem Schiffsherrn mehr als dem, was Paulus sagte." },
      { number: 12, text: "Da aber der Hafen zum Überwintern ungeeignet war, rieten die meisten dazu, von dort abzufahren, ob sie etwa nach Phönix gelangen und dort überwintern könnten, einem Hafen von Kreta, der gegen Südwesten und gegen Nordwesten sieht." },
      { number: 13, text: "Als aber ein Südwind sanft wehte, meinten sie, ihre Absicht erreicht zu haben, lichteten die Anker und fuhren näher an Kreta hin." },
      { number: 14, text: "Aber nicht lange danach erhob sich von dorther ein Sturmwind, Eurakylon* genannt.", footnotes: ["ein Nordostwind, der von den Bergen Kretas herabkam"] },
      { number: 15, text: "Als aber das Schiff mit fortgerissen wurde und dem Wind nicht widerstehen konnte, gaben wir es preis und ließen uns treiben." },
      { number: 16, text: "Als wir aber unter einer kleinen Insel, Kauda genannt, hinliefen, konnten wir kaum des Rettungsbootes mächtig werden." },
      { number: 17, text: "Dieses zogen sie herauf und wandten Hilfsmittel an, indem sie das Schiff umgürteten; und da sie fürchteten, in die Syrte* verschlagen zu werden, ließen sie das Takelwerk nieder und trieben so dahin.", footnotes: ["eine wegen Untiefen und Sandbänken gefürchtete Bucht an der afrikanischen Küste"] },
      { number: 18, text: "Da wir aber sehr unter dem Sturm litten, warfen sie am folgenden Tag Ladung über Bord;" },
      { number: 19, text: "und am dritten Tag warfen sie mit eigenen Händen das Schiffsgerät fort." },
      { number: 20, text: "Da aber viele Tage lang weder Sonne noch Sterne schienen und ein nicht geringes Unwetter uns bedrängte, schwand zuletzt alle Hoffnung auf unsere Rettung*.", footnotes: ["℘ 2Kor 11,26"] },
      { number: 21, text: "Und als man lange Zeit ohne Speise geblieben war, da stand Paulus in ihrer Mitte auf und sprach: Männer! Man hätte mir freilich gehorchen und nicht von Kreta abfahren und dieses Unglück und den Schaden vermeiden sollen." },
      { number: 22, text: "Und jetzt ermahne ich euch, guten Mutes zu sein, denn keiner von euch wird verloren gehen, nur das Schiff." },
      { number: 23, text: "Denn ein Engel des Gottes, dem ich gehöre* und dem ich diene, stand in dieser Nacht bei mir", footnotes: ["℘ Ps 119,94"] },
      { number: 24, text: "und sprach: Fürchte dich nicht, Paulus*! Du musst vor den Kaiser gestellt werden*; und siehe, Gott hat dir alle geschenkt, die mit dir fahren*.", footnotes: ["℘ Kap. 18,9", "℘ Kap. 23,11; Mt 10,18", "℘ V. 44"] },
      { number: 25, text: "Deshalb seid guten Mutes, ihr Männer! Denn ich vertraue Gott, dass es so sein wird, wie zu mir geredet worden ist." },
      { number: 26, text: "Wir müssen aber auf irgendeine Insel verschlagen werden*.", footnotes: ["℘ Kap. 28,1"] },
      { number: 27, text: "Als aber die vierzehnte Nacht gekommen war und wir im Adriatischen Meer* umhertrieben, meinten gegen Mitternacht die Matrosen, dass sich ihnen Land näherte.", footnotes: ["Das Ionische Meer zwischen Griechenland und Süditalien wurde im Altertum oft zum Adriatischen Meer gerechnet."] },
      { number: 28, text: "Und als sie das Senkblei ausgeworfen hatten, fanden sie zwanzig Faden*; nachdem sie aber ein wenig weiter gefahren waren und das Senkblei wieder ausgeworfen hatten, fanden sie fünfzehn Faden.", footnotes: ["ein seemännisches Maß von etwa 185 cm"] },
      { number: 29, text: "Und da sie fürchteten, wir möchten etwa auf felsige Stellen verschlagen werden, warfen sie vom Hinterschiff vier Anker aus und wünschten, dass es Tag würde." },
      { number: 30, text: "Als aber die Matrosen aus dem Schiff zu fliehen suchten und das Boot unter dem Vorwand, als wollten sie vom Vorderschiff Anker auswerfen, in das Meer hinabließen," },
      { number: 31, text: "sprach Paulus zu dem Hauptmann und den Soldaten: Wenn diese nicht im Schiff bleiben, könnt ihr nicht gerettet werden." },
      { number: 32, text: "Dann hieben die Soldaten die Taue des Bootes ab und ließen es hinabfallen." },
      { number: 33, text: "Als es aber Tag werden wollte, ermahnte Paulus alle, Speise zu sich zu nehmen, und sprach: Heute schon den vierzehnten Tag wartend, seid ihr ohne Essen geblieben, weil ihr nichts zu euch genommen habt." },
      { number: 34, text: "Deshalb ermahne ich euch, Speise zu euch zu nehmen, denn dies gehört zu eurer Rettung; denn keinem von euch wird ein Haar des Hauptes verloren gehen*.", footnotes: ["℘ Lk 21,18"] },
      { number: 35, text: "Und als er dies gesagt und Brot genommen hatte, dankte er Gott vor allen, und als er es gebrochen hatte, begann er zu essen*.", footnotes: ["℘ 1Tim 4,4.5"] },
      { number: 36, text: "Alle aber wurden guten Mutes und nahmen auch selbst Speise zu sich." },
      { number: 37, text: "Wir waren aber in dem Schiff, alle Seelen, zweihundertsechsundsiebzig." },
      { number: 38, text: "Als sie sich aber mit Speise gesättigt hatten, erleichterten sie das Schiff, indem sie den Weizen in das Meer warfen." },
      { number: 39, text: "Als es aber Tag wurde, erkannten sie das Land nicht; sie bemerkten aber eine Bucht, die einen Strand hatte, auf den sie, wenn möglich, das Schiff zu treiben gedachten." },
      { number: 40, text: "Und als sie die Anker gekappt hatten, ließen sie sie im Meer und machten gleichzeitig die Haltetaue der Steuerruder los und hissten das Vordersegel vor den Wind und hielten auf den Strand zu." },
      { number: 41, text: "Da sie aber auf eine Landzunge gerieten, ließen sie das Schiff stranden; und das Vorderschiff saß fest und blieb unbeweglich, das Hinterschiff aber wurde von der Gewalt der Wellen zerschellt." },
      { number: 42, text: "Der Soldaten Plan aber war, die Gefangenen zu töten, damit nicht jemand fortschwimmen und entfliehen möchte." },
      { number: 43, text: "Der Hauptmann aber, der Paulus retten wollte, hinderte sie an ihrem Vorhaben und befahl, dass die, welche schwimmen könnten, sich zuerst hinabwerfen und an Land gehen sollten" },
      { number: 44, text: "und die Übrigen teils auf Brettern, teils auf Stücken vom Schiff. Und so geschah es, dass alle an das Land gerettet wurden*.", footnotes: ["℘ V. 24"] },
    ]},
    { number: 28, verses: [
      { number: 1, text: "Und als wir gerettet waren, da erfuhren wir, dass die Insel Melite* heiße*.", heading: "Aufenthalt auf Melite", footnotes: ["viell. Malta", "℘ Kap. 27,26"] },
      { number: 2, text: "Die Eingeborenen* aber erwiesen uns eine nicht gewöhnliche Freundlichkeit, denn sie zündeten ein Feuer an und nahmen uns alle zu sich wegen des eingetretenen Regens und wegen der Kälte*.", footnotes: ["w. Barbaren; so wurden von den Griechen und Römern alle Völker genannt, die nicht griech. oder röm. Abstammung waren und eine fremde Sprache redeten", "℘ 2Kor 11,27"] },
      { number: 3, text: "Als aber Paulus eine Menge Reisig zusammenraffte und auf das Feuer legte, kam infolge der Hitze eine Giftschlange heraus und hängte sich an seine Hand." },
      { number: 4, text: "Als aber die Eingeborenen* das Tier an seiner Hand hängen sahen, sagten sie zueinander: Jedenfalls ist dieser Mensch ein Mörder, den Dike*, obschon er aus dem Meer gerettet ist, nicht leben lässt.", footnotes: ["w. Barbaren; so wurden von den Griechen und Römern alle Völker genannt, die nicht griech. oder röm. Abstammung waren und eine fremde Sprache redeten", "bei den Griechen die Göttin der Rache"] },
      { number: 5, text: "Er nun schüttelte das Tier in das Feuer ab und erlitt nichts Schlimmes*.", footnotes: ["℘ Lk 10,19"] },
      { number: 6, text: "Sie aber erwarteten, dass er anschwellen oder plötzlich tot hinfallen werde. Als sie aber lange warteten und sahen, dass ihm nichts Ungewöhnliches geschah, änderten sie ihre Meinung und sagten, er sei ein Gott*.", footnotes: ["℘ Kap. 14,11"] },
      { number: 7, text: "In der Umgebung jenes Ortes aber besaß der Erste* der Insel, mit Namen Publius, Ländereien; der nahm uns auf und beherbergte uns drei Tage freundlich.", footnotes: ["Titel des Statthalters"] },
      { number: 8, text: "Es geschah aber, dass der Vater des Publius, von Fieber und Ruhr befallen, daniederlag. Zu dem ging Paulus hinein, und als er gebetet hatte, legte er ihm die Hände auf und heilte ihn*.", footnotes: ["℘ Lk 10,19"] },
      { number: 9, text: "Als dies aber geschehen war, kamen auch die Übrigen auf der Insel, die Krankheiten hatten, herbei und wurden geheilt*;", footnotes: ["℘ Kap. 5,16"] },
      { number: 10, text: "diese erwiesen uns auch viele Ehren, und als wir abfuhren, luden sie uns auf, was uns nötig war." },
      { number: 11, text: "Nach drei Monaten aber fuhren wir ab in einem alexandrinischen Schiff mit dem Zeichen der Dioskuren*, das auf der Insel überwintert hatte.", heading: "Weiterreise nach Rom", footnotes: ["Götterbild am Bug des Schiffes mit den Zwillingssöhnen des Zeus, Kastor und Pollux"] },
      { number: 12, text: "Und als wir in Syrakus gelandet waren, blieben wir drei Tage." },
      { number: 13, text: "Von dort fuhren wir in einem Bogen und kamen nach Rhegion; und da nach einem Tag sich Südwind erhob, kamen wir den zweiten Tag nach Puteoli," },
      { number: 14, text: "wo wir Brüder fanden und gebeten wurden, sieben Tage bei ihnen zu bleiben*; und so kamen wir nach Rom*.", footnotes: ["℘ Kap. 20,6", "℘ Röm 1,7"] },
      { number: 15, text: "Und von dort kamen die Brüder, als sie von uns gehört hatten, uns bis Forum-Appii und Tres-Tabernae entgegen; und als Paulus sie sah, dankte er Gott und fasste Mut." },
      { number: 16, text: "Als wir aber nach Rom kamen*, wurde dem Paulus erlaubt, mit dem Soldaten, der ihn bewachte, für sich zu bleiben*.", footnotes: ["Andere Handschr. fügen hinzu: übergab der Hauptmann die Gefangenen dem Befehlshaber des Lagers (d. h. dem Kommandeur der kaiserlichen Leibgarde), aber es\n℘ Röm 1,7", "℘ Kap. 24,23"] },
      { number: 17, text: "Es geschah aber nach drei Tagen, dass er die, welche die Ersten der Juden waren, zusammenrief. Als sie aber zusammengekommen waren, sprach er zu ihnen: Ihr Brüder*! Ich, der ich nichts gegen das Volk oder die väterlichen Gebräuche getan habe*, bin gefangen aus Jerusalem in die Hände der Römer überliefert worden*.", heading: "Gefangenschaft und Wirken des Paulus in Rom", footnotes: ["w. Männer, Brüder (ein Hebraismus, gew. bei der Anrede verwendet)", "℘ Kap. 24,12", "℘ Kap. 23,35"] },
      { number: 18, text: "Die wollten mich, nachdem sie mich verhört hatten, loslassen, weil keine todeswürdige Schuld an mir war*.", footnotes: ["℘ Kap. 23,9"] },
      { number: 19, text: "Als aber die Juden widersprachen, war ich gezwungen, mich auf den Kaiser zu berufen*, nicht als hätte ich gegen meine Nation etwas zu klagen.", footnotes: ["℘ Kap. 25,11"] },
      { number: 20, text: "Um dieser Ursache willen nun habe ich euch herbeigerufen, euch zu sehen und zu euch zu reden; denn wegen der Hoffnung Israels trage ich diese Kette*.", footnotes: ["℘ Kap. 23,6; Phil 1,13"] },
      { number: 21, text: "Sie aber sprachen zu ihm: Wir haben über dich weder Briefe von Judäa empfangen, noch ist jemand von den Brüdern hergekommen und hat uns über dich etwas Böses berichtet oder gesagt." },
      { number: 22, text: "Aber wir begehren von dir zu hören, welche Gesinnung du hast; denn von dieser Sekte* ist uns bekannt, dass ihr überall widersprochen wird.", footnotes: ["℘ Kap. 24,5"] },
      { number: 23, text: "Als sie ihm aber einen Tag bestimmt hatten, kamen mehrere zu ihm in die Herberge, denen er das Reich* Gottes auslegte* und bezeugte*. Und er suchte sie zu überzeugen von Jesus, sowohl aus dem Gesetz Moses als auch den Propheten, von frühmorgens bis zum Abend.", footnotes: ["o. die Königsherrschaft", "℘ Kap. 17,3", "℘ Kap. 1,3"] },
      { number: 24, text: "Und einige wurden überzeugt von dem, was gesagt wurde*, andere aber glaubten nicht*.", footnotes: ["℘ Kap. 17,4", "℘ 2Thes 3,2"] },
      { number: 25, text: "Als sie aber unter sich uneins waren, gingen sie weg, als Paulus ein Wort sprach: Trefflich hat der Heilige Geist durch Jesaja, den Propheten, zu euren Vätern geredet" },
      { number: 26, text: "und gesagt: »Geh hin zu diesem Volk und sprich: Hörend* werdet ihr hören und nicht verstehen, und sehend werdet ihr sehen und nicht wahrnehmen.", footnotes: ["w. Mit Gehör"] },
      { number: 27, text: "Denn das Herz dieses Volkes ist dick geworden, und mit den Ohren haben sie schwer gehört, und ihre Augen haben sie geschlossen, damit sie nicht etwa mit den Augen sehen und mit den Ohren hören und mit dem Herzen verstehen und sich bekehren und ich sie heile.«*", footnotes: ["℘ Jes 6,9.10; Mt 13,14.15"] },
      { number: 28, text: "So sei euch nun kund, dass dieses Heil* Gottes den Nationen gesandt ist*; sie werden auch hören.", footnotes: ["o. diese Rettung", "℘ Kap. 13,46.47"] },
      { number: 29, text: "[T>]*", footnotes: ["Andere Handschr. fügen hinzu: Und als er dies gesagt hatte, gingen die Juden weg und hatten viel Wortwechsel untereinander."] },
      { number: 30, text: "Er aber blieb zwei ganze Jahre in seiner eigenen Mietwohnung und nahm alle auf, die zu ihm kamen*;", footnotes: ["℘ Kap. 24,23"] },
      { number: 31, text: "er predigte das Reich* Gottes* und lehrte die Dinge, die den Herrn Jesus Christus betreffen, mit aller Freimütigkeit ungehindert*.", footnotes: ["o. die Königsherrschaft", "℘ Lk 9,2", "℘ Eph 6,20"] },
    ]},
  ]
};
